window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s3-507","number":507,"surah":3,"verses":[144],"verseLabel":"آل عمران: 144","question":"لماذا كرر فعل الانقلاب في ﴿ومن ينقلب على عقبيه فلن يضر الله شيئًا﴾؟","answer":"أعاد فعل الانقلاب أولًا في الاستفهام لتقبيح وقوعه، ثم في الشرط لبيان عاقبته العامة: من يرجع لا يضر الله شيئًا بل تعود الخسارة عليه؛ فانتقل من العتاب إلى تقرير قاعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص33–48.","url":""}]},{"id":"s3-508","number":508,"surah":3,"verses":[144],"verseLabel":"آل عمران: 144","question":"لماذا ختم بـ﴿وسيجزي الله الشاكرين﴾ لا الصابرين أو الثابتين؟","answer":"الشاكرون هم الذين يعرفون نعمة الرسالة فيثبتون على الدين بعد غياب الرسول ولا ينقلبون على أعقابهم؛ فالثبات هنا أثر الشكر، ولذلك كان أوسع من ذكر الصابرين وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص42.","url":""}]},{"id":"s3-509","number":509,"surah":3,"verses":[145],"verseLabel":"آل عمران: 145","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان لنفس أن تموت إلا بإذن الله﴾؟","answer":"صيغة ﴿وَمَا كَانَ لِنَفْسٍ﴾ تنفي إمكان استقلال أي نفس بالموت، والاستثناء ﴿إِلَّا بِإِذْنِ اللَّهِ﴾ يقصر وقوعه على قضائه؛ فلا الإقدام يعجل الأجل ولا الإحجام يؤخره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص48–58.","url":""}]},{"id":"s3-510","number":510,"surah":3,"verses":[145],"verseLabel":"آل عمران: 145","question":"لماذا سمّى أجل الموت ﴿كتابًا مؤجلًا﴾؟","answer":"الكتاب هو الأمر المكتوب المحكم الذي لا يتخلف، و﴿مُؤَجَّلًا﴾ أي محددًا بوقت معلوم؛ فاجتمع في التعبير ثبوت الأجل وتعيين موعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص48–58.","url":""}]},{"id":"s3-511","number":511,"surah":3,"verses":[145],"verseLabel":"آل عمران: 145","question":"لماذا كرر ﴿نؤته منها﴾ في ثواب الدنيا وثواب الآخرة؟","answer":"كرر ﴿نُؤْتِهِ مِنْهَا﴾ ليفصل الجزاءين بحسب اختلاف الإرادة، ويقرر أن طالب الدنيا لا ينال منها إلا ما يؤتيه الله، وأن طالب الآخرة يؤتى من ثوابها؛ فالتكرار يقيم مقابلة متوازنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص48–58.","url":""}]},{"id":"s3-512","number":512,"surah":3,"verses":[145],"verseLabel":"آل عمران: 145","question":"لماذا خُتمت الآية مرة أخرى بـ﴿وسنجزي الشاكرين﴾؟","answer":"تكررت خاتمة الشاكرين بعد الآية السابقة لتصل الثبات عند موت الرسول بصحة قصد العمل: فالشاكر لا ينقلب، ولا يجعل الجهاد وسيلة للدنيا، ولذلك وُعد بالجزاء مرة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص48–58.","url":""}]},{"id":"s3-513","number":513,"surah":3,"verses":[146],"verseLabel":"آل عمران: 146","question":"ما سرّ التعبير في قوله تعالى: ﴿وكأين من نبي قاتل معه ربيون كثير﴾؟","answer":"﴿كَأَيِّنْ﴾ تفيد التكثير: كم من نبي قاتل معه جماعات كثيرة من الربانيين، فلم توهنهم المصائب. واستحضار كثرة النظائر السابقة يعزي المؤمنين ويقيم لهم قدوة عملية بعد أُحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص58–71.","url":""}]},{"id":"s3-514","number":514,"surah":3,"verses":[146],"verseLabel":"آل عمران: 146","question":"لماذا جمع بين ﴿فما وهنوا﴾ و﴿وما ضعفوا﴾ و﴿وما استكانوا﴾؟","answer":"نفى فتور العزم، ثم ضعف القدرة، ثم الخضوع للعدو؛ فاستوعب مراحل الانكسار النفسية والعملية والظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص68–69.","url":""}]},{"id":"s3-515","number":515,"surah":3,"verses":[146],"verseLabel":"آل عمران: 146","question":"لماذا ختم بـ﴿والله يحب الصابرين﴾؟","answer":"ختم بالمحبة لأن نفي الوهن والضعف والاستكانة ثمرة الصبر عند المصيبة؛ فوصفهم بالصفة الجامعة لأفعالهم، وجعل محبة الله أعلى جزاء معنوي لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص58–71.","url":""}]},{"id":"s3-516","number":516,"surah":3,"verses":[147],"verseLabel":"آل عمران: 147","question":"لماذا حُصر قولهم في الدعاء ﴿وما كان قولهم إلا أن قالوا﴾؟","answer":"القصر يبين أن جوابهم عند الشدة لم يكن جزعًا ولا اعتراضًا، وإنما رجوعًا إلى الله بالدعاء؛ فكأن جميع كلامهم انحصر في الاعتراف والتوبة وطلب الثبات والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص71–81.","url":""}]},{"id":"s3-517","number":517,"surah":3,"verses":[147],"verseLabel":"آل عمران: 147","question":"لماذا بدأوا بطلب مغفرة الذنوب قبل طلب تثبيت الأقدام والنصر؟","answer":"رأوا الذنب سببًا يحجب التأييد، فبدؤوا بإصلاح الصلة بالله، ثم سألوا الثبات، ثم ثمرة الثبات وهي النصر؛ فرتبوا الدعاء من الداخل إلى الخارج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص71–81.","url":""}]},{"id":"s3-518","number":518,"surah":3,"verses":[147],"verseLabel":"آل عمران: 147","question":"ما دلالة عطف ﴿وإسرافنا في أمرنا﴾ على ﴿ذنوبنا﴾ في دعائهم؟","answer":"الذنوب تشمل المعاصي، أما الإسراف فهو تجاوز الحد والمبالغة في الأمر؛ فعطفه تخصيص لأشد الذنوب أو تأكيد للاعتراف بما جاوزوا فيه حد الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص71–81.","url":""}]},{"id":"s3-519","number":519,"surah":3,"verses":[147],"verseLabel":"آل عمران: 147","question":"لماذا صوّر الثبات بقوله ﴿وثبت أقدامنا﴾؟","answer":"ثبات الأقدام كناية عن الثبات في الموقف وعدم الفرار، وهي صورة تناسب ميدان القتال؛ فثبات البدن الظاهر دليل ثبات القلب والعزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص71–81.","url":""}]},{"id":"s3-520","number":520,"surah":3,"verses":[148],"verseLabel":"آل عمران: 148","question":"ما سرّ التعبير في قوله تعالى: ﴿فآتاهم الله ثواب الدنيا وحسن ثواب الآخرة﴾؟","answer":"الفاء تفيد أن الإيتاء جاء ثمرةً لدعائهم وثباتهم، وجمع لهم ثواب الدنيا من النصر والعزة وثواب الآخرة الباقي؛ فدل على أن إخلاصهم لم يحرمهم خير الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص81–88.","url":""}]},{"id":"s3-521","number":521,"surah":3,"verses":[148],"verseLabel":"آل عمران: 148","question":"لماذا وصف ثواب الآخرة وحده بـ﴿حسن﴾؟","answer":"لم يوصف ثواب الدنيا بالحسن لأن خيرها محدود وقد يخالطه ما يكره الإنسان، أما ثواب الآخرة فحسن خالص دائم؛ فخص بالوصف تعظيمًا وبيانًا لفضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص81–88.","url":""}]},{"id":"s3-522","number":522,"surah":3,"verses":[148],"verseLabel":"آل عمران: 148","question":"لماذا ختم بـ﴿والله يحب المحسنين﴾ بعد وصف الصابرين؟","answer":"الصبر منعهم من الوهن والاستكانة، ثم تجاوزوا ذلك إلى إحسان العمل والدعاء والجهاد؛ فانتقل الوصف من الصابرين إلى المحسنين، وختم بمحبة الله لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص81–88.","url":""}]},{"id":"s3-523","number":523,"surah":3,"verses":[149],"verseLabel":"آل عمران: 149","question":"لماذا كرر النداء ﴿يا أيها الذين آمنوا﴾ قبل التحذير من طاعة الكافرين؟","answer":"جدد النداء لتنبيه المؤمنين إلى انتقال السياق من عرض قدوة الربانيين إلى تحذير مباشر يمس مصير إيمانهم، وناداهم بوصف الإيمان ليستنهضهم إلى ما يقتضيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص88–95.","url":""}]},{"id":"s3-524","number":524,"surah":3,"verses":[149],"verseLabel":"آل عمران: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿يردوكم على أعقابكم﴾ لا: عن دينكم؟","answer":"صُور الرجوع عن الدين بردّ الإنسان على عقبيه؛ فهو يعود إلى الوراء بعد أن تقدم، وفي الصورة إهانة للخضوع للكافرين وبيان لضياع الطريق الذي قطعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص88–95.","url":""}]},{"id":"s3-525","number":525,"surah":3,"verses":[149],"verseLabel":"آل عمران: 149","question":"ما سرّ التعبير في قوله تعالى: ﴿فتنقلبوا خاسرين﴾ فجاء بالفاء؟","answer":"الفاء تجعل الخسران نتيجة سريعة مترتبة على طاعة الكافرين والرد على الأعقاب؛ فما إن يقع الارتداد حتى يتحقق الانقلاب بالخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص88–95.","url":""}]},{"id":"s3-526","number":526,"surah":3,"verses":[150],"verseLabel":"آل عمران: 150","question":"لماذا أضرب عن طاعة الكافرين بقوله ﴿بل الله مولاكم﴾؟","answer":"﴿بَلْ﴾ تبطل ما قد يوهمه التحذير من طلب الحماية عند الكافرين، وتثبت البديل الحق: الله وحده مولاكم؛ فلا طاعة لمن يردكم عن الدين مع وجود ولايته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص95–99.","url":""}]},{"id":"s3-527","number":527,"surah":3,"verses":[150],"verseLabel":"آل عمران: 150","question":"لماذا أفرد الولاية لله ثم قال ﴿وهو خير الناصرين﴾ بالجمع؟","answer":"أفرد ﴿مَوْلَاكُمْ﴾ لأن الولاية الحقيقية لله وحده، ثم جاء ﴿النَّاصِرِينَ﴾ جمعًا باعتبار من يُظن فيهم النصر؛ فهو خير كل من يُطلب منه نصر، ولا مساواة في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص95–99.","url":""}]},{"id":"s3-528","number":528,"surah":3,"verses":[151],"verseLabel":"آل عمران: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿سنلقي في قلوب الذين كفروا الرعب﴾، فجعل الرعب شيئًا يُلقى؟","answer":"جُسّم الرعب شيئًا يُلقى في مستقر الإدراك والإرادة، فيسبق انهيار القلب انهيار الصفوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص99–107.","url":""}]},{"id":"s3-529","number":529,"surah":3,"verses":[151],"verseLabel":"آل عمران: 151","question":"لماذا خُصّت القلوب بإلقاء الرعب؟","answer":"لأن هزيمة الصف تبدأ من انهيار مركز الإدراك والإرادة؛ فإذا استقر الرعب في القلب تعطلت أسباب القوة ولو بقي السلاح والعدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص99–107.","url":""}]},{"id":"s3-530","number":530,"surah":3,"verses":[151],"verseLabel":"آل عمران: 151","question":"لماذا عُلّل الرعب بقوله ﴿بما أشركوا بالله ما لم ينزل به سلطانًا﴾؟","answer":"جعل الإشراك بلا سلطان سببًا للرعب لأن من عبد ما لا حجة عليه فقد حرم قلبه سند الحق واليقين؛ فناسب اضطراب الباطن فساد الأصل الذي قام عليه اعتقاده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص99–107.","url":""}]},{"id":"s3-531","number":531,"surah":3,"verses":[151],"verseLabel":"آل عمران: 151","question":"لماذا سمّى الحجة ﴿سلطانًا﴾؟","answer":"السلطان في الأصل القوة والتمكن، فسميت الحجة سلطانًا لأنها تقهر الباطل وتملك النفس بإلزامها؛ والمعنى أن شركهم لا يقوم على أدنى برهان منزل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص99–107.","url":""}]},{"id":"s3-532","number":532,"surah":3,"verses":[151],"verseLabel":"آل عمران: 151","question":"ما سرّ التعبير في قوله تعالى: ﴿ومأواهم النار﴾، فجعل النار مأوى؟","answer":"المأوى هو المكان الذي يلجأ إليه المرء طلبًا للأمن، فجُعلت النار مأواهم على سبيل التهكم المرير: لا ملجأ لهم في الآخرة إلا موضع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص99–107.","url":""}]},{"id":"s3-533","number":533,"surah":3,"verses":[151],"verseLabel":"آل عمران: 151","question":"لماذا ختم بـ﴿وبئس مثوى الظالمين﴾ بعد ﴿مأواهم النار﴾؟","answer":"﴿مَأْوَاهُمُ النَّارُ﴾ يبين مقرهم، ثم أسلوب الذم ﴿وَبِئْسَ مَثْوَى الظَّالِمِينَ﴾ يقبح هذا المقام ويقرر دوام الإقامة فيه؛ فزاد الحكم وصفًا وتقريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص99–107.","url":""}]},{"id":"s3-534","number":534,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد صدقكم الله وعده﴾ مع أن المسلمين لم ينتصروا آخر المعركة؟","answer":"صدق الوعد تحقق في أول المعركة حين أخذ المؤمنون يقتلون المشركين بإذن الله؛ ثم تغيرت الحال عندما فشل بعضهم وتنازعوا وعصوا. فالهزيمة المتأخرة لم تكن إخلافًا للوعد بل نتيجة لتغير شرط الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-535","number":535,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"لماذا اختير ﴿تحسونهم﴾ في وصف قتل المشركين؟","answer":"الحس هو القتل الذريع المستأصل، فـ﴿تَحُسُّونَهُمْ﴾ أبلغ من «تقتلونهم» في تصوير شدة ما أصاب المشركين أول المعركة وتجدد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-536","number":536,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى إذا فشلتم وتنازعتم في الأمر وعصيتم﴾، ورتب هذه الأفعال هكذا؟","answer":"بدأ بالفشل، وهو ضعف النفس؛ فنشأ عنه التنازع في أمر الموقع، ثم انتهى إلى العصيان العملي بمخالفته. فالترتيب يرسم انتقال الخلل من الباطن إلى اختلاف الجماعة ثم إلى الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-537","number":537,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما أراكم ما تحبون﴾ بدل: بعد النصر؟","answer":"﴿مَا تُحِبُّونَ﴾ تشمل أمارات النصر والغنيمة التي رأوها، وتكشف في الوقت نفسه موضع الاختبار في رغباتهم؛ فهي أبلغ تربويًا من تسمية النصر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-538","number":538,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿منكم من يريد الدنيا ومنكم من يريد الآخرة﴾؟","answer":"كرر ﴿مِنْكُمْ مَنْ﴾ ليقسم الجماعة بإنصاف بحسب الباعث: فريق أراد الغنيمة، وفريق ثبت يريد ثواب الآخرة؛ فلا يعمم العتاب على المؤمنين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-539","number":539,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"لماذا صُوّر الانصراف عن العدو بقوله ﴿ثم صرفكم عنهم﴾؟","answer":"﴿صَرَفَكُمْ عَنْهُمْ﴾ تصور انتقالهم من الإقبال على العدو والغلبة إلى الانكفاف والانهزام بعد مخالفة الأمر، ونسبة الصرف إلى الله تبين جريان النتيجة بقدره حين تغيرت أسباب النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-540","number":540,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"ما سرّ التعبير في قوله تعالى: ﴿ليبتليكم﴾ بعد ذكر المعصية والهزيمة؟","answer":"لم تكن الهزيمة انتقامًا مجردًا، بل ابتلاء يكشف النيات والطاعة والصبر ويهذب الجماعة؛ فجاء التعليل بعد ذكر الصرف لبيان الحكمة التربوية من المحنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-541","number":541,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"لماذا أعقب العتاب فورًا بقوله ﴿ولقد عفا عنكم﴾؟","answer":"أكد العفو باللام و﴿قَدْ﴾ عقب تفصيل الخطأ حتى لا يتحول العتاب إلى يأس، وليبين أن المقصود إصلاح الجماعة لا إقصاؤها؛ فقد علم الله ندمهم فعفا عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-542","number":542,"surah":3,"verses":[152],"verseLabel":"آل عمران: 152","question":"لماذا ختم بـ﴿والله ذو فضل على المؤمنين﴾ لا: غفور لهم؟","answer":"العفو المذكور مظهر من فضل أوسع يشمل بقاء الإيمان والتوبة والتربية والتأييد؛ لذلك ختم بـ﴿ذُو فَضْلٍ عَلَى الْمُؤْمِنِينَ﴾ ولم يقصر المعنى على المغفرة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص107–121.","url":""}]},{"id":"s3-543","number":543,"surah":3,"verses":[153],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ تصعدون ولا تلوون على أحد﴾، وما صورة الصعود وعدم الالتفات؟","answer":"﴿تُصْعِدُونَ﴾ تصور ابتعادهم مسرعين في الأرض أو صعودهم في جهة الجبل، و﴿لَا تَلْوُونَ عَلَى أَحَدٍ﴾ تنفي حتى الالتفات أو التوقف لإنقاذ غيرهم؛ فترسم شدة الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص121–131.","url":""}]},{"id":"s3-544","number":544,"surah":3,"verses":[153],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿والرسول يدعوكم في أخراكم﴾؟","answer":"الجملة الحالية تجعل المشهد متزامنًا: هم يبتعدون، والرسول ﷺ ثابت في آخرهم يناديهم إلى الرجوع. و﴿فِي أُخْرَاكُمْ﴾ تبين أنه كان خلف المنهزمين، فتبرز المفارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص121–131.","url":""}]},{"id":"s3-545","number":545,"surah":3,"verses":[153],"verseLabel":"آل عمران: 153","question":"ما سرّ التعبير في قوله تعالى: ﴿فأثابكم غمًا بغم﴾، وسمّى الغم ثوابًا؟","answer":"سُمي الغم ثوابًا على سبيل المشاكلة أو التهكم؛ لأنه جزاء ترتب على الفشل والتنازع والعصيان. والباء في ﴿بِغَمٍّ﴾ تفيد غمًا متصلًا بغم أو واقعًا في مقابله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص121–131.","url":""}]},{"id":"s3-546","number":546,"surah":3,"verses":[153],"verseLabel":"آل عمران: 153","question":"لماذا نُكّر ﴿غمًا بغم﴾؟","answer":"تنكير الغمين يفيد تعظيمهما ويتركهما شاملين لما اجتمع يومئذ من فوات النصر والغنيمة، والقتل والجراح، وإشاعة مقتل الرسول ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص121–131.","url":""}]},{"id":"s3-547","number":547,"surah":3,"verses":[153],"verseLabel":"آل عمران: 153","question":"لماذا عُلّل ذلك بقوله ﴿لكيلا تحزنوا على ما فاتكم ولا ما أصابكم﴾؟","answer":"من وجوه المعنى أن الغم الأكبر شغلهم عما فاتهم وعما أصابهم، فهان ما عداه؛ وفي المحنة تدريب لهم على ألا يستسلموا للحزن على فائت أو مصاب، ولا يلغي ذلك كونها أثرًا لخطئهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص121–131.","url":""}]},{"id":"s3-548","number":548,"surah":3,"verses":[153],"verseLabel":"آل عمران: 153","question":"لماذا قدّم ما فات على ما أصاب؟","answer":"لأن حزنهم بدأ بالغنيمة أو النصر الفائت ثم اشتد بالمصاب اللاحق؛ فرتب العلاج بحسب وقوع داعيي الحزن في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص121–131.","url":""}]},{"id":"s3-549","number":549,"surah":3,"verses":[153],"verseLabel":"آل عمران: 153","question":"لماذا ختم بـ﴿والله خبير بما تعملون﴾؟","answer":"الخبير هو العالم بدقائق الأمور وبواطنها؛ فناسب ختام آية كشفت الفشل والتنازع واختلاف إرادة الدنيا والآخرة، وأكد أن دوافع الأعمال وتفاصيلها معلومة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص121–131.","url":""}]},{"id":"s3-550","number":550,"surah":3,"verses":[23],"verseLabel":"آل عمران: 153؛ الحديد: 23","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿لكيلا تحزنوا على ما فاتكم﴾، وقوله تعالى في الحديد ﴿لكيلا تأسوا على ما فاتكم﴾؟","answer":"حزن أحد كان ألمًا حيًا متصلًا بهزيمة ومصاب قريب، فناسبه ﴿تحزنوا﴾؛ أما الحديد فيقرر قاعدة عامة في القدر ومتاع الدنيا، فاختير الأسى وهو حزن يمتد على الفائت ويتعلق به القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص226، الحديد: 23 في المقارنة بآل عمران: 153.","url":""}]},{"id":"s3-551","number":551,"surah":3,"verses":[23],"verseLabel":"آل عمران: 153؛ الحديد: 23","question":"لماذا لم تذكر آل عمران بعد ﴿لكيلا تحزنوا على ما فاتكم﴾ مقابل الحديد ﴿ولا تفرحوا بما آتاكم﴾؟","answer":"مقام آل عمران علاج جرح أحد، فالعناية منصبة على الحزن بالمفقود والمصاب، ولم يكن مقام زهو بالنعمة؛ أما الحديد فيربي على التوازن العام بين الفقد والعطاء، فذكر طرفي الأسى والفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص226، الحديد: 23 في المقارنة بآل عمران: 153.","url":""}]},{"id":"s3-552","number":552,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم أنزل عليكم من بعد الغم أمنة نعاسًا﴾، فجعل النعاس أمنة منزلة؟","answer":"صُورت الأمنة نعمةً تنزل عليهم من عند الله بعد طبقات الغم، وفسرها ﴿نُعَاسًا﴾؛ فالنعاس نفسه علامة الأمن، إذ لا يغلب في موطن الخوف إلا قلبًا سكن واضطرابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-553","number":553,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا غشي النعاس طائفة ولم يغش الطائفة الأخرى؟","answer":"الأمنة نزلت على من صدق توكله فسكنت نفسه، أما من أهمتهم أنفسهم وساء ظنهم بالله فظل القلق مستوليًا عليهم؛ فصار النعاس كاشفًا لحال القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-554","number":554,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى عن الطائفة الأخرى ﴿قد أهمتهم أنفسهم﴾؟","answer":"﴿أَهَمَّتْهُمْ أَنْفُسُهُمْ﴾ أي استأثرت نفوسهم بكل همهم فلم ينشغلوا إلا بسلامتهم، بخلاف الطائفة التي اطمأنت إلى الله؛ وفي التعبير كشف للأنانية التي غذت خوفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-555","number":555,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا وصف ظنهم بأنه ﴿غير الحق ظن الجاهلية﴾؟","answer":"﴿غَيْرَ الْحَقِّ﴾ يبطل ظنهم، ثم ﴿ظَنَّ الْجَاهِلِيَّةِ﴾ يكشف أصله: تصور أن الله لا ينصر رسوله أو أن تدبيره تابع لرأيهم، وهو ظن ناشئ من الجهل بالله ووعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-556","number":556,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا سألوا ﴿هل لنا من الأمر من شيء﴾ في صورة استفهام؟","answer":"هو استفهام اعتراض وتشكيك من أصحاب الظن، يوحي بأنهم حُرموا التدبير؛ فجاء الجواب بقصر الأمر كله على الله وكشف ما يخفونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-557","number":557,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا جاء الرد ﴿قل إن الأمر كله لله﴾ بتوكيد وعموم؟","answer":"أكدت ﴿إِنَّ﴾ الحكم في مواجهة اعتراضهم، و﴿كُلَّهُ﴾ رفعت احتمال أن يكون لهم جزء مستقل من التدبير؛ فالخلق والأجل والنصر والهزيمة جميعًا بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-558","number":558,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿يخفون في أنفسهم ما لا يبدون لك﴾؟","answer":"يقابل التعبير بين الإخفاء والإبداء، ويجعل النفس وعاءً للاعتراض الذي لا يجرؤون على إظهاره للنبي ﷺ؛ فالسؤال الظاهر كان يخفي اتهامًا أصرح كشفته الجملة التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-559","number":559,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا كرر سؤالهم بصيغة أخرى: ﴿لو كان لنا من الأمر شيء ما قتلنا هاهنا﴾؟","answer":"السؤال الأول ﴿هَلْ لَنَا مِنَ الْأَمْرِ مِنْ شَيْءٍ﴾ تعريض مبهم، أما قولهم ﴿لَوْ كَانَ لَنَا...﴾ فهو تفسير لما أخفوه: زعموا أن اتباع التدبير النبوي سبب القتل. فالثاني كشف لا تكرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-560","number":560,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"ما سرّ التعبير في قوله تعالى: ﴿لبرز الذين كتب عليهم القتل إلى مضاجعهم﴾؟","answer":"﴿لَبَرَزَ﴾ تدل على خروجهم من البيوت إلى العراء، و﴿كُتِبَ عَلَيْهِمُ الْقَتْلُ﴾ تقرر سبق الأجل؛ فلو بقوا في بيوتهم لخرج المقدر عليهم إلى المواضع التي يموتون فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-561","number":561,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا سمّى مواضع القتل ﴿مضاجعهم﴾؟","answer":"المضجع موضع الاضطجاع والراحة، فسُميت به مواضع القتل تلطفًا وتكريمًا للشهداء، وتصويرًا لاستقرارهم فيها كما يبلغ النائم فراشه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-562","number":562,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا جمع بين ابتلاء ما في الصدور وتمحيص ما في القلوب؟","answer":"الابتلاء يُظهر المستور ويختبره، والتمحيص ينقيه ويميز خالصه من دخيله؛ فالمحنة كاشفة ومطهرة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-563","number":563,"surah":3,"verses":[154],"verseLabel":"آل عمران: 154","question":"لماذا خُتمت الآية بـ﴿والله عليم بذات الصدور﴾؟","answer":"لأن الآية عرضت أقوالًا تخفي وراءها ظنونًا واعتراضات؛ فقرر أن الله يعلم السريرة التي تولد منها الكلمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص131–160.","url":""}]},{"id":"s3-564","number":564,"surah":3,"verses":[155],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الذين تولوا منكم يوم التقى الجمعان﴾ ولم يسمّهم؟","answer":"جاء الموصول ﴿الَّذِينَ تَوَلَّوْا﴾ بدل تسمية الأفراد لربط الحكم بالفعل الذي وقع منهم، وستر أسمائهم بعد أن فتح لهم باب العفو؛ فلا تتحول الزلة إلى وصمة دائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص160–174.","url":""}]},{"id":"s3-565","number":565,"surah":3,"verses":[155],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما استزلهم الشيطان ببعض ما كسبوا﴾، فجعل الخطأ زلّة؟","answer":"الاستزلال طلب الزلة أو حمل صاحبها عليها؛ فصُور الشيطان كمن أوقع أقدامهم في مزلق حتى تولوا. والتعبير يجعل الفرار زلة عارضة لا هوية ثابتة، مع إثبات مسؤوليتهم عن سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص160–174.","url":""}]},{"id":"s3-566","number":566,"surah":3,"verses":[155],"verseLabel":"آل عمران: 155","question":"ما سرّ التعبير في قوله تعالى: ﴿ببعض ما كسبوا﴾، دون أن يقال: بذنوبهم؟","answer":"﴿كَسَبُوا﴾ تنسب الذنب إلى عملهم الاختياري، و﴿بَعْضِ﴾ تفيد أن بعض ما سبق منهم كان منفذًا لاستزلال الشيطان، فلا يُرد الفرار إلى قوة الشيطان وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص160–174.","url":""}]},{"id":"s3-567","number":567,"surah":3,"verses":[155],"verseLabel":"آل عمران: 155","question":"لماذا كرر العفو في ﴿ولقد عفا الله عنهم﴾؟","answer":"بعد العفو العام في الآية 152 أعيد هنا عفو الله عن الذين تولوا خاصة، وأكد باللام و﴿قَدْ﴾؛ لقطع اليأس وبيان أن ذكر سبب الزلة ليس لإبقاء المؤاخذة بعد التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص160–174.","url":""}]},{"id":"s3-568","number":568,"surah":3,"verses":[155],"verseLabel":"آل عمران: 155","question":"لماذا ختم بـ﴿إن الله غفور حليم﴾؟","answer":"﴿غَفُورٌ﴾ يناسب التصريح بالعفو عن زلتهم، و﴿حَلِيمٌ﴾ يبين أنه لم يعاجلهم بالعقوبة حين تولوا؛ فاجتمع ستر الذنب والإمهال الذي يفتح باب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص160–174.","url":""}]},{"id":"s3-569","number":569,"surah":3,"verses":[156],"verseLabel":"آل عمران: 156","question":"لماذا نُهي المؤمنون أن يكونوا كالذين كفروا في كلامهم عن إخوانهم؟","answer":"لأن قولهم يربط الموت بالسفر والقتال ويغذي الحسرة والجبن، فأبطل القرآن منطقهم بتقرير أن الإحياء والإماتة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص174–189.","url":""}]},{"id":"s3-570","number":570,"surah":3,"verses":[156],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا ضربوا في الأرض﴾، وكيف يكون السفر ضربًا؟","answer":"الضرب في الأرض كناية عن السفر؛ لأن المسافر يضربها برجليه أو دابته ويشق طريقه فيها، فتنقل العبارة حركة الرحلة ومشقتها بدل مجرد ذكر الخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص174–189.","url":""}]},{"id":"s3-571","number":571,"surah":3,"verses":[156],"verseLabel":"آل عمران: 156","question":"لماذا قابل بين ﴿غزّى﴾ و﴿ضربوا في الأرض﴾؟","answer":"﴿ضَرَبُوا فِي الْأَرْضِ﴾ تشمل المسافرين الذين ماتوا، و﴿غُزًّى﴾ جمع غازٍ يخص الخارجين للقتال الذين قتلوا؛ فجمع التعبيران السببين اللذين علق الكافرون بهما الموت والقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص174–189.","url":""}]},{"id":"s3-572","number":572,"surah":3,"verses":[156],"verseLabel":"آل عمران: 156","question":"لماذا كرروا ﴿ما ماتوا وما قتلوا﴾ مع إمكان الاكتفاء بأحدهما؟","answer":"ذكرا معًا لاختلاف الحالين: الموت قد يقع للمسافر من غير قتال، والقتل يقع للغازي؛ فنفى قولهم أثر الخروج في كلتا الصورتين، ولم يكن أحد اللفظين مغنيًا عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص174–189.","url":""}]},{"id":"s3-573","number":573,"surah":3,"verses":[156],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿ليجعل الله ذلك حسرة في قلوبهم﴾؟","answer":"الإشارة في ﴿ذَلِكَ﴾ تعود إلى قولهم الباطل وربطه الموت بالخروج؛ ويجعل الله هذا الاعتقاد نفسه حسرة مستقرة في قلوبهم، إذ يتوهمون أن بقاء موتاهم كان ممكنًا لو أطاعوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص174–189.","url":""}]},{"id":"s3-574","number":574,"surah":3,"verses":[156],"verseLabel":"آل عمران: 156","question":"ما سرّ التعبير في قوله تعالى: ﴿والله يحيي ويميت﴾ بعد نفي أثر البقاء في البيوت؟","answer":"بعد إبطال زعمهم قررت الجملة الحقيقة الجامعة: الله وحده يحيي ويميت، فلا البيت يمنع الأجل ولا السفر والقتال ينشئانه؛ وبذلك يزول أصل الحسرة والجبن.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص174–189.","url":""}]},{"id":"s3-575","number":575,"surah":3,"verses":[156],"verseLabel":"آل عمران: 156","question":"لماذا ختم بـ﴿والله بما تعملون بصير﴾؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص174–189.","url":""}]},{"id":"s3-576","number":576,"surah":3,"verses":[157],"verseLabel":"آل عمران: 157","question":"ما سرّ تقديم ﴿قتلتم﴾ على ﴿متم﴾ في الآية 157، وتقديم الموت على القتل في الآيتين 144 و158؟","answer":"في الآية 157 مقام ترغيب في الجهاد، فقدم القتل الذي يخشاه المخاطب ليقرر أن عاقبته مغفرة ورحمة. أما الآية 144 فبدأت بالموت لأنه الطريق المعتاد لانقضاء أجل الرسول ثم ذكرت القتل المحتمل، والآية 158 في مقام حشر الجميع فبدأت بالموت الأعم والأغلب ثم ألحقت به القتل؛ فالتقديم تابع لجهة السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص39 وص189–204.","url":""}]},{"id":"s3-577","number":577,"surah":3,"verses":[157],"verseLabel":"آل عمران: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿لمغفرة من الله ورحمة خير مما يجمعون﴾؟","answer":"أكدت اللام جواب القسم، ونكرت المغفرة والرحمة للتعظيم، ثم فضلهما على كل ما يجمعه الناس من متاع؛ فالقتل أو الموت في سبيل الله لا يفضي إلى خسارة بل إلى خير أبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص189–197.","url":""}]},{"id":"s3-578","number":578,"surah":3,"verses":[157],"verseLabel":"آل عمران: 157","question":"لماذا قدّم المغفرة على الرحمة؟","answer":"لأن المغفرة ترفع أثر الذنب أولًا، ثم تتفضل الرحمة بإيصال الخير؛ فالتطهير سابق على الإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص189–197.","url":""}]},{"id":"s3-579","number":579,"surah":3,"verses":[157],"verseLabel":"آل عمران: 157","question":"ما سرّ التعبير في قوله تعالى: ﴿مما يجمعون﴾ ولم يذكر المال؟","answer":"حذف مفعول ﴿يَجْمَعُونَ﴾ ليعم كل ما يحرص الناس على جمعه من مال ومتاع ومصالح، وليُشعر بحقارة المجموع أيًا كان أمام مغفرة الله ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص189–197.","url":""}]},{"id":"s3-580","number":580,"surah":3,"verses":[158],"verseLabel":"آل عمران: 158","question":"ما سرّ التعبير في قوله تعالى: ﴿لإلى الله تحشرون﴾ بتقديم الجار والمجرور؟","answer":"تقديم ﴿إِلَى اللَّهِ﴾ يفيد قصر الحشر والمرجع عليه، واللام مع نون التوكيد تقويان حتمية المصير؛ فلا مهرب بعد الموت أو القتل إلى غير حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص197–204.","url":""}]},{"id":"s3-581","number":581,"surah":3,"verses":[158],"verseLabel":"آل عمران: 158","question":"لماذا اختير ﴿تحشرون﴾ لا: ترجعون؟","answer":"الحشر جمع الخلق وسوقهم جميعًا إلى موقف الحساب، فهو أخص من مجرد الرجوع؛ لأن السياق لا يقرر العودة إلى الله فقط، بل اجتماع الناس للجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص197–204.","url":""}]},{"id":"s3-582","number":582,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿فبما رحمة من الله لنت لهم﴾، وما سر زيادة ﴿ما﴾؟","answer":"في ﴿مَا﴾ قولان بلاغيان مشهوران: أنها مزيدة للتوكيد وتقوية الصلة بين الباء و﴿رَحْمَةٍ﴾، أو إبهامية تفيد التعجب والتفخيم؛ وعلى الوجهين تعظم الرحمة التي كان بها لين النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-583","number":583,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"لماذا نُسب اللين إلى النبي في قوله ﴿لنت لهم﴾؟","answer":"نسب اللين إلى فعل النبي ﷺ ﴿لِنْتَ لَهُمْ﴾ لأنه ظهر في معاملته لهم بعد خطئهم، ثم رد منشأه إلى رحمة من الله؛ فجمع كمال خلق الرسول وفضل التأييد الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-584","number":584,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"لماذا جمع بين ﴿فظًا﴾ و﴿غليظ القلب﴾؟","answer":"الفظاظة خشونة القول والمعاملة في الظاهر، وغلظ القلب قسوة الباطن؛ فانتفى عن الرسول السبب الداخلي ومظهره الذي ينفر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-585","number":585,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"لماذا صوّر ابتعاد الناس بقوله ﴿لانفضوا من حولك﴾؟","answer":"الانفضاض تفرق سريع بعد اجتماع، فصوّر أثر الفظاظة في تفكيك الجماعة وانصرافها عن مركزها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-586","number":586,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"لماذا رتب الأوامر: ﴿فاعف عنهم واستغفر لهم وشاورهم في الأمر﴾؟","answer":"بدأ بالعفو عما يتعلق بحق النبي ﷺ، ثم الاستغفار لما يتعلق بحق الله، ثم الشورى التي تعيد ثقتهم ومشاركتهم في الجماعة؛ فانتقل من إزالة أثر الزلة إلى الدعاء لهم ثم استئناف العمل معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-587","number":587,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"لماذا أمره بمشاورتهم بعد ما وقع بسبب بعضهم في أُحد؟","answer":"حتى لا تتحول الزلة إلى إقصاء يهدم الجماعة، ولتثبيت الشورى منهجًا لا يسقط بخطأ نتائجه؛ فالرسول يعفو ويستغفر ثم يشركهم في الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-588","number":588,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا عزمت فتوكل على الله﴾، فنسب العزم إلى النبي؟","answer":"بعد الشورى نُسب العزم إلى النبي ﷺ لأنه صاحب القرار والتنفيذ؛ فإذا استقر رأيه مضى ولم يبق مترددًا، ثم توكل على الله لأن الأسباب والمشاورة لا تستقل بتحقيق النتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-589","number":589,"surah":3,"verses":[159],"verseLabel":"آل عمران: 159","question":"لماذا ختم بـ﴿إن الله يحب المتوكلين﴾؟","answer":"الخاتمة ترغّب في التوكل بعد العزم، وتبين أن الاعتماد على الله ليس تركًا للمشاورة أو العمل؛ فالمتوكل المحبوب يأخذ بالأسباب ثم يفوض النتيجة إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص204–220.","url":""}]},{"id":"s3-590","number":590,"surah":3,"verses":[11],"verseLabel":"آل عمران: 159؛ الجمعة: 11","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿لانفضوا من حولك﴾، وقوله تعالى في الجمعة ﴿انفضوا إليها وتركوك قائمًا﴾؟","answer":"﴿من حولك﴾ تصور تفكك الجماعة وابتعادها عن مركزها بسبب الفظاظة، أما ﴿إليها﴾ فتصور اندفاعهم نحو التجارة واللهو؛ فالحرفان يرسمان جهتي الحركة: نفورًا من شخص، وإقبالًا على مغرٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص744–745، الجمعة: 11 في المقارنة بآل عمران: 159.","url":""}]},{"id":"s3-591","number":591,"surah":3,"verses":[160],"verseLabel":"آل عمران: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ينصركم الله فلا غالب لكم﴾، دون أن يقال: فأنتم الغالبون؟","answer":"النفي في ﴿فَلَا غَالِبَ لَكُمْ﴾ أبلغ من «فأنتم الغالبون»؛ لأنه ينفي وجود أي غالب يستطيع قهركم مع نصر الله، فيسد كل احتمال للمغالبة بدل إثبات الغلبة من جهة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص220–230.","url":""}]},{"id":"s3-592","number":592,"surah":3,"verses":[160],"verseLabel":"آل عمران: 160","question":"لماذا قابل النصر بالخذلان لا بالهزيمة؟","answer":"لأن الخذلان هو سلب المعونة، وهو المقابل الحقيقي لنصر الله؛ أما الهزيمة فنتيجة ظاهرة قد تقع ابتلاءً ولا تدل وحدها على انقطاع الولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص220–230.","url":""}]},{"id":"s3-593","number":593,"surah":3,"verses":[160],"verseLabel":"آل عمران: 160","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن ذا الذي ينصركم من بعده﴾ في صورة سؤال؟","answer":"الاستفهام إنكاري ينفي أن يوجد بعد خذلان الله أي ناصر، و﴿مَنْ ذَا الَّذِي﴾ تتحدى السامع أن يعين واحدًا يملك النصر من دونه؛ فينقطع التعلق بكل قوة سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص220–230.","url":""}]},{"id":"s3-594","number":594,"surah":3,"verses":[160],"verseLabel":"آل عمران: 160","question":"لماذا ختم ﴿وعلى الله فليتوكل المؤمنون﴾ كما ختمت آية 122؟","answer":"تكررت الخاتمة لأن آية 122 جاءت بعد همّ طائفتين بالفشل فدعت إلى التوكل عند الخوف، وهنا جاءت بعد حصر النصر والخذلان بيد الله فقررت النتيجة نفسها: عليه وحده يعتمد المؤمنون في أسباب النصر كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص220–230.","url":""}]},{"id":"s3-595","number":595,"surah":3,"verses":[161],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان لنبي أن يغل﴾ بصيغة الاستبعاد؟","answer":"صيغة ﴿وَمَا كَانَ لِنَبِيٍّ﴾ تنفي أن يصح أو يتصور في مقام النبوة وقوع الغلول؛ لأن الأمانة من لوازم الرسالة، فالاتهام مناقض لأصل اصطفاء النبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص230–242.","url":""}]},{"id":"s3-596","number":596,"surah":3,"verses":[161],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يغلل يأت بما غل يوم القيامة﴾، وكيف يأتي الإنسان بما أخفى؟","answer":"يُجعل ما غلّه شاهدًا حاضرًا معه يوم القيامة، يحمله أو يحضر بعينه على وجه يفضحه؛ فالصورة تحول الخيانة المستورة في الدنيا إلى عبء ظاهر لا يمكن إنكاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص230–242.","url":""}]},{"id":"s3-597","number":597,"surah":3,"verses":[161],"verseLabel":"آل عمران: 161","question":"ما سرّ التعبير في قوله تعالى: ﴿ثم توفى كل نفس ما كسبت﴾، فجعل العمل كسبًا؟","answer":"سميت الأعمال كسبًا لأنها ثمرة اختيار النفس وسعيها، كما يكتسب الإنسان المال؛ ثم توفى كل نفس حصيلة ما عملت كاملة، خيرًا أو شرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص230–242.","url":""}]},{"id":"s3-598","number":598,"surah":3,"verses":[161],"verseLabel":"آل عمران: 161","question":"لماذا ختم بـ﴿وهم لا يظلمون﴾ بالبناء للمجهول؟","answer":"بُني ﴿لَا يُظْلَمُونَ﴾ للمجهول لتعم قاعدة نفي الظلم عن كل نفس من أي وجه، أما من يتولى توفية الجزاء فمعلوم من السياق وهو الله؛ فالعناية بضمان العدل الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص230–242.","url":""}]},{"id":"s3-599","number":599,"surah":3,"verses":[162],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿أفمن اتبع رضوان الله كمن باء بسخط من الله﴾؟","answer":"الاستفهام ينفي التسوية نفيًا يحمل السامع على الحكم بنفسه؛ فشتان بين من طلب الرضا ومن رجع حاملًا السخط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص242–251.","url":""}]},{"id":"s3-600","number":600,"surah":3,"verses":[162],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿اتبع رضوان الله﴾، وكيف يُتبع الرضوان؟","answer":"اتباع الرضوان هو سلوك الأعمال والطرائق التي تقود إلى رضا الله، فكأن رضوانه غاية ودليل يتبع أثره؛ وفيه تصوير للطاعة اختيارًا متصلًا لا فعلًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص242–251.","url":""}]},{"id":"s3-601","number":601,"surah":3,"verses":[162],"verseLabel":"آل عمران: 162","question":"ما سرّ التعبير في قوله تعالى: ﴿باء بسخط﴾ لا: استحق سخطًا؟","answer":"﴿بَاءَ﴾ تفيد رجع متحملًا للسخط أو استقر به، فتصور السخط حملًا لازمًا عاد به صاحبه بسبب الغلول والمعصية، لا مجرد حكم عارض استحقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص242–251.","url":""}]},{"id":"s3-602","number":602,"surah":3,"verses":[162],"verseLabel":"آل عمران: 162","question":"لماذا ختم بـ﴿وبئس المصير﴾ بعد ذكر جهنم؟","answer":"بعد ذكر جهنم جاء ﴿بِئْسَ الْمَصِيرُ﴾ ليذم نهاية الطريق كله، لا المكان وحده؛ فمن اتبع السخط انتهى إلى أسوأ مرجع ومستقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص242–251.","url":""}]},{"id":"s3-603","number":603,"surah":3,"verses":[163],"verseLabel":"آل عمران: 163","question":"ما سرّ التعبير في قوله تعالى: ﴿هم درجات عند الله﴾، دون أن يقال: لهم درجات؟","answer":"حذف المضاف، أي هم أصحاب درجات أو ذوو درجات، للمبالغة حتى صُير أصحاب الأعمال أنفسهم درجات؛ لأن اختلاف أعمالهم جعل تفاوت منازلهم كأنه تفاوت في ذواتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص251–258.","url":""}]},{"id":"s3-604","number":604,"surah":3,"verses":[163],"verseLabel":"آل عمران: 163","question":"لماذا جمع الجميع في لفظ ﴿درجات﴾ مع اختلاف منازل الخير والشر؟","answer":"جُمعت ﴿دَرَجَاتٌ﴾ لأن الفريقين ليسا على منزلة واحدة: للمؤمنين مراتب صاعدة بحسب الطاعة، ولأهل السخط منازل خسيسة بحسب الجرم؛ فاللفظ يجمع التفاوت عند الله، وإن غلب استعمال الدرجات في الرفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص251–258.","url":""}]},{"id":"s3-605","number":605,"surah":3,"verses":[163],"verseLabel":"آل عمران: 163","question":"لماذا ختم بـ﴿والله بصير بما يعملون﴾؟","answer":"البصر أنسب بمقام الأعمال والمواقف المشاهدة، وفيه مراقبة ووعد أو وعيد بحسب السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص251–258.","url":""}]},{"id":"s3-606","number":606,"surah":3,"verses":[164],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد منّ الله على المؤمنين﴾، وخص المؤمنين مع أن الرسول أُرسل للناس؟","answer":"الرسالة نعمة عامة من جهة البعث، لكن المؤمنين هم الذين قبلوها وانتفعوا بالتلاوة والتزكية والتعليم؛ لذلك خُصوا بالمنة المحققة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص258–272.","url":""}]},{"id":"s3-607","number":607,"surah":3,"verses":[164],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿رسولًا من أنفسهم﴾ لا: منهم؟","answer":"﴿مِنْ أَنْفُسِهِمْ﴾ أبلغ من «منهم»؛ فهي تدل على أنه من جنسهم وقومهم، معروف النسب واللسان والخلق، قريب من نفوسهم، فيسهل فهمه والائتناس به وتقوم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص258–272.","url":""}]},{"id":"s3-608","number":608,"surah":3,"verses":[164],"verseLabel":"آل عمران: 164","question":"لماذا رتب وظائف الرسول: التلاوة، ثم التزكية، ثم تعليم الكتاب والحكمة؟","answer":"التلاوة توصل الوحي أولًا، والتزكية تهيئ النفوس لقبوله، والتعليم يبني الفهم الراسخ للكتاب والحكمة؛ فجمع البلاغ والتربية والمعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص258–272.","url":""}]},{"id":"s3-609","number":609,"surah":3,"verses":[164],"verseLabel":"آل عمران: 164","question":"ما سرّ تقديم التزكية هنا على تعليم الكتاب والحكمة؟","answer":"لأن الآية تعدد أثر المنة الواقعة في المخاطبين: أخرجهم الرسول من دنس الجاهلية ثم علّمهم؛ فقدم التحول المشاهد، مع أن التعليم وسيلة التزكية أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص258–272.","url":""}]},{"id":"s3-610","number":610,"surah":3,"verses":[164],"verseLabel":"آل عمران: 164","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن كانوا من قبل لفي ضلال مبين﴾ بهذا التوكيد؟","answer":"اجتمع في الجملة ﴿إِنْ﴾ المخففة واللام الفارقة في ﴿لَفِي﴾، مع ظرف ﴿مِنْ قَبْلُ﴾ ووصف الضلال بالمبين؛ لتوكيد عظم التحول من ضلال ظاهر ثابت إلى التزكية والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص258–272.","url":""}]},{"id":"s3-611","number":611,"surah":3,"verses":[2],"verseLabel":"آل عمران: 164؛ البقرة: 129، 151؛ الجمعة: 2","question":"ما سرّ تقديم التزكية على تعليم الكتاب في آل عمران، بينما قدم إبراهيم التعليم على التزكية في دعائه؟","answer":"دعاء إبراهيم سار على ترتيب الوسائل المتوقعة: تلاوة ثم تعليم ثم تزكية، أما الإخبار عن منة الله فقدم ثمرة الرسالة العملية وهي تزكية النفوس، مع أن أعمال الرسول متداخلة؛ فترتيب الدعاء ترتيب طلب، وترتيب الامتنان ترتيب عناية وغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص258–272، مع البقرة: 129، 151 والجمعة: 2.","url":""}]},{"id":"s3-612","number":612,"surah":3,"verses":[128],"verseLabel":"آل عمران: 164؛ التوبة: 128","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران ﴿رسولًا من أنفسهم﴾، وقوله تعالى في التوبة ﴿رسول من أنفسكم﴾؟","answer":"آل عمران تحكي المنة على المؤمنين بضمير الغيبة في نسق الحديث عنهم، أما التوبة فتواجه الأمة بالرسول في ختام السورة فجاء الخطاب ﴿من أنفسكم﴾ أشد قربًا واستعطافًا؛ والمعنى الجامع أنه من جنسهم ولسانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص258–272؛ ج43، ص458–459.","url":""}]},{"id":"s3-613","number":613,"surah":3,"verses":[165],"verseLabel":"آل عمران: 165","question":"ما سرّ التعبير في قوله تعالى: ﴿أولما أصابتكم مصيبة قد أصبتم مثليها﴾؟","answer":"الهمزة للإنكار، والواو تربط تعجبهم بما سبق من نصر بدر؛ فكيف يستعظمون مصيبة أُحد وقد أصابوا عدوهم مثليها قتلًا وأسرًا؟ والتعبير يعيد الحدث إلى ميزان أوسع من لحظة الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص272–280.","url":""}]},{"id":"s3-614","number":614,"surah":3,"verses":[165],"verseLabel":"آل عمران: 165","question":"لماذا حكى تعجبهم بقولهم ﴿أنى هذا﴾ لا: كيف حدث هذا؟","answer":"﴿أنى﴾ تسأل عن جهة مجيء المصيبة ومصدرها، فجاء الجواب ﴿هو من عند أنفسكم﴾ مطابقًا؛ أما كيف فتطلب صفة الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص272–280.","url":""}]},{"id":"s3-615","number":615,"surah":3,"verses":[165],"verseLabel":"آل عمران: 165","question":"لماذا جاء الجواب ﴿قل هو من عند أنفسكم﴾؟","answer":"ردّ سبب المصيبة إلى مخالفة الرماة والتنازع، ليمنع تعليق الفشل على القدر وحده ويثبت مسؤولية الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص272–280.","url":""}]},{"id":"s3-616","number":616,"surah":3,"verses":[165],"verseLabel":"آل عمران: 165","question":"لماذا ختم بـ﴿إن الله على كل شيء قدير﴾ مع أن الحديث عن خطأ البشر؟","answer":"ختم بالقدرة لأن الله قادر على نصرهم وعلى إمضاء أثر عصيانهم، فلا تعارض بين وعده السابق وما أذن بوقوعه بسببهم؛ وقدرته نافذة في الجزاء والتربية معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص272–280.","url":""}]},{"id":"s3-617","number":617,"surah":3,"verses":[166],"verseLabel":"آل عمران: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أصابكم يوم التقى الجمعان فبإذن الله﴾؟","answer":"﴿فَبِإِذْنِ اللَّهِ﴾ ترد الواقعة إلى تقديره من غير أن تلغي سببها البشري المذكور قبلها؛ فالمصيبة كانت من عند أنفسهم من جهة العصيان، ووقعت بإذن الله من جهة القضاء والحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-618","number":618,"surah":3,"verses":[166],"verseLabel":"آل عمران: 166","question":"لماذا عبّر عن أُحد بـ﴿يوم التقى الجمعان﴾؟","answer":"﴿يَوْمَ الْتَقَى الْجَمْعَانِ﴾ يستحضر أُحدًا في صورة جيشين متقابلين، ويجعل العبرة في موقف اللقاء والاختبار لا في اسم المكان وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-619","number":619,"surah":3,"verses":[166],"verseLabel":"آل عمران: 166","question":"ما سرّ التعبير في قوله تعالى: ﴿وليعلم المؤمنين﴾ مع سبق علم الله؟","answer":"ليس المراد أن علمًا جديدًا حصل لله، بل أن يظهر المؤمنون بإيمانهم في واقع الامتحان متميزين من المنافقين، فيتعلق بهم الجزاء على ما تحقق منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-620","number":620,"surah":3,"verses":[167],"verseLabel":"آل عمران: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿وقيل لهم تعالوا قاتلوا في سبيل الله أو ادفعوا﴾؟","answer":"بُني ﴿قِيلَ﴾ للمجهول لأن العناية بعرض الحجة عليهم لا باسم القائل، ثم خُيروا بين المرتبة العليا ﴿قَاتِلُوا فِي سَبِيلِ اللَّهِ﴾ وأدنى واجب اجتماعي ﴿أَوِ ادْفَعُوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-621","number":621,"surah":3,"verses":[167],"verseLabel":"آل عمران: 167","question":"لماذا عُرض عليهم القتال في سبيل الله، ثم أدنى منه مجرد الدفع؟","answer":"أقام عليهم الحجة بالتدرج: إن لم يخلصوا للقتال الديني فليدفعوا عن الأهل والبلد؛ فلما رفضوا الأدنى انكشف أن عذرهم ستار للنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-622","number":622,"surah":3,"verses":[167],"verseLabel":"آل عمران: 167","question":"ما دلالة قولهم ﴿لو نعلم قتالًا لاتبعناكم﴾ بدل أن يقولوا: لقاتلنا معكم؟","answer":"قولهم ﴿لَاتَّبَعْنَاكُمْ﴾ أبعد من الالتزام الصريح «لقاتلنا»؛ جعلوا القضية اتباعًا لتقدير غيرهم، وعلّقوه بشرط موهوم هو وجود قتال، فجمع جوابهم التهرب والطعن في جدوى الخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-623","number":623,"surah":3,"verses":[167],"verseLabel":"آل عمران: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿هم للكفر يومئذ أقرب منهم للإيمان﴾ لا: هم كافرون؟","answer":"لم يحكم على بواطنهم حكمًا مطلقًا، بل وصف ما أظهره موقفهم يومئذ؛ وفي المقارنة كشف لتأرجحهم وغلبة جانب الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-624","number":624,"surah":3,"verses":[167],"verseLabel":"آل عمران: 167","question":"ما سرّ التعبير في قوله تعالى: ﴿يقولون بأفواههم ما ليس في قلوبهم﴾؟","answer":"ذكر الأفواه مع أن القول لا يكون إلا بها لبيان أن الكلام لم يتجاوز ظاهر النطق إلى تصديق القلب؛ فالمقابلة بين الأفواه والقلوب تجسم انفصال ظاهرهم عن باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص280–298.","url":""}]},{"id":"s3-625","number":625,"surah":3,"verses":[167],"verseLabel":"آل عمران: 167","question":"لماذا جاءت خاتمة آل عمران ﴿والله أعلم بما يكتمون﴾، وفي المائدة ﴿والله أعلم بما كانوا يكتمون﴾؟","answer":"جاء المضارع ﴿يَكْتُمُونَ﴾ في آل عمران لأن نفاقهم في موقف أُحد كان أقرب إلى التردد وأقل رسوخًا، أما ﴿كَانُوا يَكْتُمُونَ﴾ في المائدة فتدل على كتمان صار عادةً ماضية متقررة، ملائمًا لشدة غرق المذكورين هناك في الكفر والنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص296؛ مسح عكسي.","url":""}]},{"id":"s3-626","number":626,"surah":3,"verses":[1],"verseLabel":"آل عمران: 167؛ المنافقون: 1","question":"ما سرّ التعبير بقوله تعالى: في آل عمران ﴿الذين نافقوا﴾، وجاء في السورة الأخرى الاسم الصريح ﴿المنافقون﴾؟","answer":"في آل عمران يصف النص فعلًا ظهر منهم في حادثة أحد، فناسب الموصول والفعل ﴿الذين نافقوا﴾؛ أما سورة المنافقون فتعالج الصفة بعد رسوخها واشتهار أصحابها بها، فجاء اسم الفاعل عنوانًا ثابتًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص781، المنافقون: 1 في المقارنة بآل عمران: 167.","url":""}]},{"id":"s3-627","number":627,"surah":3,"verses":[168],"verseLabel":"آل عمران: 168","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين قالوا لإخوانهم وقعدوا﴾، دون أن يقال: الذين قعدوا وقالوا؟","answer":"قُدم قولهم لأن الآية ترد حجتهم المنطوقة، ثم عطف ﴿وَقَعَدُوا﴾ ليكشف تناقضها: تكلموا في شأن من خرجوا وهم أنفسهم امتنعوا عن الخروج؛ فالقعود حال تفضح المقالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص298–306.","url":""}]},{"id":"s3-628","number":628,"surah":3,"verses":[168],"verseLabel":"آل عمران: 168","question":"لماذا سمّوا المقتولين ﴿إخوانهم﴾ مع تخذيلهم لهم؟","answer":"الإخوة هنا أخوة النسب أو القوم، وذكرها يزيد تقريعهم؛ إذ كان مقتضى الأخوة النصرة والمواساة، فإذا بهم يقعدون ويجعلون قتل إخوانهم مادة للتخذيل والشماتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص298–306.","url":""}]},{"id":"s3-629","number":629,"surah":3,"verses":[168],"verseLabel":"آل عمران: 168","question":"ما سرّ التعبير بقوله تعالى: لهم ﴿فادرءوا عن أنفسكم الموت إن كنتم صادقين﴾؟","answer":"الأمر للتعجيز وإبطال دعواهم: إن كان القعود يمنع الموت كما يزعمون، فليدفعوا الموت عن أنفسهم. وعجزهم يكشف أن الأجل لا يحجزه بيت ولا يقدمه قتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص298–306.","url":""}]},{"id":"s3-630","number":630,"surah":3,"verses":[168],"verseLabel":"آل عمران: 168","question":"لماذا اختير ﴿ادرءوا﴾ لا: ادفعوا؟","answer":"الدرء دفع الشيء وإبعاده قبل أن يصل أو عند توجهه، وفيه معنى المقاومة؛ لذلك هو أنسب بالتحدي من «ادفعوا» العامة: حاولوا إزاحة الموت عن أنفسكم إن صدق زعمكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص298–306.","url":""}]},{"id":"s3-631","number":631,"surah":3,"verses":[169],"verseLabel":"آل عمران: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تحسبن الذين قتلوا في سبيل الله أمواتًا﴾ بصيغة النهي؟","answer":"النهي يصحح حسبانًا تفرضه مشاهدة الأجساد بعد القتل؛ فيمنع تثبيت وصف الأموات للشهداء، ثم ينقل الإدراك إلى حقيقتهم عند الله: حياة ورزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-632","number":632,"surah":3,"verses":[169],"verseLabel":"آل عمران: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿بل أحياء عند ربهم يرزقون﴾، وما دلالة ﴿بل﴾؟","answer":"أضرب عن حسبان الموت إلى حياة برزخية خاصة، وقيدها بالقرب والرزق لإثبات حياة حقيقية تليق بعالمها لا نعرف كيفيتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-633","number":633,"surah":3,"verses":[169],"verseLabel":"آل عمران: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿عند ربهم﴾، دون أن يقال: في الجنة؟","answer":"﴿عِنْدَ رَبِّهِمْ﴾ تدل على منزلة القرب والتشريف والرعاية، وهي أخص بمقصود تسلية أهلهم من تعيين مكان؛ كما أنها تثبت أن حقيقة حياتهم معلومة عند ربهم وإن غابت عن الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-634","number":634,"surah":3,"verses":[169],"verseLabel":"آل عمران: 169","question":"لماذا جاء ﴿يرزقون﴾ بالمضارع المبني للمجهول؟","answer":"المضارع يدل على تجدد الرزق واستمراره، والبناء للمجهول يوجه العناية إلى دوام النعمة نفسها، أما الرازق فمعلوم من قوله ﴿عِنْدَ رَبِّهِمْ﴾ وهو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-635","number":635,"surah":3,"verses":[154],"verseLabel":"آل عمران: 169؛ البقرة: 154","question":"ما سرّ اختلاف التفصيل في شأن الشهداء بين قوله تعالى في البقرة ﴿بل أحياء ولكن لا تشعرون﴾، وقوله تعالى في آل عمران ﴿بل أحياء عند ربهم يرزقون﴾؟","answer":"البقرة جاءت في أول تربية الأمة على البلاء فاكتفت بإثبات حياة لا تدركها الحواس، أما آل عمران فنزلت بعد وقوع القتل في أحد ففصلت تسليةً لأهل الشهداء: قربٌ ورزق وفرح واستبشار؛ فالثانية تفصيل للأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص544–545؛ ج6، ص306–323.","url":""}]},{"id":"s3-636","number":636,"surah":3,"verses":[170],"verseLabel":"آل عمران: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿فرحين بما آتاهم الله من فضله﴾ لا: بما استحقوا؟","answer":"نسب العطاء إلى الله ووصفه بالفضل ليبين أن ما ناله الشهداء من رزق وفرح تكرم زائد، لا معاوضة يستقلون باستحقاقها؛ وذلك أدعى إلى تعظيم النعمة والشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-637","number":637,"surah":3,"verses":[170],"verseLabel":"آل عمران: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿ويستبشرون بالذين لم يلحقوا بهم من خلفهم﴾؟","answer":"يستبشر الشهداء بإخوانهم الذين بقوا وراءهم في الدنيا ولم ينضموا إليهم بعد، لما علموا من حسن ما ينتظر من يلحق بهم ثابتًا؛ ففرحهم يتجاوز ذواتهم إلى الأحياء بعدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-638","number":638,"surah":3,"verses":[170],"verseLabel":"آل عمران: 170","question":"لماذا نُفي عن اللاحقين الخوف والحزن مع اختلاف زمنيهما؟","answer":"الخوف توقع مكروه آت، والحزن ألم على فائت؛ فنفيهما يؤمن مستقبلهم وماضيهم ويستوعب اضطراب النفس كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-639","number":639,"surah":3,"verses":[171],"verseLabel":"آل عمران: 171","question":"لماذا كرر ﴿يستبشرون﴾ في آيتين متتاليتين؟","answer":"الاستبشار الأول متعلق بالذين لم يلحقوا بهم وبزوال خوفهم وحزنهم، والثاني متعلق بما يناله الشهداء أنفسهم من نعمة وفضل؛ فتكرر الفعل لاختلاف متعلقي البشرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-640","number":640,"surah":3,"verses":[171],"verseLabel":"آل عمران: 171","question":"لماذا فُصّل الاستبشار بـ﴿نعمة من الله وفضل﴾، وما الفرق بينهما؟","answer":"النعمة هي ما أنعم الله به عليهم من حياة ورزق وأمن، والفضل زيادة العطاء فوق ما يقابل العمل؛ فجمع الأصل المشهود وسعة التفضل الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-641","number":641,"surah":3,"verses":[171],"verseLabel":"آل عمران: 171","question":"لماذا ختم بـ﴿وأن الله لا يضيع أجر المؤمنين﴾؟","answer":"الخاتمة تعمم ضمان الجزاء بعد وصف الشهداء، فلم تقل «أجرهم» وحدهم؛ لتقرر أن الله لا يضيع أجر أي مؤمن، وفي ذلك تسلية للأحياء وترغيب لهم في الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص306–323.","url":""}]},{"id":"s3-642","number":642,"surah":3,"verses":[172],"verseLabel":"آل عمران: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين استجابوا لله والرسول من بعد ما أصابهم القرح﴾؟","answer":"قيد الاستجابة بأنها وقعت ﴿مِنْ بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ﴾ ليعظم شأنها؛ فقد خرجوا في أثر العدو مع الجراح والتعب، فكان جوابهم العملي دليل صدق وثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-643","number":643,"surah":3,"verses":[172],"verseLabel":"آل عمران: 172","question":"لماذا أفرد حرف الجر في ﴿لله والرسول﴾؟","answer":"جيء بلام واحدة في ﴿لِلَّهِ وَالرَّسُولِ﴾ لأن الاستجابة للرسول استجابة لأمر الله وليست طاعة مستقلة عنه؛ فجمعهما حرف واحد في جهة التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-644","number":644,"surah":3,"verses":[172],"verseLabel":"آل عمران: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿للذين أحسنوا منهم واتقوا﴾، فجاء بـ﴿منهم﴾؟","answer":"تحتمل ﴿مِنْهُمْ﴾ البيان؛ أي هؤلاء المستجيبون الذين أحسنوا واتقوا، وتحتمل التبعيض الاحترازي؛ فيكون الأجر العظيم لمن استمر منهم على الإحسان والتقوى. وفي الوجهين لا يكفي مجرد الخروج بلا صلاح الباطن والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-645","number":645,"surah":3,"verses":[172],"verseLabel":"آل عمران: 172","question":"لماذا جمع الإحسان والتقوى؟","answer":"الإحسان أداء العمل على وجهه وبذل الخير، والتقوى اجتناب ما يسخط الله؛ فجمع فعل المأمور وترك المحظور.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-646","number":646,"surah":3,"verses":[173],"verseLabel":"آل عمران: 173","question":"ما دلالة تكرار لفظ ﴿الناس﴾ في قوله تعالى: ﴿الذين قال لهم الناس إن الناس قد جمعوا لكم﴾؟","answer":"ليس المراد بالناس في الموضعين جماعة واحدة بالضرورة: الأول من نقل خبر التخويف، والثاني جيش العدو الذي قيل إنه جمع؛ والتكرار مع إبهام الجمعين يضخم صورة الحشد في السمع، ثم يهدم أثرها إيمان المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-647","number":647,"surah":3,"verses":[173],"verseLabel":"آل عمران: 173","question":"لماذا زادهم التخويف إيمانًا بدل الخوف؟","answer":"لأن التهديد ردهم إلى يقينهم بأن الله كافيهم، فصار اجتماع الناس عليهم دليلًا جديدًا على صدق الوعد وميدانًا للتوكل، لا سببًا للانهيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-648","number":648,"surah":3,"verses":[173],"verseLabel":"آل عمران: 173","question":"ما دلالة جواب المؤمنين: ﴿حسبنا الله ونعم الوكيل﴾؟","answer":"﴿حَسْبُنَا اللَّهُ﴾ إعلان أن الله كافيهم فلا يحتاجون مع كفايته إلى قوة أخرى، و﴿نِعْمَ الْوَكِيلُ﴾ مدح لمن فوضوا إليه أمرهم؛ فجمع القول الثقة بالكفاية وحسن التفويض.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-649","number":649,"surah":3,"verses":[173],"verseLabel":"آل عمران: 173","question":"لماذا اختير اسم ﴿الوكيل﴾ في هذا الموقف؟","answer":"الوكيل هو من يفوض إليه حفظ الأمر وتدبيره؛ واختير هنا لأن المخوفين أوهموهم عجزهم عن مواجهة الجمع، فردوا بتسليم أمر الحماية والنصر إلى خير من يعتمد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص323–338.","url":""}]},{"id":"s3-650","number":650,"surah":3,"verses":[174],"verseLabel":"آل عمران: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿فانقلبوا بنعمة من الله وفضل﴾، فجعل الرجوع انقلابًا؟","answer":"الانقلاب رجوع مع تحول في الحال؛ خرجوا يواجهون خبر الخوف ثم عادوا مصحوبين بالنعمة والفضل، فانقلب توقع الضرر إلى سلامة وربح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص338–344.","url":""}]},{"id":"s3-651","number":651,"surah":3,"verses":[174],"verseLabel":"آل عمران: 174","question":"لماذا جمع بين النعمة والفضل؟","answer":"النعمة ما عاد عليهم من سلامة ونصر، والفضل الزيادة الواسعة التي لم تكن حقًا واجبًا لهم؛ فذكر العطاء المشهود ومصدر توسعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص338–344.","url":""}]},{"id":"s3-652","number":652,"surah":3,"verses":[174],"verseLabel":"آل عمران: 174","question":"لماذا جاءت جملة ﴿لم يمسسهم سوء﴾ بين النعمة واتباع الرضوان؟","answer":"الجملة حال تبين تمام النعمة: عادوا بنعمة وفضل في حال لم يصبهم أدنى سوء، ثم بين أن سلامتهم اقترنت باتباع رضوان الله؛ فجمعت سلامة البدن وصلاح القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص338–344.","url":""}]},{"id":"s3-653","number":653,"surah":3,"verses":[174],"verseLabel":"آل عمران: 174","question":"لماذا ختم بـ﴿والله ذو فضل عظيم﴾؟","answer":"جاء ﴿ذُو فَضْلٍ عَظِيمٍ﴾ بعد نعمة السلامة وربح التجارة وثواب الطاعة؛ ليبين أن ما نالوه بعض فضل الله الواسع، وأن النتيجة لم تكن ثمرة قوتهم وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص338–344.","url":""}]},{"id":"s3-654","number":654,"surah":3,"verses":[175],"verseLabel":"آل عمران: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما ذلكم الشيطان يخوف أولياءه﴾؟","answer":"القصر بـ﴿إِنَّمَا﴾ يكشف أن مصدر رسالة التخويف هو الشيطان، و﴿ذَلِكُمُ﴾ تشير إلى المخوف أو الخبر الحاضر في أذهانهم. ومعنى ﴿يُخَوِّفُ أَوْلِيَاءَهُ﴾: يخوفكم بأوليائه ويضخم قوتهم في نفوسكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص344–352.","url":""}]},{"id":"s3-655","number":655,"surah":3,"verses":[175],"verseLabel":"آل عمران: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تخافوهم وخافون﴾، فجمع ضميرهم وأفرد ضمير الله؟","answer":"ضمير الجمع في ﴿فَلَا تَخَافُوهُمْ﴾ يعود إلى الأولياء المتعددين، أما ياء المتكلم المقدرة في ﴿وَخَافُونِ﴾ فتعود إلى الله الواحد؛ والمقابلة تهدم رهبة الكثرة أمام الخوف من الواحد القادر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص351.","url":""}]},{"id":"s3-656","number":656,"surah":3,"verses":[175],"verseLabel":"آل عمران: 175","question":"لماذا عُلّق الأمر بالخوف من الله بقوله ﴿إن كنتم مؤمنين﴾؟","answer":"جعل الخوف من الله دون أولياء الشيطان مقتضى الإيمان؛ فمن صدق بأن النصر والضر بيده لم يقدم خشية المخلوق على خشيته. والشرط لاستنهاض حقيقة الإيمان في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص344–352.","url":""}]},{"id":"s3-657","number":657,"surah":3,"verses":[176],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحزنك الذين يسارعون في الكفر﴾، وكيف تكون المسارعة داخل الكفر؟","answer":"جعل الكفر ميدانًا يندفعون في داخله، فالصورة تكشف نشاطهم في أسبابه، ثم تسلّي الرسول بأنهم لا يضرون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص352–360.","url":""}]},{"id":"s3-658","number":658,"surah":3,"verses":[176],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿إنهم لن يضروا الله شيئًا﴾ لا: لن يضروك؟","answer":"لم يقل «لن يضروك» لأن مسارعتهم ليست اعتداءً شخصيًا على الرسول ﷺ فقط، بل محاولة لمغالبة دين الله؛ فنفى قدرتهم على الإضرار بالله، أي بدينه ووعده، وارتد ضررهم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص352–360.","url":""}]},{"id":"s3-659","number":659,"surah":3,"verses":[176],"verseLabel":"آل عمران: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿يريد الله ألا يجعل لهم حظًا في الآخرة﴾؟","answer":"إرادة ألا يكون لهم حظ في الآخرة بيان لعاقبة إصرارهم ومسارعتهم الاختيارية في الكفر؛ فالله يمهلهم حتى يستوفوا ما اختاروه وتقوم عليهم الحجة، ثم لا يبقى لهم نصيب من ثواب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص352–360.","url":""}]},{"id":"s3-660","number":660,"surah":3,"verses":[176],"verseLabel":"آل عمران: 176","question":"لماذا سمّى نصيب الآخرة ﴿حظًا﴾؟","answer":"الحظ هو النصيب المقدر من الخير، وتنكيره في سياق النفي يعم أدنى نصيب؛ أي لا يجعل لهم شيئًا من نعيم الآخرة، لا قليلًا ولا كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص352–360.","url":""}]},{"id":"s3-661","number":661,"surah":3,"verses":[177],"verseLabel":"آل عمران: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿اشتروا الكفر بالإيمان﴾، وكيف يُشترى الكفر؟","answer":"صُورت مفارقة الإيمان إلى الكفر صفقةً جعلوا فيها الإيمان ثمنًا والكفر سلعة؛ وفيها تقبيح لاختيارهم، إذ بذلوا أنفس ما يملكون في شراء سبب العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص360–363.","url":""}]},{"id":"s3-662","number":662,"surah":3,"verses":[177],"verseLabel":"آل عمران: 177","question":"لماذا أعاد ﴿لن يضروا الله شيئًا﴾؟","answer":"في الآية 176 نُفي الضرر عن المسارعين في الكفر، وهنا أعيد بعد تصوير صفقتهم الخاسرة؛ ليؤكد أن انتقالهم المتعمد إلى الكفر لا ينقص ملك الله ولا يفسد وعده، وإنما يهلكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص360–363.","url":""}]},{"id":"s3-663","number":663,"surah":3,"verses":[177],"verseLabel":"آل عمران: 177","question":"ما سرّ التعبير في قوله تعالى: ﴿ولهم عذاب أليم﴾ بعد نفي الضرر عن الله؟","answer":"لما نُفي ضررهم عن الله بيّن أن الضرر لا يضيع بل يرجع إليهم، فجاء ﴿وَلَهُمْ﴾ للاختصاص، ووصف العذاب بالأليم لأن الصفقة التي اختاروها تنتهي إلى ألمهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص360–363.","url":""}]},{"id":"s3-664","number":664,"surah":3,"verses":[178],"verseLabel":"آل عمران: 178","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحسبن الذين كفروا أنما نملي لهم خير لأنفسهم﴾؟","answer":"الإملاء إطالة المدة والإمهال؛ والآية تنهيهم عن عد طول العمر والسعة دليل رضا وخير، لأن قيمة المهلة بما يعمل فيها لا بمجرد امتدادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص363–369.","url":""}]},{"id":"s3-665","number":665,"surah":3,"verses":[178],"verseLabel":"آل عمران: 178","question":"لماذا كرر ﴿إنما نملي لهم﴾ بعد ذكر الإملاء أولًا؟","answer":"الأولى تحكي ظنهم أن الإملاء خير، والثانية تقصر حقيقته عليهم في عاقبة أخرى: استمرار اختيارهم يزيد إثمهم. فالتكرار يفصل بين الوهم الذي نُفي والحقيقة التي أُثبتت.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص363–369.","url":""}]},{"id":"s3-666","number":666,"surah":3,"verses":[178],"verseLabel":"آل عمران: 178","question":"لماذا عُلّل الإمهال بقوله ﴿ليزدادوا إثمًا﴾؟","answer":"ليس المعنى أن الله يجبرهم على الإثم؛ بل يمهلهم مع قيام الحجة، وهم يستمرون باختيارهم في الكفر، فتؤول المهلة إلى زيادة ما يكتسبونه من الإثم. فاللام لبيان العاقبة أو الغاية الجزائية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص363–369.","url":""}]},{"id":"s3-667","number":667,"surah":3,"verses":[178],"verseLabel":"آل عمران: 178","question":"لماذا وصف العذاب هنا بـ﴿مهين﴾؟","answer":"وصف العذاب بالمهين لأنهم اتخذوا الإملاء والمال والعمر علامة كرامة، فقوبل اغترارهم بعذاب يجمع الألم وإسقاط الكرامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص363–369.","url":""}]},{"id":"s3-668","number":668,"surah":3,"verses":[180],"verseLabel":"آل عمران: 178؛ آل عمران: 180","question":"ما سرّ التعبير في قوله تعالى في الآية 178 ﴿خير لأنفسهم﴾، وفي الآية 180 ﴿خيرًا لهم﴾ مع افتتاحهما بـ﴿ولا يحسبن﴾؟","answer":"الأولى تتحدث عن الإملاء ذاته فجيء بخبر ﴿خير﴾ مضافًا إلى الأنفس التي يتوهمون نفعها، أما الثانية فالمحسوب هو البخل أو المال فجاء ﴿خيرًا﴾ مفعولًا ثانيًا للحسبان ثم رده صراحةً بـ﴿بل هو شر لهم﴾؛ فاختلاف التركيب تابع لاختلاف المحسوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص363–369 وص381–388.","url":""}]},{"id":"s3-669","number":669,"surah":3,"verses":[179],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان الله ليذر المؤمنين على ما أنتم عليه﴾؟","answer":"تركيب ﴿مَا كَانَ اللَّهُ لِيَذَرَ﴾ يفيد نفيًا مؤكدًا لما لا يليق بحكمته: ألا يترك جماعة المؤمنين والمنافقين مختلطين على حال لا يتميز فيها الصادق من الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص369–381.","url":""}]},{"id":"s3-670","number":670,"surah":3,"verses":[179],"verseLabel":"آل عمران: 179","question":"لماذا انتقل من الغيبة في ﴿المؤمنين﴾ إلى الخطاب في ﴿ما أنتم عليه﴾؟","answer":"بدأ باسم المؤمنين تقريرًا لسنة الله في جماعتهم، ثم التفت إلى خطابهم ﴿مَا أَنْتُمْ عَلَيْهِ﴾ ليواجه السامعين بحال الاختلاط الذي عاشوه، فيصير التنبيه أوقع في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص369–381.","url":""}]},{"id":"s3-671","number":671,"surah":3,"verses":[179],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿حتى يميز الخبيث من الطيب﴾، ومن الخبيث والطيب هنا؟","answer":"التمييز صورة مأخوذة من فصل الشيء الخبيث عن الطيب بعد اختلاطهما؛ والمراد هنا كشف المنافق من المؤمن بالابتلاء، لا أن الله يجهل أحدهما قبل الاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص369–381.","url":""}]},{"id":"s3-672","number":672,"surah":3,"verses":[179],"verseLabel":"آل عمران: 179","question":"لماذا نفى إطلاع الناس على الغيب ثم أثبت اجتباء الرسل؟","answer":"نفى أن يكون الغيب مباحًا للبشر ابتداءً، ثم بيّن الاستثناء المنضبط: الله يختار من رسله من يطلعه على قدر يؤدي به الرسالة؛ فلا تناقض بين النفي والاجتباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص369–381.","url":""}]},{"id":"s3-673","number":673,"surah":3,"verses":[179],"verseLabel":"آل عمران: 179","question":"ما سرّ التعبير في قوله تعالى: ﴿يجتبي من رسله من يشاء﴾ لا: يختار؟","answer":"الاجتباء اختيار مع جمع واصطفاء، فهو أخص من مطلق الاختيار؛ يختار الله من رسله من يطلعه على ما شاء من الغيب لأداء الرسالة، لا ليصير الغيب مباحًا للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص369–381.","url":""}]},{"id":"s3-674","number":674,"surah":3,"verses":[179],"verseLabel":"آل عمران: 179","question":"لماذا ختم بـ﴿وإن تؤمنوا وتتقوا فلكم أجر عظيم﴾؟","answer":"بعد نفي طريق التطلع إلى الغيب ردهم إلى ما كلفوا به: الإيمان بالله ورسله والتقوى؛ فمن قام بالواجب نال أجرًا عظيمًا من غير حاجة إلى كشف الغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص369–381.","url":""}]},{"id":"s3-675","number":675,"surah":3,"verses":[180],"verseLabel":"آل عمران: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحسبن الذين يبخلون بما آتاهم الله من فضله هو خيرًا لهم﴾؟","answer":"الآية تنفي حسبان البخل خيرًا لأصحابه، ثم تقلب حكمهم صراحةً إلى الشر. وتعليق البخل بما آتاهم الله يكشف أن ما منعوه نعمة اؤتمنوا عليها لا ملكًا مستقلًا عن واهبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص381–388.","url":""}]},{"id":"s3-676","number":676,"surah":3,"verses":[180],"verseLabel":"آل عمران: 180","question":"ما سرّ التعبير في قوله تعالى: ﴿بما آتاهم الله من فضله﴾، دون أن يقال: بأموالهم؟","answer":"عدل عن «أموالهم» إلى ﴿مَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ﴾ ليسلب البخيل توهم الاستقلال بالملك، ويذكره بأن المال عطاء وتفضل يقتضي الشكر والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص381–388.","url":""}]},{"id":"s3-677","number":677,"surah":3,"verses":[180],"verseLabel":"آل عمران: 180","question":"لماذا أعقب ﴿هو خيرًا لهم﴾ بقوله ﴿بل هو شر لهم﴾؟","answer":"﴿بَلْ﴾ تبطل ظن الخيرية وتثبت ضده بقوة: المال المحبوس ليس نفعًا لهم بل شر يعود عليهم؛ ثم فسر هذا الشر بصورة الطوق يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص381–388.","url":""}]},{"id":"s3-678","number":678,"surah":3,"verses":[180],"verseLabel":"آل عمران: 180","question":"لماذا صوّر مال البخيل بقوله ﴿سيطوقون ما بخلوا به﴾؟","answer":"حوّل المال المحبوب إلى طوق ملازم خانق يوم القيامة؛ فالعقوبة من جنس تعلقهم بما منعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص381–388.","url":""}]},{"id":"s3-679","number":679,"surah":3,"verses":[180],"verseLabel":"آل عمران: 180","question":"لماذا ختم بـ﴿ولله ميراث السماوات والأرض﴾؟","answer":"ميراث السماوات والأرض رجوع كل ما في أيدي الخلق إلى مالكه الباقي بعد فنائهم؛ فخاتمتها تبطل أصل البخل، لأن ما يمسكونه سيتركونه ويظل ملكه لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص381–388.","url":""}]},{"id":"s3-680","number":680,"surah":3,"verses":[181],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد سمع الله قول الذين قالوا﴾ مع أن الله يسمع كل شيء؟","answer":"التوكيد والقول المكرر يثبتان أن الكلمة لم تضع، ويحوّلان ما حسبوه حديثًا عابرًا إلى جريمة محفوظة محاسب عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-681","number":681,"surah":3,"verses":[181],"verseLabel":"آل عمران: 181","question":"لماذا حكى مقالتهم البشعة نصًا: ﴿إن الله فقير ونحن أغنياء﴾؟","answer":"حكاية قولهم نصًا تقيم الحجة عليهم بلفظه وتكشف غاية جرأتهم، فلا يخفف قبحه بنقل المعنى؛ كما تجعل السامع يدرك التناقض بين غنى الله وافتقارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-682","number":682,"surah":3,"verses":[181],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿سنكتب ما قالوا﴾، وكيف يُكتب القول؟","answer":"الكتابة كناية عن الإثبات والحفظ الذي لا يضيع؛ فما ظنوه قولًا عابرًا سيثبت في سجل أعمالهم ويواجهون بجزائه، والسين تهدد بقرب تحقق ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-683","number":683,"surah":3,"verses":[181],"verseLabel":"آل عمران: 181","question":"لماذا عطف ﴿وقتلهم الأنبياء بغير حق﴾ على مقالتهم؟","answer":"لأن جرأة اللسان في قولهم على الله امتداد لجرأة الفعل على رسله؛ فجمع شاهد العقيدة الفاسدة وشاهد التاريخ الإجرامي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-684","number":684,"surah":3,"verses":[181],"verseLabel":"آل عمران: 181","question":"ما سرّ التعبير في قوله تعالى: ﴿ونقول ذوقوا عذاب الحريق﴾؟","answer":"الذوق إحساس مباشر شديد لا واسطة فيه، فاستعير لمباشرة عذاب النار. وإضافة العذاب إلى ﴿الْحَرِيقِ﴾ تستحضر احتراقًا متجددًا لا مجرد نار تُرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-685","number":685,"surah":3,"verses":[182],"verseLabel":"آل عمران: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بما قدمت أيديكم﴾ مع أن الذنوب ليست كلها باليد؟","answer":"الأيدي كناية عن أصحابها وأعمالهم لأن أكثر الأفعال تباشر بها؛ فنسب التقديم إليها لتأكيد مسؤوليتهم عما صنعوا، وإن شملت المؤاخذة أقوال اللسان واعتقاد القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-686","number":686,"surah":3,"verses":[182],"verseLabel":"آل عمران: 182","question":"لماذا عبّر عن الأعمال الماضية بأنها ﴿قدمت﴾؟","answer":"﴿قَدَّمَتْ﴾ تصور الأعمال كمتاع أرسله صاحبه أمامه إلى الآخرة ثم لحق به؛ فما يلقاه هناك هو ما سبق أن هيأه لنفسه في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-687","number":687,"surah":3,"verses":[182],"verseLabel":"آل عمران: 182","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن الله ليس بظلام للعبيد﴾ بصيغة المبالغة؟","answer":"صيغة ﴿ظَلَّامٍ﴾ تحت النفي لا تقتصر على نفي الظلم الكثير، بل تؤكد نفي جنس الظلم كله؛ ومع كثرة العبيد لو وقع أدنى ظلم لكل واحد لكان ظلمًا عظيمًا، فتنزه الله عن قليله وكثيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص388–414.","url":""}]},{"id":"s3-688","number":688,"surah":3,"verses":[183],"verseLabel":"آل عمران: 183","question":"ما دلالة نسبتهم طلبهم إلى عهد إلهي في قولهم: ﴿إن الله عهد إلينا﴾؟","answer":"نسبوا اشتراطهم إلى عهد من الله ليصوروا امتناعهم من التصديق التزامًا دينيًا لا تعنتًا منهم؛ فجاء الرد بتكذيب دعواهم من تاريخهم مع الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص414–423.","url":""}]},{"id":"s3-689","number":689,"surah":3,"verses":[183],"verseLabel":"آل عمران: 183","question":"ما سرّ اشتراطهم قربانًا ﴿تأكله النار﴾؟","answer":"كان أكل النار للقربان علامة عرفوها في شرائع سابقة، فاتخذوا طلبها ذريعة لتعليق الإيمان على آية مخصوصة، مع أن الرسل جاءوهم بها من قبل فلم يؤمنوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص414–423.","url":""}]},{"id":"s3-690","number":690,"surah":3,"verses":[183],"verseLabel":"آل عمران: 183","question":"لماذا جاء الرد بذكر رسل سابقين جاءوا بالبينات وبالذي طلبوه؟","answer":"ألزمهم بتاريخهم: فقد تحقق الشرط الذي يتعللون به على أيدي رسل قبل محمد ثم كذبوهم وقتلوهم؛ فدل أن الطلب ليس طلب هداية بل مكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص414–423.","url":""}]},{"id":"s3-691","number":691,"surah":3,"verses":[183],"verseLabel":"آل عمران: 183","question":"ما دلالة ختام الرد بقوله تعالى: ﴿فلم قتلتموهم إن كنتم صادقين﴾؟","answer":"جاء الاستفهام تبكيتًا يلزمهم بما يناقض دعوى الصدق: فقد جاءت رسل قبل محمد ﷺ بالبينات وبالقربان الذي طلبوه، ثم قابلهم أسلافهم بالقتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص414–423.","url":""}]},{"id":"s3-692","number":692,"surah":3,"verses":[184],"verseLabel":"آل عمران: 184","question":"ما دلالة قوله تعالى: ﴿فإن كذبوك فقد كذب رسل من قبلك﴾ في تسلية النبي ﷺ؟","answer":"الشرط يواجه احتمال التكذيب، و﴿قَدْ﴾ تحقق وقوع نظيره من قبل؛ فمصدر التكذيب عناد المكذبين لا قصور الحجة، وفي ذلك تسلية للنبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص414–423.","url":""}]},{"id":"s3-693","number":693,"surah":3,"verses":[184],"verseLabel":"آل عمران: 184","question":"ما دلالة الجمع بين ﴿البينات والزبر والكتاب المنير﴾؟","answer":"﴿الْبَيِّنَاتِ﴾ تشمل الحجج الواضحة، و﴿الزُّبُرِ﴾ الكتب المشتملة على المواعظ والحِكَم، و﴿الْكِتَابِ الْمُنِيرِ﴾ الوحي الذي يكشف طريق الهدى؛ فالجمع يبين تنوع ما جاءت به الرسل من دلائل وهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص414–423.","url":""}]},{"id":"s3-694","number":694,"surah":3,"verses":[184],"verseLabel":"آل عمران: 184","question":"ما سرّ وصف الكتاب بـ﴿المنير﴾؟","answer":"وصفه بـ﴿الْمُنِيرِ﴾ لأنه يكشف الحق ويزيل ظلمات الجهل والضلال، كما يكشف النور الأشياء للناظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص414–423.","url":""}]},{"id":"s3-695","number":695,"surah":3,"verses":[185],"verseLabel":"آل عمران: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿كل نفس ذائقة الموت﴾، وهل الموت يُذاق؟","answer":"استعير الذوق للمباشرة الشخصية التي لا ينوب فيها أحد عن أحد؛ واسم الفاعل يقرر تحقق التجربة لكل نفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423.","url":""}]},{"id":"s3-696","number":696,"surah":3,"verses":[185],"verseLabel":"آل عمران: 185","question":"ما سرّ التعبير في قوله تعالى: ﴿ذائقة﴾ باسم الفاعل لا: تذوق؟","answer":"اسم الفاعل في ﴿ذائقة﴾ يثبت الصفة لصاحبها ويقرر تحققها، وهو أرسخ من فعل عابر مقيد بزمن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423.","url":""}]},{"id":"s3-697","number":697,"surah":3,"verses":[185],"verseLabel":"آل عمران: 185","question":"ما دلالة القصر في قوله تعالى: ﴿وإنما توفون أجوركم يوم القيامة﴾ مع وجود جزاء في الدنيا؟","answer":"﴿إِنَّمَا﴾ تقصر التوفية الكاملة للأجور على يوم القيامة؛ أما ما يقع في الدنيا فليس إلا بعض الجزاء أو مقدمة له، ولا يبلغ تمام الجزاء الأخروي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423.","url":""}]},{"id":"s3-698","number":698,"surah":3,"verses":[185],"verseLabel":"آل عمران: 185","question":"ما سرّ تصوير النجاة بقوله تعالى: ﴿فمن زحزح عن النار﴾؟","answer":"﴿زُحْزِحَ﴾ تدل على الإبعاد شيئًا فشيئًا وبقوة عن خطر قريب؛ فتصور شدة النجاة من النار وعظم المنة بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423.","url":""}]},{"id":"s3-699","number":699,"surah":3,"verses":[185],"verseLabel":"آل عمران: 185","question":"لماذا قدّم الزحزحة عن النار على إدخال الجنة؟","answer":"لأن النجاة من أعظم مرهوب مقدمة الفوز، ثم يكتمل بإدخال الجنة؛ فجمع دفع الشر وجلب الخير ورتبهما بحسب المرور يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423.","url":""}]},{"id":"s3-700","number":700,"surah":3,"verses":[185],"verseLabel":"آل عمران: 185","question":"ما دلالة الإيجاز والتوكيد في قوله تعالى: ﴿فقد فاز﴾؟","answer":"﴿قَدْ﴾ تحقق الفوز، والفعل الموجز ﴿فَازَ﴾ يجمع النجاة من المكروه والظفر بالمطلوب: الزحزحة عن النار ودخول الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423.","url":""}]},{"id":"s3-701","number":701,"surah":3,"verses":[185],"verseLabel":"آل عمران: 185","question":"ما سرّ وصف الحياة الدنيا بأنها ﴿متاع الغرور﴾؟","answer":"المتاع ما ينتفع به زمنًا ثم ينقضي، وإضافته إلى الغرور تبين أن الدنيا تخدع من ركن إلى زينتها فحسبها غاية باقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423.","url":""}]},{"id":"s3-702","number":702,"surah":3,"verses":[57],"verseLabel":"آل عمران: 185؛ الأنبياء: 35؛ العنكبوت: 57","question":"لماذا تكررت ﴿كل نفس ذائقة الموت﴾ ثم اختلف ما بعدها في آل عمران والأنبياء والعنكبوت؟","answer":"آل عمران في سياق العمل والجزاء فأتبعها بتوفية الأجور والفوز، والأنبياء في سياق الابتلاء فأتبعها بفتنة الخير والشر، والعنكبوت في سياق الهجرة والرجوع فأتبعها بالرجوع إلى الله؛ فالحقيقة الواحدة صارت مدخلًا للغرض الذي تعالجه كل سورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص418–423؛ ج30 وج41 في موضعي الأنبياء: 35 والعنكبوت: 57.","url":""}]},{"id":"s3-703","number":703,"surah":3,"verses":[186],"verseLabel":"آل عمران: 186","question":"لماذا قدّم الابتلاء في الأموال على الأنفس؟","answer":"لأن أذى المال أكثر تكررًا وأسبق وقوعًا في النفقة والخسارة، ثم ارتقى إلى ما هو أشد وهو أذى الأنفس؛ فالتقديم يراعي الكثرة والتدرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص423–432.","url":""}]},{"id":"s3-704","number":704,"surah":3,"verses":[186],"verseLabel":"آل عمران: 186","question":"ما دلالة توكيد الابتلاء بلام القسم ونون التوكيد في ﴿لتبلون﴾ و﴿لتسمعن﴾؟","answer":"لام القسم ونون التوكيد الثقيلة تثبتان حتمية الابتلاء وسماع الأذى، ليتهيأ المؤمنون لهما بالصبر والتقوى فلا يفجآهم وقوعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص423–432.","url":""}]},{"id":"s3-705","number":705,"surah":3,"verses":[186],"verseLabel":"آل عمران: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتسمعن... أذى كثيرًا﴾، فجعل الأذى مسموعًا؟","answer":"المراد ما يسمعونه من أقوال مؤذية؛ فسمي القول أذًى باسم أثره، و﴿كَثِيرًا﴾ تبين تكرر هذا الأذى وكثرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص423–432.","url":""}]},{"id":"s3-706","number":706,"surah":3,"verses":[186],"verseLabel":"آل عمران: 186","question":"لماذا جمع أذى أهل الكتاب والمشركين في آية واحدة؟","answer":"ليتهيأ المؤمنون لاجتماع مصادر العداوة المختلفة على أذاهم، فلا يفاجئهم صدوره ممن عنده كتاب ولا ممن يعلن الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص423–432.","url":""}]},{"id":"s3-707","number":707,"surah":3,"verses":[186],"verseLabel":"آل عمران: 186","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن تصبروا وتتقوا فإن ذلك من عزم الأمور﴾؟","answer":"الصبر يضبط احتمال الأذى، والتقوى تضبط الرد عليه، ووصفهما بالعزم لأن الثبات الأخلاقي عند الاستفزاز يحتاج إرادة راسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص423–432.","url":""}]},{"id":"s3-708","number":708,"surah":3,"verses":[187],"verseLabel":"آل عمران: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ أخذ الله ميثاق الذين أوتوا الكتاب﴾؟","answer":"أخذ الميثاق تصوير للعهد المؤكد كأنه شيء يُقبض ويُستوثق منه؛ وفيه تشديد لإلزام أهل الكتاب ببيان ما أوتوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص432–443.","url":""}]},{"id":"s3-709","number":709,"surah":3,"verses":[187],"verseLabel":"آل عمران: 187","question":"ما دلالة تقديم ﴿لتبيننه للناس﴾ على ﴿ولا تكتمونه﴾؟","answer":"بدأ بالواجب الإيجابي: بيان الكتاب للناس، ثم نهى عن نقيضه وهو الكتمان؛ لأن المقصود ليس مجرد ترك الإخفاء، بل أداء العلم ونشره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص432–443.","url":""}]},{"id":"s3-710","number":710,"surah":3,"verses":[187],"verseLabel":"آل عمران: 187","question":"لماذا صوّر ترك الميثاق بقوله ﴿فنبذوه وراء ظهورهم﴾؟","answer":"صوّر إهمال الميثاق بكتاب يُرمى خلف الظهر فلا يُرى ولا يُرجع إليه؛ وهي أبلغ من مجرد الترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص443.","url":""}]},{"id":"s3-711","number":711,"surah":3,"verses":[187],"verseLabel":"آل عمران: 187","question":"ما سرّ التعبير في قوله تعالى: ﴿واشتروا به ثمنًا قليلًا﴾؟","answer":"صوّر إيثارهم المنفعة العاجلة صفقةً باعوا فيها الميثاق والبيان بثمن دنيوي قليل؛ وفي الصورة إظهار لخسارة المبادلة وحقارة العوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص432–443.","url":""}]},{"id":"s3-712","number":712,"surah":3,"verses":[187],"verseLabel":"آل عمران: 187","question":"ما دلالة المضارع في قوله تعالى: ﴿فبئس ما يشترون﴾، دون: ما اشتروا؟","answer":"المضارع ﴿يَشْتَرُونَ﴾ يصور ذلك عادة متجددة، لا صفقة مضت وانتهت، و﴿بِئْسَ﴾ تنشئ ذم هذه التجارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص432–443.","url":""}]},{"id":"s3-713","number":713,"surah":3,"verses":[101],"verseLabel":"آل عمران: 187؛ البقرة: 101","question":"ما سرّ التعبير في قوله تعالى في البقرة ﴿نبذه فريق من الذين أوتوا الكتاب وراء ظهورهم﴾، وفي آل عمران ﴿فنبذوه وراء ظهورهم﴾؟","answer":"البقرة تبعض أهل الكتاب إنصافًا لأن النبذ صدر من فريق، أما آل عمران فقد سبق الموصول ﴿الذين أوتوا الكتاب﴾ وأخذ الميثاق عليهم ثم حكى نقض المخاطبين به، فاستغنى الضمير عن إعادة التبعيض وركز على فداحة مخالفة الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص608–615؛ ج6، ص432–443.","url":""}]},{"id":"s3-714","number":714,"surah":3,"verses":[188],"verseLabel":"آل عمران: 188","question":"ما دلالة الجمع بين قوله تعالى: ﴿يفرحون بما أتوا﴾ و﴿يحبون أن يحمدوا بما لم يفعلوا﴾؟","answer":"جمعت الآية فسادين متلازمين: الابتهاج بما صنعوه من تلبيس، وطلب الثناء على خير لم يفعلوه؛ فليس الخلل في الفعل وحده بل في تزكية النفس أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص443–453.","url":""}]},{"id":"s3-715","number":715,"surah":3,"verses":[188],"verseLabel":"آل عمران: 188","question":"لماذا جمع بين الفرح بالعمل وحب الحمد بغير عمل؟","answer":"الأول إعجاب بالباطل الذي فعلوه، والثاني طلب منزلة لم يحققوها؛ فجمع فساد تقييم العمل وفساد طلب السمعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص443–453.","url":""}]},{"id":"s3-716","number":716,"surah":3,"verses":[188],"verseLabel":"آل عمران: 188","question":"ما دلالة تكرار النهي في قوله تعالى: ﴿فلا تحسبنهم بمفازة من العذاب﴾ بعد قوله: ﴿لا تحسبن الذين يفرحون﴾؟","answer":"طالت الصلة بذكر حالين، فأعيد النهي في ﴿فَلَا تَحْسَبَنَّهُمْ﴾ لتجديد التحذير وإبراز نتيجته: أنهم ليسوا بمنجاة من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص443–453.","url":""}]},{"id":"s3-717","number":717,"surah":3,"verses":[188],"verseLabel":"آل عمران: 188","question":"ما سرّ التعبير في قوله تعالى: ﴿بمفازة من العذاب﴾، فجعل النجاة مكانًا؟","answer":"﴿مَفَازَةٍ﴾ موضع فوز ونجاة، فتصور السلامة كحيز بعيد عن العذاب ثم تنفي أن يكونوا فيه؛ فيقوى نفي نجاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص443–453.","url":""}]},{"id":"s3-718","number":718,"surah":3,"verses":[188],"verseLabel":"آل عمران: 188","question":"ما مناسبة ختام الآية بقوله تعالى: ﴿ولهم عذاب أليم﴾؟","answer":"بعد نفي كونهم في موضع نجاة، أثبت لهم المقابل صراحةً: عذابًا مؤلمًا؛ فتم الانتقال من إبطال الوهم إلى تقرير المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص443–453.","url":""}]},{"id":"s3-719","number":719,"surah":3,"verses":[189],"verseLabel":"آل عمران: 189","question":"لماذا تكرر تقرير ملك السماوات والأرض قبيل آيات التفكر؟","answer":"ليجعل النظر في الكون نظرًا في ملك الله وآيات قدرته لا تأملًا منفصلًا عن العبادة، وليمهد للاستدلال من الخلق على الحكمة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص453–458.","url":""}]},{"id":"s3-720","number":720,"surah":3,"verses":[189],"verseLabel":"آل عمران: 189","question":"ما مناسبة الجمع بين ملك السماوات والأرض والقدرة على كل شيء في قوله تعالى: ﴿ولله ملك السماوات والأرض والله على كل شيء قدير﴾؟","answer":"ملك السماوات والأرض يثبت شمول السلطان، والقدرة على كل شيء تثبت نفاذه؛ فليس بعسير على مالك الكون أن يبعث الخلق ويحاسبهم، وهي مناسبة لما قبلها ولآيات التفكر بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص453–458.","url":""}]},{"id":"s3-721","number":721,"surah":3,"verses":[190],"verseLabel":"آل عمران: 190","question":"ما دلالة التوكيد والجمع في قوله تعالى: ﴿إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات﴾؟","answer":"أكدت الجملة بـ﴿إِنَّ﴾ واللام، وجمعت ﴿آيَاتٍ﴾؛ لأن في أصل الخلق وتعاقب الليل والنهار دلائل كثيرة متجددة، لا علامة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص458–466.","url":""}]},{"id":"s3-722","number":722,"surah":3,"verses":[190],"verseLabel":"آل عمران: 190","question":"لماذا قدّم خلق السماوات والأرض على اختلاف الليل والنهار؟","answer":"بدأ بالأجرام والأصول الثابتة، ثم أتبعها بالنظام المتحرك الناشئ عنها؛ فانتقل من بناء الكون إلى تعاقب ظواهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص458–466.","url":""}]},{"id":"s3-723","number":723,"surah":3,"verses":[190],"verseLabel":"آل عمران: 190","question":"ما سرّ تخصيص الانتفاع بهذه الآيات بـ﴿أولي الألباب﴾؟","answer":"الألباب العقول الخالصة من شوائب الغفلة؛ فهذه الآيات يراها الناس جميعًا، لكن أصحاب العقول المتدبرة هم الذين ينفذون من ظاهرها إلى دلالتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص458–466.","url":""}]},{"id":"s3-724","number":724,"surah":3,"verses":[191],"verseLabel":"آل عمران: 191","question":"ما دلالة ترتيب أحوال الذكر في قوله تعالى: ﴿قيامًا وقعودًا وعلى جنوبهم﴾؟","answer":"شملت الأحوال الثلاثة هيئة الإنسان قائمًا وقاعدًا ومضطجعًا، ورتبتها من حال القوة والحركة إلى حال الراحة؛ لتدل على استمرار الذكر في جميع الأحوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص466–476.","url":""}]},{"id":"s3-725","number":725,"surah":3,"verses":[191],"verseLabel":"آل عمران: 191","question":"لماذا انتقل من ذكر الله إلى التفكر في خلق السماوات والأرض؟","answer":"لأن الذكر يوقظ القلب والتفكر يقيم الدليل في العقل؛ وباجتماعهما تتحول مشاهدة الكون إلى معرفة وخشية ودعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص466–476.","url":""}]},{"id":"s3-726","number":726,"surah":3,"verses":[191],"verseLabel":"آل عمران: 191","question":"ما دلالة اسم الإشارة المفرد في دعائهم: ﴿ربنا ما خلقت هذا باطلًا﴾؟","answer":"أفرد اسم الإشارة لأن السماوات والأرض واختلاف الليل والنهار نُظر إليها كنظام كوني واحد متماسك يشهد بالحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص466–476.","url":""}]},{"id":"s3-727","number":727,"surah":3,"verses":[191],"verseLabel":"آل عمران: 191","question":"ما مناسبة قولهم ﴿سبحانك﴾ بين الاعتراف بحكمة الخلق وطلب الوقاية من النار؟","answer":"﴿سُبْحَانَكَ﴾ تنزيه لله عن أن يخلق هذا الكون عبثًا؛ فلما أثبتوا للخلق حكمة نزهوه عن الباطل، ثم بنوا على ذلك طلب الوقاية من النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص466–476.","url":""}]},{"id":"s3-728","number":728,"surah":3,"verses":[191],"verseLabel":"آل عمران: 191","question":"ما مناسبة دعائهم: ﴿فقنا عذاب النار﴾ بعد التفكر في الكون؟","answer":"دلهم انتظام الكون وحكمة خلقه على أن الخلق ليس عبثًا، وأن وراءه حسابًا وجزاءً؛ فتحول التفكر إلى دعاء بالنجاة والعمل لمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص466–476.","url":""}]},{"id":"s3-729","number":729,"surah":3,"verses":[192],"verseLabel":"آل عمران: 192","question":"ما سرّ التعبير في قوله تعالى: ﴿إنك من تدخل النار فقد أخزيته﴾، فجعل دخول النار خزيًا؟","answer":"إدخال النار خزي لأنه يجمع العذاب والفضيحة والحرمان من الكرامة، و﴿قَدْ﴾ تحقق ملازمة هذا الخزي لمن أدخله الله النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص476–482.","url":""}]},{"id":"s3-730","number":730,"surah":3,"verses":[192],"verseLabel":"آل عمران: 192","question":"ما دلالة الجمع ودخول ﴿من﴾ في قوله تعالى: ﴿وما للظالمين من أنصار﴾؟","answer":"دخول ﴿مِنْ﴾ في سياق النفي يستغرق أي نصير، وجمع ﴿أَنْصَارٍ﴾ ينفي عن الظالمين كل فرد وكل جماعة يمكن أن تنصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص476–482.","url":""}]},{"id":"s3-731","number":731,"surah":3,"verses":[193],"verseLabel":"آل عمران: 193","question":"ما دلالة الجمع بين الاسم والفعل من مادة واحدة في قوله تعالى: ﴿إننا سمعنا مناديًا ينادي للإيمان﴾؟","answer":"الجمع بين ﴿مُنَادِيًا﴾ و﴿يُنَادِي﴾ يثبت ذات المنادي ويستحضر تجدد ندائه، فيبرز قوة الدعوة ووضوح وصولها إلى السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص488.","url":""}]},{"id":"s3-732","number":732,"surah":3,"verses":[193],"verseLabel":"آل عمران: 193","question":"لماذا لم يصرّحوا باسم المنادي؟","answer":"لأن المقصود مضمون النداء وأثره لا ذات المنادي، ولأن إبهامه يفخمه: منادٍ عظيم الشأن يدعو إلى أعظم مطلوب وهو الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص482–492.","url":""}]},{"id":"s3-733","number":733,"surah":3,"verses":[193],"verseLabel":"آل عمران: 193","question":"ما دلالة تفسير النداء بقوله تعالى: ﴿أن آمنوا بربكم فآمنا﴾؟","answer":"﴿أَنْ آمِنُوا﴾ تفسر مضمون النداء، والفاء في ﴿فَآمَنَّا﴾ تدل على سرعة الاستجابة واتصالها بالدعوة بلا تراخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص482–492.","url":""}]},{"id":"s3-734","number":734,"surah":3,"verses":[193],"verseLabel":"آل عمران: 193","question":"لماذا رتبوا الدعاء: مغفرة الذنوب، وتكفير السيئات، ثم الوفاة مع الأبرار؟","answer":"سألوا غفران الأصول العظيمة، ثم ستر آثار السيئات ومحوها، ثم حسن الخاتمة واللحاق بالأبرار؛ فانتقلوا من تطهير الماضي إلى تأمين المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص482–492.","url":""}]},{"id":"s3-735","number":735,"surah":3,"verses":[193],"verseLabel":"آل عمران: 193","question":"ما دلالة الجمع بين ﴿ذنوبنا﴾ و﴿سيئاتنا﴾ في الدعاء؟","answer":"الذنوب تُلحظ من جهة ما يجنيه العبد من تبعتها، والسيئات من جهة قبح الأعمال وآثارها؛ فجمعوا في الدعاء طلب المغفرة والستر والتكفير والمحو، من غير لزوم تقسيم كل لفظ إلى نوع مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص482–492.","url":""}]},{"id":"s3-736","number":736,"surah":3,"verses":[194],"verseLabel":"آل عمران: 194","question":"ما سرّ التعبير في دعائهم: ﴿وآتنا ما وعدتنا على رسلك﴾، دون أن يقال: على ألسنة رسلك؟","answer":"التعبير بـ﴿عَلَى رُسُلِكَ﴾ موجز، أي: ما وعدتنا على ألسنة رسلك أو بسبب تبليغهم؛ فحذف المضاف اعتمادًا على وضوح المعنى، مع إبراز منزلة الرسل وساطتهم في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص492–498.","url":""}]},{"id":"s3-737","number":737,"surah":3,"verses":[194],"verseLabel":"آل عمران: 194","question":"لماذا طلبوا إنجاز الوعد مع يقينهم أن الله لا يخلف الميعاد؟","answer":"ليس شكًا في الوعد، بل تضرع لطلب الدخول في أهله والثبات على أسبابه؛ فالخشية متجهة إلى تقصيرهم لا إلى خلف من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص492–498.","url":""}]},{"id":"s3-738","number":738,"surah":3,"verses":[194],"verseLabel":"آل عمران: 194","question":"ما سرّ تخصيص نفي الخزي بقولهم: ﴿يوم القيامة﴾؟","answer":"لأن خزي يوم القيامة هو الخزي الأعظم الظاهر الذي لا تدارك بعده، فسألوا السلامة منه خاصةً مع دخوله في عموم قولهم: ﴿فَقِنَا عَذَابَ النَّارِ﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص492–498.","url":""}]},{"id":"s3-739","number":739,"surah":3,"verses":[194],"verseLabel":"آل عمران: 194","question":"ما مناسبة ختم الدعاء بقولهم: ﴿إنك لا تخلف الميعاد﴾؟","answer":"ليس قولهم شكًا في الوعد، بل توسل بصدق وعد الله وثناء عليه؛ أي اجعلنا ممن يتحقق فيهم وعدك ولا تجعلنا ممن حرمته أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص492–498.","url":""}]},{"id":"s3-740","number":740,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستجاب لهم ربهم﴾ لا ﴿فأجابهم﴾؟","answer":"الاستجابة تفيد قبول الدعاء وتحقيق مقتضاه، وإظهار ﴿ربهم﴾ يربط الإجابة بالتربية والرعاية والقرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-741","number":741,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"ما سرّ إظهار وصف الربوبية في قوله تعالى: ﴿ربهم﴾؟","answer":"وصف الربوبية أنسب بمقام الدعاء والاستجابة؛ لما فيه من معنى الرعاية والتربية والإنعام على عباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-742","number":742,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير في قوله تعالى: ﴿أني لا أضيع عمل عامل منكم﴾، فجعل العمل شيئًا يضيع؟","answer":"صوّر العمل كشيء محفوظ لصاحبه لا يضيع ولا يفقد؛ وفيه ضمان واضح أن أي عمل صالح لن يبطل جزاؤه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-743","number":743,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"ما دلالة التصريح بقوله تعالى: ﴿من ذكر أو أنثى﴾ بعد عموم ﴿عامل﴾؟","answer":"التصريح بالذكر والأنثى يرفع أي توهم أن لفظ ﴿عَامِلٍ﴾ أو الخطاب السابق يختص بالرجال، ويقرر تساويهما في حفظ العمل والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-744","number":744,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"لماذا اعترض بقوله ﴿بعضكم من بعض﴾؟","answer":"اعتراض يقرر وحدة الأصل والتكليف والتناصر، وينفي أن يضيع عمل بسبب الذكورة أو الأنوثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-745","number":745,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"لماذا رُتبت الأعمال: الهجرة، والإخراج، والأذى، والقتال، والقتل؟","answer":"تصاعدت من مفارقة الوطن، إلى الإكراه على الخروج، إلى تحمل الأذى، ثم مباشرة القتال، ثم بذل النفس؛ فوافق تصاعد الجزاء تصاعد التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-746","number":746,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"لماذا أكّد التكفير والإدخال بلام ونون التوكيد؟","answer":"لتثبيت الوعد بعد ذكر أقصى التضحيات وقطع توهم ضياع شيء منها؛ فاللام والنون تنقلان الجزاء إلى وعد محقق مؤكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-747","number":747,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿ثوابًا من عند الله﴾ بعد تفصيل الجزاء؟","answer":"المصدر ﴿ثَوَابًا﴾ يؤكد معنى الجزاء، و﴿مِنْ عِنْدِ اللَّهِ﴾ تبين شرف منشئه وأن ما فصّل من التكفير والجنة عطاء إلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-748","number":748,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"ما دلالة ختم الآية بقوله تعالى: ﴿والله عنده حسن الثواب﴾؟","answer":"﴿عِنْدَهُ﴾ تفيد أن مصدر الثواب ومخزنه عند الله، و﴿حُسْنُ الثَّوَابِ﴾ تجمع كمال الجزاء؛ فختمت الوعد بتعظيم ما لديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514.","url":""}]},{"id":"s3-749","number":749,"surah":3,"verses":[195],"verseLabel":"آل عمران: 195","question":"ما الفرق بين قوله تعالى في النساء: ﴿ومن يعمل من الصالحات من ذكر أو أنثى﴾، وقوله في آل عمران: ﴿لا أضيع عمل عامل منكم من ذكر أو أنثى﴾؟","answer":"آية النساء تقرر قاعدة عامة: من جمع الإيمان والعمل الصالح دخل الجنة ولم يظلم. أما آية آل عمران فجاءت جوابًا لدعاء المؤمنين وبعد ذكر هجرتهم وأذاهم، فناسبها ضمان ألا يضيع عمل أي عامل مع التصريح بالذكر والأنثى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514؛ مسح عكسي.","url":""}]},{"id":"s3-750","number":750,"surah":3,"verses":[196],"verseLabel":"آل عمران: 196","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يغرنك تقلب الذين كفروا في البلاد﴾، وما الصورة التي يرسمها ﴿تقلب﴾؟","answer":"﴿تَقَلُّبُ﴾ يصور ترددهم بحرية من بلد إلى بلد في التجارة والمكاسب والتصرف، وهي حركة رخاء ظاهرة قد تغر الناظر؛ فجاء النهي عن الاغترار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص514–524.","url":""}]},{"id":"s3-751","number":751,"surah":3,"verses":[196],"verseLabel":"آل عمران: 196","question":"لماذا أُفرد خطاب النبي في نهي يراد به تثبيت المؤمنين؟","answer":"لأن ثبات القائد أبلغ طريق إلى تثبيت الجماعة، والخطاب له تشريف وتعليم لكل سامع؛ فإذا نُهي الرسول عن الاغترار بتقلب الكافرين فالأمة أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص514–524.","url":""}]},{"id":"s3-752","number":752,"surah":3,"verses":[196],"verseLabel":"آل عمران: 196","question":"ما سرّ التعبير بقوله تعالى: ﴿في البلاد﴾، دون: في الأرض؟","answer":"البلاد هي المواطن المعمورة ومراكز التجارة والسلطان التي يظهر فيها تقلبهم ومكاسبهم؛ وهي أدق هنا من الأرض التي تشمل المعمور وغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص514–524.","url":""}]},{"id":"s3-753","number":753,"surah":3,"verses":[4],"verseLabel":"آل عمران: 196؛ غافر: 4","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آل عمران: ﴿لا يغرنك تقلب الذين كفروا في البلاد﴾، وقوله في غافر: ﴿فلا يغررك تقلبهم في البلاد﴾؟","answer":"في آل عمران جاء النهي ابتداءً، وصرح بـ﴿الَّذِينَ كَفَرُوا﴾، وأكد الفعل بنون التوكيد الثقيلة: ﴿يَغُرَّنَّكَ﴾. وفي غافر جاء بالفاء نتيجةً لما قبلها، واكتفى بالضمير بعد ذكر الكافرين، وجاء الفعل مجزومًا بلا نون: ﴿يَغْرُرْكَ﴾؛ فناسب كل تعبير سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص514–524، مع غافر: 4.","url":""}]},{"id":"s3-754","number":754,"surah":3,"verses":[197],"verseLabel":"آل عمران: 197","question":"ما دلالة إيجاز نجاحهم الدنيوي في قوله تعالى: ﴿متاع قليل﴾؟","answer":"﴿مَتَاعٌ﴾ يحصره في منفعة عابرة، و﴿قَلِيلٌ﴾ تحقر قدره ومدته؛ فاختزل اللفظان كل ما يبدو من نجاحهم في حقيقته الزائلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص514–524.","url":""}]},{"id":"s3-755","number":755,"surah":3,"verses":[197],"verseLabel":"آل عمران: 197","question":"ما دلالة ﴿ثم﴾ في قوله تعالى: ﴿ثم مأواهم جهنم﴾؟","answer":"﴿ثُمَّ﴾ تفيد التراخي الزمني، وتبرز كذلك البون بين المتاع العابر والمصير الثقيل. و﴿مَأْوَاهُمْ﴾ تسمي جهنم مقرهم النهائي بعد ذلك التقلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص514–524.","url":""}]},{"id":"s3-756","number":756,"surah":3,"verses":[197],"verseLabel":"آل عمران: 197","question":"لماذا ختم بـ﴿وبئس المهاد﴾، وسمّى جهنم مهادًا؟","answer":"سمّى النار مهادًا على سبيل التهكم؛ فالمهاد موضع الراحة، أما هذا المهاد فغاية العذاب، وفي التضاد زيادة تهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص514–524.","url":""}]},{"id":"s3-757","number":757,"surah":3,"verses":[198],"verseLabel":"آل عمران: 198","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الذين اتقوا ربهم﴾ بعد وصف حال الكافرين؟","answer":"﴿لَكِنِ﴾ تقطع توهم أن ظاهر الرخاء هو المعيار، وتنقل إلى المصير المقابل للمتقين: نعيم دائم بإزاء المتاع القليل والمهاد السيئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص524–532.","url":""}]},{"id":"s3-758","number":758,"surah":3,"verses":[198],"verseLabel":"آل عمران: 198","question":"ما دلالة قوله تعالى: ﴿لهم جنات تجري من تحتها الأنهار خالدين فيها﴾ في مقابلة ﴿متاع قليل﴾؟","answer":"قدمت الآية ملكهم للجزاء بـ﴿لَهُمْ﴾، وجمعت الجنات، ووصفت جريان الأنهار والخلود؛ فاجتمعت سعة النعيم ودوامه في مقابلة متاع الكافرين القليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص524–532.","url":""}]},{"id":"s3-759","number":759,"surah":3,"verses":[198],"verseLabel":"آل عمران: 198","question":"لماذا سمّى نعيم الجنة ﴿نزلًا من عند الله﴾؟","answer":"النزل ما يهيأ للضيف عند قدومه؛ فإذا كان نعيم الجنة مجرد نزل من عند الله فما بعده أعظم وأدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص524–532.","url":""}]},{"id":"s3-760","number":760,"surah":3,"verses":[198],"verseLabel":"آل عمران: 198","question":"ما سرّ التعبير بقوله تعالى: ﴿وما عند الله خير للأبرار﴾، دون: للمتقين كما في أول الآية؟","answer":"﴿الْأَبْرَارِ﴾ تصفهم بتحقق البر واتساع وجوه الخير فيهم؛ فبعد ذكر تقواهم أولًا ختم بصفة تظهر ثمرة التقوى وكمال صلاحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص524–532.","url":""}]},{"id":"s3-761","number":761,"surah":3,"verses":[199],"verseLabel":"آل عمران: 199","question":"ما دلالة قوله تعالى: ﴿وإن من أهل الكتاب لمن يؤمن بالله﴾ بعد الآيات التي نقدت مواقف فريق منهم؟","answer":"الاستثناء المنصف يبين أن الذم السابق لم يكن تعميمًا على أهل الكتاب؛ و﴿إِنَّ﴾ واللام في ﴿لَمَنْ﴾ تؤكدان وجود فريق صادق الإيمان منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص532–543.","url":""}]},{"id":"s3-762","number":762,"surah":3,"verses":[199],"verseLabel":"آل عمران: 199","question":"لماذا جمع بين ﴿ما أنزل إليكم وما أنزل إليهم﴾؟","answer":"ليثبت أن إيمان الصادقين من أهل الكتاب لا يتجزأ: يصدقون بالقرآن وبأصل الوحي الذي عندهم، فيلتقي التنزيلان عند مصدر واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص532–543.","url":""}]},{"id":"s3-763","number":763,"surah":3,"verses":[199],"verseLabel":"آل عمران: 199","question":"ما دلالة وصفهم بقوله تعالى: ﴿خاشعين لله﴾ بين صفات الإيمان؟","answer":"الخشوع هيئة باطنة من الذل والتعظيم لله، فجاء وسط صفات الإيمان علامةً على صدقها، وعلى أن علمهم لم يحملهم على الكتمان والاتجار بالآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص532–543.","url":""}]},{"id":"s3-764","number":764,"surah":3,"verses":[199],"verseLabel":"آل عمران: 199","question":"ما دلالة قوله تعالى: ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾ في مقابل من سبق ذكرهم؟","answer":"جاء النفي في مقابلة من باعوا عهد الله وآياته بثمن قليل؛ فهؤلاء لا يستبدلون بالوحي منفعة دنيوية مهما بدت.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص532–543.","url":""}]},{"id":"s3-765","number":765,"surah":3,"verses":[199],"verseLabel":"آل عمران: 199","question":"ما سرّ إضافة الأجر إليهم في قوله تعالى: ﴿أولئك لهم أجرهم عند ربهم﴾؟","answer":"اللام في ﴿لَهُمْ﴾ تثبت استحقاق الأجر الموعود لهم بفضل الله، و﴿عِنْدَ رَبِّهِمْ﴾ تضيف معنى الكرامة والأمن والرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص532–543.","url":""}]},{"id":"s3-766","number":766,"surah":3,"verses":[199],"verseLabel":"آل عمران: 199","question":"لماذا ختم بـ﴿إن الله سريع الحساب﴾ في مقام الوعد؟","answer":"سرعة الحساب تطمئن إلى قرب الوفاء، وتحذر من توهم أن كثرة الخلق أو الأعمال تؤخر الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص532–543.","url":""}]},{"id":"s3-767","number":767,"surah":3,"verses":[77],"verseLabel":"آل عمران: 199؛ آل عمران: 77","question":"لماذا قوبل من ﴿يشترون بعهد الله وأيمانهم ثمنًا قليلًا﴾ بمن ﴿لا يشترون بآيات الله ثمنًا قليلًا﴾ في آخر السورة؟","answer":"التركيب الواحد يقيم ميزانًا داخل أهل الكتاب: فريق باع العهد والآيات فعوقب بالحرمان، وفريق آمن وخشع ورفض البيع فثبت له الأجر؛ فالمقابلة تختم السورة بالإنصاف بعد النقد.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص310–321؛ ج6، ص532–543.","url":""}]},{"id":"s3-768","number":768,"surah":3,"verses":[200],"verseLabel":"آل عمران: 200","question":"ما دلالة اجتماع الأوامر الأربعة في خاتمة السورة: ﴿اصبروا وصابروا ورابطوا واتقوا الله﴾؟","answer":"بدأت الأوامر بصبر النفس، ثم مصابرة الخصم والثبات أمامه، ثم المرابطة والاستعداد الدائم، وختمت بالتقوى التي تضبط ذلك كله؛ فجمعت أسباب الثبات والفلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص543–564.","url":""}]},{"id":"s3-769","number":769,"surah":3,"verses":[200],"verseLabel":"آل عمران: 200","question":"ما الفرق بين ﴿اصبروا﴾ و﴿صابروا﴾، وما الذي زادته صيغة المفاعلة؟","answer":"﴿اصْبِرُوا﴾ أمر لكل مؤمن أن يلزم الصبر، و﴿صَابِرُوا﴾ بصيغة المفاعلة تزيد معنى مقابلة صبر العدو بصبر أثبت وأطول حتى لا يغلبكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص543–564.","url":""}]},{"id":"s3-770","number":770,"surah":3,"verses":[200],"verseLabel":"آل عمران: 200","question":"ما مناسبة إتباع الصبر والمصابرة بالأمر: ﴿ورابطوا﴾؟","answer":"المرابطة تزيد على احتمال المشقة معنى ملازمة مواقع الطاعة والحراسة والاستعداد؛ فتنقل المؤمن من مجرد الثبات عند البلاء إلى دوام اليقظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص543–564.","url":""}]},{"id":"s3-771","number":771,"surah":3,"verses":[200],"verseLabel":"آل عمران: 200","question":"ما دلالة ختم الأوامر بقوله تعالى: ﴿واتقوا الله﴾؟","answer":"التقوى أصل جامع يصون الصبر والمصابرة والمرابطة من الانحراف والرياء والتعدي، ويجعلها كلها لله وعلى حدوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص543–564.","url":""}]},{"id":"s3-772","number":772,"surah":3,"verses":[200],"verseLabel":"آل عمران: 200","question":"ما دلالة تعليق الفلاح على هذه الأوامر في قوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"﴿لَعَلَّكُمْ﴾ تحض على امتثال هذه المنظومة من الأوامر رجاء الفلاح؛ فالفلاح ثمرة اجتماع الصبر والمصابرة والمرابطة والتقوى، لا مجرد دعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص543–564.","url":""}]},{"id":"s4-1","number":1,"surah":4,"verses":[1],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿اتَّقُوا رَبَّكُمُ﴾، دون أن يقال: اتقوا الله؟","answer":"افتتاح الخطاب باسم الرب يستحضر نعمة الخلق والتربية التي قررتها الآية، فيكون الأمر بالتقوى مبنيًا على رابطة الربوبية؛ ثم جاء الاسم الجليل في التقوى الثانية عند الحقوق التي يُتساءل بها والأرحام.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص576.","url":""}]},{"id":"s4-2","number":2,"surah":4,"verses":[1],"verseLabel":"النساء: 1","question":"لماذا وصف أصل البشر بأنه ﴿نَفْسٍ وَاحِدَةٍ﴾، ولم يصرح باسم آدم عليه السلام؟","answer":"عُدل عن اسم آدم إلى الوصف الجامع ليبرز وحدة الأصل الإنساني؛ ومن ثم تتهيأ النفس لأحكام العدل وصلة الرحم وحفظ حقوق الضعفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص569.","url":""}]},{"id":"s4-3","number":3,"surah":4,"verses":[1],"verseLabel":"النساء: 1","question":"لماذا اختير فعل ﴿بَثَّ﴾، ولم يقل: نشر منهما رجالًا ونساء؟","answer":"البث نشرٌ مع تفريق وتكثير في جهات واسعة، فهو يصور امتداد البشر من أصل واحد أجيالًا وأقطارًا، وهو أبلغ حركةً من مجرد النشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص565.","url":""}]},{"id":"s4-4","number":4,"surah":4,"verses":[1],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿رِجَالًا كَثِيرًا وَنِسَاءً﴾، فوصف الرجال بالكثرة، دون أن يقال: ونساء كثيرات؟","answer":"ذِكر الكثرة مع الرجال يغني عنها في المعطوف، فالمعنى: رجالًا كثيرًا ونساءً كثيرات؛ وحذفها يمنع الثقل ويحفظ الفاصلة من غير أن ينفي كثرة النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص574.","url":""}]},{"id":"s4-5","number":5,"surah":4,"verses":[1],"verseLabel":"النساء: 1","question":"لماذا تكرر الأمر بالتقوى مرتين في آية واحدة: ﴿اتَّقُوا رَبَّكُمُ﴾ ثم ﴿وَاتَّقُوا اللَّهَ﴾؟","answer":"الأولى تقوى الرب الذي خلق البشر من نفس واحدة، والثانية تقوى الله في الحقوق المتبادلة والأرحام؛ فتجدد الأمر لاختلاف العلة والمجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص576.","url":""}]},{"id":"s4-6","number":6,"surah":4,"verses":[1],"verseLabel":"النساء: 1","question":"لماذا ختمت الآية بـ﴿رَقِيبًا﴾، ولم تختم بـ«حفيظًا» مثلًا؟","answer":"الرقيب من يلاحظ الشيء ولا يغيب عنه، وهو أنسب بأحكام الحقوق الخفية وصلات الأرحام؛ أما الحفظ فقد يدل على الصيانة، ولا يستحضر المراقبة والمحاسبة بالوضوح نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص581.","url":""}]},{"id":"s4-7","number":7,"surah":4,"verses":[1],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿وَخَلَقَ مِنْهَا زَوْجَهَا﴾، بينما قال في الأعراف والزمر: ﴿وَجَعَلَ مِنْهَا زَوْجَهَا﴾؟","answer":"﴿خلق﴾ في النساء يبرز ابتداء التكوين ووحدة الأصل في مقام التشريع للأسرة والرحم، أما ﴿جعل﴾ في الأعراف والزمر فيلحظ تصيير الزوج من جنس النفس وجعل السكن والازدواج؛ فكل فعل يوافق زاوية السياق.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج2، ص32؛ منقول في Quranpedia، ملاحظة 48388.","url":""}]},{"id":"s4-8","number":8,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى في حقوق اليتامى: ﴿وَآتُوا الْيَتَامَى أَمْوَالَهُمْ﴾، واختار الإيتاء دون الإعطاء؟","answer":"الإيتاء يشعر بإيصال الحق وتمكين صاحبه منه، لا بمجرد المناولة؛ ولذلك ناسب رد مال اليتيم كاملًا بوصفه حقًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص584، 596.","url":""}]},{"id":"s4-9","number":9,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّهُ كَانَ حُوبًا كَبِيرًا﴾، واختار «الحوب» بدل «الإثم»؟","answer":"الحوب هو الإثم العظيم الذي يوقع في الحرج والهلاك، وفي اللفظ زجر أشد من الاسم العام للإثم، ولا سيما في أكل مال اليتيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص600.","url":""}]},{"id":"s4-10","number":10,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما الصلة بين الخوف من عدم القسط في اليتامى وبين قوله مباشرة: ﴿فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ﴾؟","answer":"كان بعض الأولياء يرغب في اليتيمة التي تحت ولايته فيتزوجها ولا يقسط في مهرها وحقها؛ فخُيّر في غيرها من النساء دفعًا للظلم، وربط التعدد ابتداءً بشرط العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص595–601.","url":""}]},{"id":"s4-11","number":11,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا طَابَ لَكُمْ﴾، دون أن يقال: من طاب لكم؟","answer":"جيء بـ﴿ما﴾ للنظر إلى الوصف والصنف الطيب المباح، لا إلى ذوات النساء مجردة؛ وفيه إبعاد لهن عن أسلوب التملك والتعيين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص603.","url":""}]},{"id":"s4-12","number":12,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾، دون أن يقال: اثنتين أو ثلاثًا أو أربعًا؟","answer":"هذه ألفاظ توزيع: اثنتين اثنتين، وثلاثًا ثلاثًا، وأربعًا أربعًا لكل من أراد؛ فهي تمنع توهم جمع الأعداد أو إطلاق العدد بلا حد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص602–604.","url":""}]},{"id":"s4-13","number":13,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"لماذا عطف الأعداد بالواو: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾، ولم يعطفها بـ«أو» الدالة على التخيير؟","answer":"الواو هنا تعطف صور التوزيع المباحة: مثنى، وثلاث، ورباع؛ فلا تعني جمع الأعداد في عصمة رجل واحد، لأن صيغ التوزيع وسياق الخوف من الجور يحددان المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص604.","url":""}]},{"id":"s4-14","number":14,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكَ أَدْنَى أَلَّا تَعُولُوا﴾، واختار هذا التعبير دون التصريح بـ«ألا تجوروا»؟","answer":"العَول هنا الميل والجور، واختيار اللفظ يلمح كذلك إلى ثقل العيال والمؤنة عند من فسره بذلك؛ فالتعبير أوسع إيحاءً من التصريح بالجور وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص604.","url":""}]},{"id":"s4-15","number":15,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"لماذا سمى المهور ﴿صَدُقَاتِهِنَّ﴾، ولم يقل: مهورهن؟","answer":"اشتق الاسم من الصدق؛ لأن المهر علامة صدق الرغبة في النكاح وتكريم المرأة، لا ثمنًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص606.","url":""}]},{"id":"s4-16","number":16,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"لماذا وصف إعطاء المهر بأنه ﴿نِحْلَةً﴾؟","answer":"النحلة عطية واجبة تؤدى عن طيب نفس من غير منّ ولا عوض مالي، فتنفي ما كان من الاستيلاء على مهر المرأة أو اعتباره تفضلًا من الزوج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص607.","url":""}]},{"id":"s4-17","number":17,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿فَكُلُوهُ هَنِيئًا مَرِيئًا﴾، فخص الأكل وقرن بين «هنيئًا» و«مريئًا»؟","answer":"الهنيء ما لا تنغيص فيه، والمريء ما تحسن عاقبته ولا يضر؛ فاجتماعهما يطمئن الزوج إلى حل ما طابت به نفس زوجته ظاهرًا وباطنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص608.","url":""}]},{"id":"s4-18","number":18,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"لماذا سمى أموال السفهاء ﴿أَمْوَالَكُمُ﴾، مع أنها أموالهم هم؟","answer":"أضاف أموال السفهاء إلى الجماعة لأن المال قوام المجتمع ولأن الولي مؤتمن عليه كأنه ماله؛ فيمنعه ذلك من إضاعته كما يمنع إضاعة مال نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص608–610.","url":""}]},{"id":"s4-19","number":19,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"لماذا وصف الأموال بأنها ﴿الَّتِي جَعَلَ اللَّهُ لَكُمْ قِيَامًا﴾؛ وكيف يكون المال قيامًا للناس؟","answer":"المال تقوم به المعاشات والمصالح، فكأنه ما يقيم حياة الناس ويحفظ استقلالهم؛ لذلك وجب صونه من تصرف السفيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص609.","url":""}]},{"id":"s4-20","number":20,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿وَارْزُقُوهُمْ فِيهَا﴾، دون أن يقال: وارزقوهم منها؟","answer":"﴿فيها﴾ تدعو إلى تنمية أصل المال والإنفاق من ريعه، كأن الرزق واقع في محيط المال لا مقتطع من أصله حتى يفنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص610.","url":""}]},{"id":"s4-21","number":21,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ آنَسْتُمْ مِنْهُمْ رُشْدًا﴾، دون أن يقال: فإن علمتم منهم رشدًا؟","answer":"الإيناس إدراك يتولد من أمارات متكررة ظاهرة، فليس المطلوب ظن الرشد أو معرفته مرة، بل اختباره حتى يطمئن الولي إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص614.","url":""}]},{"id":"s4-22","number":22,"surah":4,"verses":[2,3,4,5,6],"verseLabel":"النساء: 2–6","question":"لماذا أمر بالإشهاد عند دفع مال اليتيم: ﴿فَأَشْهِدُوا عَلَيْهِمْ﴾، ثم ختم بـ﴿وَكَفَى بِاللَّهِ حَسِيبًا﴾؟","answer":"الإشهاد يحفظ الحق في ظاهر التعامل، ويمنع الخصومة عند تسليم المال، ثم جاءت ﴿وَكَفَى بِاللَّهِ حَسِيبًا﴾ لتذكّر بأن وراء شهادة الناس حساب الله المحيط بما خفي من أمانة الولي وتصرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص616–618.","url":""}]},{"id":"s4-23","number":23,"surah":4,"verses":[3],"verseLabel":"النساء: 3","question":"ما الفرق بين التعبير بـ﴿أَلَّا تُقْسِطُوا فِي الْيَتَامَى﴾ والتعبير بـ﴿أَلَّا تَعْدِلُوا﴾ في تعدد الزوجات؟","answer":"القسط استعمل مع حقوق اليتامى لأنه العدل في الحكم وإيصال الحق، ثم استعمل العدل في تعدد الزوجات لأنه التسوية المطلوبة في المعاملة والنفقة؛ فتقارب المعنى لا يلغي دقة كل مقام.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 43211.","url":""}]},{"id":"s4-24","number":24,"surah":4,"verses":[7,8],"verseLabel":"النساء: 7–8","question":"لماذا كرر: ﴿لِلرِّجَالِ نَصِيبٌ﴾ و﴿وَلِلنِّسَاءِ نَصِيبٌ﴾، ولم يجمعهما في عبارة واحدة؟","answer":"أعيد لفظ ﴿نَصِيبٌ﴾ لإثبات أن نصيب النساء مفروض مستقل كنصيب الرجال، لا تابع له ولا تفضلًا من الورثة؛ وفي ذلك إبطال صريح لحرمان النساء من الميراث في الجاهلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص623–626.","url":""}]},{"id":"s4-25","number":25,"surah":4,"verses":[7,8],"verseLabel":"النساء: 7–8","question":"ما سرّ تقديم الرجال على النساء في آية الميراث؟","answer":"قدّم الرجال وفق ترتيب الجنسين في هذا الباب وما حمّلوا من القوامة والمسؤولية، ثم أفرد النساء بجملة مماثلة مستقلة؛ فالمقصود تقرير أصل الاستحقاق لكل منهما، لا جعل حق النساء تابعًا لحق الرجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص623.","url":""}]},{"id":"s4-26","number":26,"surah":4,"verses":[7,8],"verseLabel":"النساء: 7–8","question":"لماذا ذكر ﴿الْوَالِدَانِ﴾ ثم ﴿الْأَقْرَبُونَ﴾، مع أن الوالدين من الأقربين؟","answer":"ذُكر الوالدان أولًا مع دخولهما في الأقربين؛ لأنهما أشد الأقارب اتصالًا بالميت وأعظمهم منزلة، وهما أصل باب القرابة، فكان ذكر الخاص قبل العام إظهارًا للعناية بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص624–625.","url":""}]},{"id":"s4-27","number":27,"surah":4,"verses":[7,8],"verseLabel":"النساء: 7–8","question":"لماذا أعاد قوله: ﴿مِمَّا تَرَكَ الْوَالِدَانِ وَالْأَقْرَبُونَ﴾، ولم يكتف بضمير يعود إلى المذكور؟","answer":"أعيدت العبارة نفسها مع الرجال والنساء ليأتي حكم كل فريق مستقلًا صريحًا، وليؤكد أن مصدر النصيب واحد: ما ترك الوالدان والأقربون، قليلًا كان أو كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص626–627.","url":""}]},{"id":"s4-28","number":28,"surah":4,"verses":[7,8],"verseLabel":"النساء: 7–8","question":"ما سرّ التعبير في قوله تعالى: ﴿نَصِيبًا مَفْرُوضًا﴾، دون أن يقال: حظًا معلومًا؟","answer":"النصيب حصة مخصوصة، و﴿مفروضًا﴾ تثبت أنها مقدرة ملزمة من الله لا منحة عائلية قابلة للمنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص628–630، 638.","url":""}]},{"id":"s4-29","number":29,"surah":4,"verses":[7,8],"verseLabel":"النساء: 7–8","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا حَضَرَ الْقِسْمَةَ﴾ بـ«إذا»، دون أن يقال: وإن حضر القسمة؟","answer":"﴿إِذَا﴾ تستعمل فيما يتوقع وقوعه؛ فحضور القسمة موقف متكرر متحقق الوقوع، وجاء الحكم منظمًا لما ينبغي فعله عند حصوله، لا معلقًا على احتمال بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص631.","url":""}]},{"id":"s4-30","number":30,"surah":4,"verses":[7,8],"verseLabel":"النساء: 7–8","question":"لماذا سمى ما يعطى الحاضرين عند القسمة رزقًا: ﴿فَارْزُقُوهُمْ مِنْهُ﴾، ولم يقل: فأعطوهم؟","answer":"سمّى ما يعطَونه ﴿رِزْقًا﴾ تطييبًا لنفوسهم وإشعارًا بأن ما يصل إليهم فضل ساقه الله، مع أنهم ليسوا من أصحاب الأنصبة المفروضة؛ فالإعطاء هنا صلة وإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص634–636.","url":""}]},{"id":"s4-31","number":31,"surah":4,"verses":[9,10],"verseLabel":"النساء: 9–10","question":"لماذا جمع بين الأمر بالتقوى والأمر بالقول السديد في حماية اليتامى؟","answer":"التقوى تضبط باطن المتصرف في مال اليتيم وتمنعه من الخيانة، والقول السديد يقيم ظاهر معاملته ووصيته على الحق؛ فجمعت الآية صلاح النية وصواب القول الذي يحفظ الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص646–649.","url":""}]},{"id":"s4-32","number":32,"surah":4,"verses":[9,10],"verseLabel":"النساء: 9–10","question":"ما سرّ التعبير في قوله تعالى: ﴿قَوْلًا سَدِيدًا﴾ هنا، بينما قال قبلها: ﴿قَوْلًا مَعْرُوفًا﴾؟","answer":"السديد هو المصيب المستقيم الذي يسد موضع الخلل؛ فناسب مقام الوصية بحماية اليتيم، أما المعروف ففي مقام الملاطفة والعطاء لمن حضر القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص640.","url":""}]},{"id":"s4-33","number":33,"surah":4,"verses":[9,10],"verseLabel":"النساء: 9–10","question":"ما سر الصورة المروعة في قوله: ﴿يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا﴾، مع أنهم يأكلون أموالًا؟","answer":"صوّر المال الحرام بحقيقته التي يصير إليها: نارًا تملأ البطون؛ فانتقل من ظاهر اللذة العاجلة إلى باطن العاقبة المروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص653.","url":""}]},{"id":"s4-34","number":34,"surah":4,"verses":[9,10],"verseLabel":"النساء: 9–10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَسَيَصْلَوْنَ سَعِيرًا﴾ بالسين، ولم يأت بها في فعل الأكل؟","answer":"جاء أكل مال اليتيم بصيغة الحال لأنه واقع منهم، وكشف النص حقيقته بأنه نار؛ أما ﴿سَيَصْلَوْنَ﴾ فبالسين لأنه وعيد بعذاب مستقبل تظهر فيه تلك الحقيقة يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص655.","url":""}]},{"id":"s4-35","number":35,"surah":4,"verses":[11],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿يُوصِيكُمُ اللَّهُ﴾، دون أن يقال: نوصيكم؟","answer":"إظهار الاسم الجليل يرفع الحكم من عرف الأسرة إلى وصية الله الملزمة، ويورث المهابة والتسليم في موضع تنازع النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص665.","url":""}]},{"id":"s4-36","number":36,"surah":4,"verses":[11],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي أَوْلَادِكُمْ﴾، دون أن يقال: في أبنائكم؟","answer":"الأولاد يشملون الذكور والإناث، بخلاف الأبناء الذي قد يتبادر منه الذكور؛ فاختير اللفظ الأجمع لأصحاب الأنصبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص666.","url":""}]},{"id":"s4-37","number":37,"surah":4,"verses":[11],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ﴾، دون أن يقال: للرجل مثل حظ المرأتين؟","answer":"اختير الذكر والأنثى لأن الحكم متعلق بوصف الجنس لا بسن الرجولة والبلوغ، وجعل نصيبه معيارًا مضاعفًا يختصر صور القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص667.","url":""}]},{"id":"s4-38","number":38,"surah":4,"verses":[11],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فَوْقَ اثْنَتَيْنِ﴾، دون أن يقال: اثنتين فما فوق؟","answer":"عبارة ﴿فَوْقَ اثْنَتَيْنِ﴾ تنص على حكم العدد الزائد على اثنتين، أما حكم البنتين فقد بينته السنة وأُلحق بحكم الأخوات؛ فلا يصح جعل البديل المقترح مساويًا للنص من كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص668.","url":""}]},{"id":"s4-39","number":39,"surah":4,"verses":[11],"verseLabel":"النساء: 11","question":"لماذا ذكر فرض البنت الواحدة صراحة، ولم يذكر فرض الابن الواحد؟","answer":"ذُكر فرض البنت الواحدة لأنها صاحبة فرض مقدر بالنصف، أما الابن الواحد فيأخذ الباقي تعصيبًا بعد أصحاب الفروض، فلا يحتاج إلى نسبة ثابتة تُذكر هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص671.","url":""}]},{"id":"s4-40","number":40,"surah":4,"verses":[11],"verseLabel":"النساء: 11","question":"لماذا توسط قوله: ﴿آبَاؤُكُمْ وَأَبْنَاؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا﴾ تفاصيل الأنصبة؟","answer":"اعترضت الجملة تفاصيل القسمة لترد تقدير الأنصبة إلى علم الله: فالإنسان لا يحيط بمن يكون أنفع له من آبائه وأبنائه، ولذلك لا تُترك المواريث للظن والهوى بل للفرض الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص672.","url":""}]},{"id":"s4-41","number":41,"surah":4,"verses":[11],"verseLabel":"النساء: 11","question":"لماذا ختمت أحكام المواريث هنا بـ﴿إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا﴾؟","answer":"العلم يقرر إحاطة الله بمصالح الوارثين، والحكمة تضع الأنصبة في مواضعها؛ فترد الخاتمة على اعتراض الهوى على القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص673.","url":""}]},{"id":"s4-42","number":42,"surah":4,"verses":[12],"verseLabel":"النساء: 12","question":"لماذا عبر عن الزوجات بلفظ ﴿أَزْوَاجُكُمْ﴾، ولم يقل: زوجاتكم؟","answer":"﴿الزَّوْج﴾ في الاستعمال القرآني يطلق على كل واحد من القرينين، ذكرًا كان أو أنثى؛ فقول ﴿أَزْوَاجُكُمْ﴾ يلحظ رابطة الاقتران نفسها، وهو اللفظ الجاري في القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص681.","url":""}]},{"id":"s4-43","number":43,"surah":4,"verses":[12],"verseLabel":"النساء: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَرَكَ أَزْوَاجُكُمْ﴾، فاستعمل «ما» وأجمل أنواع التركة؟","answer":"﴿مَا﴾ الموصولة تعم كل ما تتركه الزوجات من مال وحق قابل للإرث، من غير حاجة إلى تعداد أنواع التركة؛ فالإجمال هنا يفيد الاستغراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص683.","url":""}]},{"id":"s4-44","number":44,"surah":4,"verses":[12],"verseLabel":"النساء: 12","question":"ما سرّ التعبير في قوله تعالى في ختام التفصيل: ﴿غَيْرَ مُضَارٍّ﴾ بصيغة المفرد؟","answer":"جاء الإفراد في ﴿غَيْرَ مُضَارٍّ﴾ بالنظر إلى الجنس أو إلى كل فرد على حدة، فيواجه كل مخاطب بالحكم مباشرة؛ ولا يعني ذلك نفي تعدد الأفراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص687.","url":""}]},{"id":"s4-45","number":45,"surah":4,"verses":[12],"verseLabel":"النساء: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وَصِيَّةً مِنَ اللَّهِ﴾ بعد أن فصل الأنصبة؟","answer":"﴿وَصِيَّةً مِنَ اللَّهِ﴾ مصدر مؤكد لما تقدم من الأحكام، يقرر أنها عهد مفروض صادر من الله، لا ترتيبًا يملكه الورثة أو يغيرونه بأهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص688.","url":""}]},{"id":"s4-46","number":46,"surah":4,"verses":[12],"verseLabel":"النساء: 12","question":"لماذا ختمت آية المواريث الأولى بـ﴿عَلِيمًا حَكِيمًا﴾، وختمت الثانية بـ﴿عَلِيمٌ حَلِيمٌ﴾؟","answer":"ختمت الآية الأولى بـ﴿عَلِيمًا حَكِيمًا﴾ لأن مقامها تفصيل الأنصبة التي أحاط الله بمصالحها ووضعها مواضعها. وختمت الثانية بـ﴿عَلِيمٌ حَلِيمٌ﴾ بعد النهي عن المضارة في الوصية؛ فهو يعلم قصد المضار ولا يعاجله بالعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص689.","url":""}]},{"id":"s4-47","number":47,"surah":4,"verses":[13,14],"verseLabel":"النساء: 13–14","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ حُدُودُ اللَّهِ﴾ بعد أحكام المواريث؟","answer":"شُبهت الأحكام بحدود تفصل الحق من الباطل، فلا يجوز تجاوزها؛ وفي الإضافة إلى الله تعظيم لحرمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص697.","url":""}]},{"id":"s4-48","number":48,"surah":4,"verses":[13,14],"verseLabel":"النساء: 13–14","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الطائعين: ﴿خَالِدِينَ فِيهَا﴾ بالجمع، وقوله تعالى في العاصي: ﴿خَالِدًا فِيهَا﴾ بالإفراد؟","answer":"جُمع أهل الطاعة لأن طرق الخير وجماعته واسعة، وأفرد العاصي بالنظر إلى كل فرد يواجه تبعة تجاوزه وحده؛ ولا ينفي ذلك تعدد العصاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص703–704.","url":""}]},{"id":"s4-49","number":49,"surah":4,"verses":[13,14],"verseLabel":"النساء: 13–14","question":"ما سرّ التعبير في قوله تعالى عن الجنة: ﴿وَذَلِكَ الْفَوْزُ الْعَظِيمُ﴾، وقال عن النار: ﴿وَلَهُ عَذَابٌ مُهِينٌ﴾؟","answer":"جعل جزاء الطاعة ﴿الْفَوْزَ الْعَظِيمَ﴾ لأنه جمع النجاة ونيل الجنة، وجعل جزاء التعدي ﴿عَذَابًا مُهِينًا﴾ لأن من استكبر عن حدود الله جوزي مع الألم بالإذلال؛ فناسب كل وصف طريق صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص701–703.","url":""}]},{"id":"s4-50","number":50,"surah":4,"verses":[15,16],"verseLabel":"النساء: 15–16","question":"لماذا أسند التوفي إلى الموت في قوله: ﴿حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ﴾؟","answer":"أُسند التوفي إلى الموت مجازًا باعتبار أنه سبب استيفاء الأجل وقبض الروح، فصُوّر الموت كأنه يتولى أخذهن أخذًا تامًا؛ وفيه تشديد لصورة الحبس الممتد إلى نهاية العمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص715.","url":""}]},{"id":"s4-51","number":51,"surah":4,"verses":[15,16],"verseLabel":"النساء: 15–16","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلًا﴾، فنكر «سبيلًا» ولم يبينه؟","answer":"نُكر ﴿سَبِيلًا﴾ لأن الطريق البديل لم يكن قد بُيّن لهم حين نزول الآية؛ فتركه منتظرًا لما يشرعه الله بعد ذلك، ثم بينت السنة حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص716.","url":""}]},{"id":"s4-52","number":52,"surah":4,"verses":[15,16],"verseLabel":"النساء: 15–16","question":"لماذا جمع بين التوبة والإصلاح: ﴿فَإِنْ تَابَا وَأَصْلَحَا فَأَعْرِضُوا عَنْهُمَا﴾؟","answer":"التوبة رجوع عن الذنب وندم عليه، والإصلاح إظهار أثر ذلك الرجوع في السلوك وإزالة ما أفسده العمل؛ فلا يكفي ادعاء التوبة مع البقاء على الحال السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص720.","url":""}]},{"id":"s4-53","number":53,"surah":4,"verses":[15,16],"verseLabel":"النساء: 15–16","question":"لماذا ختمت الآية بـ﴿تَوَّابًا رَحِيمًا﴾، ولم تختم بـ«غفورًا رحيمًا»؟","answer":"التواب كثير القبول لمن رجع بعد الذنب، وهو أدق من الغفور هنا لأن السياق شرط التوبة والإصلاح؛ ثم الرحمة توصل أثر القبول إلى العبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص720–721.","url":""}]},{"id":"s4-54","number":54,"surah":4,"verses":[17,18],"verseLabel":"النساء: 17–18","question":"ما دلالة تعدية التوبة بـ﴿عَلَى﴾ في قوله تعالى: ﴿إِنَّمَا التَّوْبَةُ عَلَى اللَّهِ﴾؟","answer":"﴿على﴾ ليست إلزامًا من غيره، بل وعد أوجبه الله على نفسه تفضلًا وفق حكمته؛ فهي تفيد تحقق القبول لمن استوفى وصف التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص726.","url":""}]},{"id":"s4-55","number":55,"surah":4,"verses":[17,18],"verseLabel":"النساء: 17–18","question":"لماذا وصف أصحاب الذنب بأنهم ﴿يَعْمَلُونَ السُّوءَ بِجَهَالَةٍ﴾؛ أكل ذنب يقع بجهالة؟","answer":"كل معصية جهالة من جهة إيثار اللذة العاجلة على علم العاقبة، ولو عرف صاحبها الحكم؛ فالجهالة هنا سفه العمل لا انعدام المعلومة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص727.","url":""}]},{"id":"s4-56","number":56,"surah":4,"verses":[17,18],"verseLabel":"النساء: 17–18","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ يَتُوبُونَ مِنْ قَرِيبٍ﴾، دون أن يقال: سريعًا؟","answer":"أي قبل حضور الموت، والزمن كله قريب أمام الآخرة؛ واللفظ يحث على المبادرة من غير حصرها في مدة حسابية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص728.","url":""}]},{"id":"s4-57","number":57,"surah":4,"verses":[17,18],"verseLabel":"النساء: 17–18","question":"لماذا قابل بين من يتوب ﴿مِنْ قَرِيبٍ﴾ ومن ينتظر حتى ﴿حَضَرَ أَحَدَهُمُ الْمَوْتُ﴾؟","answer":"قابلت الآيتان المبادرة بالتوبة قبل حضور الموت بتوبة الاضطرار عند معاينته؛ لتبين أن المقبول رجوع اختياري في زمن التكليف، لا كلمة تقال حين ينقطع إمكان العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص734.","url":""}]},{"id":"s4-58","number":58,"surah":4,"verses":[19],"verseLabel":"النساء: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا﴾، فصور معاملة النساء على هيئة ميراث؟","answer":"استعمل فعل ﴿تَرِثُوا﴾ لأن المرأة في الجاهلية كانت تُعامل بعد موت زوجها كأنها جزء من تركته يتصرف فيها الوارث؛ ففضح التعبير هذا التصور وأبطله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص746.","url":""}]},{"id":"s4-59","number":59,"surah":4,"verses":[19],"verseLabel":"النساء: 19","question":"لماذا علق الاستثناء بـ«إن»: ﴿إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ﴾، ولم يقل: إذا أتين؟","answer":"جاءت ﴿إِنْ﴾ لأن وقوع الفاحشة أمر محتمل غير متحقق ولا متوقع من كل زوجة؛ فلا يبنى الاستثناء على صيغة تشعر بتحقق الوقوع مثل ﴿إذا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص752.","url":""}]},{"id":"s4-60","number":60,"surah":4,"verses":[19],"verseLabel":"النساء: 19","question":"لماذا انتقل من كراهية النساء إلى التعبير العام: ﴿فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا﴾؟","answer":"عمم التعبير بقوله ﴿شَيْئًا﴾ ليتجاوز النفور من صفة بعينها إلى قاعدة تربوية: قد يكره المرء جانبًا، ويجعل الله في مجموع الأمر خيرًا كثيرًا لا يراه أولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص756.","url":""}]},{"id":"s4-61","number":61,"surah":4,"verses":[19],"verseLabel":"النساء: 19","question":"لماذا قابل ﴿شَيْئًا﴾ المنكر بـ﴿خَيْرًا كَثِيرًا﴾؟","answer":"قوبل ﴿شَيْئًا﴾ المنكر، وهو ما وقع عليه الكره ولو كان جانبًا محدودًا، بـ﴿خَيْرًا كَثِيرًا﴾؛ لتصغير ما تنفر منه النفس أمام ما قد يقدره الله من منافع واسعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص753.","url":""}]},{"id":"s4-62","number":62,"surah":4,"verses":[20,21,22,23],"verseLabel":"النساء: 20–23","question":"لماذا مثل لأعلى المهر بقوله: ﴿آتَيْتُمْ إِحْدَاهُنَّ قِنْطَارًا﴾؟","answer":"القنطار مثال للمال الكثير؛ فذكره يبلغ بالنهي غايته: حتى لو كان المهر عظيمًا فلا يحل استرداد شيء منه عند استبدال زوجة بأخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص761.","url":""}]},{"id":"s4-63","number":63,"surah":4,"verses":[20,21,22,23],"verseLabel":"النساء: 20–23","question":"لماذا جاء الاستفهام المنكر: ﴿أَتَأْخُذُونَهُ بُهْتَانًا وَإِثْمًا مُبِينًا﴾؟","answer":"الاستفهام إنكار وتعجيب من أخذ المهر بعد الإفضاء والميثاق؛ وسماه ﴿بُهْتَانًا﴾ لما قد يصاحبه من اتهام باطل لتبرير الأخذ، و﴿إِثْمًا مُبِينًا﴾ لوضوح حرمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص763.","url":""}]},{"id":"s4-64","number":64,"surah":4,"verses":[20,21,22,23],"verseLabel":"النساء: 20–23","question":"لماذا وصف الزواج بقوله: ﴿وَأَخَذْنَ مِنْكُمْ مِيثَاقًا غَلِيظًا﴾؛ وكيف تأخذ النساء الميثاق؟","answer":"عقد الزواج عهد مؤكد أحله الله وتترتب عليه حرمة وحقوق عميقة؛ ونُسب الأخذ إلى النساء لأن قبولهن للعقد واستباحة العشرة به يجعلان العهد لهن على الأزواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص772.","url":""}]},{"id":"s4-65","number":65,"surah":4,"verses":[20,21,22,23],"verseLabel":"النساء: 20–23","question":"لماذا زادت هذه الآية ﴿وَمَقْتًا﴾ في قوله: ﴿إِنَّهُ كَانَ فَاحِشَةً وَمَقْتًا وَسَاءَ سَبِيلًا﴾؟","answer":"زاد ﴿وَمَقْتًا﴾ في نكاح ما نكح الآباء لأنه فعل شديد البغض عند الله وعند الطباع السليمة، حتى كان يسمى في الجاهلية نكاح المقت؛ فالقيد يصور خصوص قبحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص784.","url":""}]},{"id":"s4-66","number":66,"surah":4,"verses":[20,21,22,23],"verseLabel":"النساء: 20–23","question":"لماذا وصف الفعل بثلاثة أوصاف متتابعة: ﴿فَاحِشَةً وَمَقْتًا وَسَاءَ سَبِيلًا﴾؟","answer":"﴿فَاحِشَةً﴾ تبين تجاوز الفعل غاية القبح، و﴿مَقْتًا﴾ تبين شدة بغضه، و﴿سَاءَ سَبِيلًا﴾ تذم اتخاذه طريقًا وعادة؛ فاجتمعت بشاعة الفعل وبغضه وسوء مسلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص783.","url":""}]},{"id":"s4-67","number":67,"surah":4,"verses":[20,21,22,23],"verseLabel":"النساء: 20–23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ﴾، فزاد قيد ﴿مِنْ أَصْلَابِكُمْ﴾؟","answer":"القيد يخرج أبناء التبني الذين كانوا يُنزّلون منزلة أبناء النسب في التحريم، ولا يخرج أبناء الرضاع لأن حكمهم ثبت بدليل آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص796.","url":""}]},{"id":"s4-68","number":68,"surah":4,"verses":[20,21,22,23],"verseLabel":"النساء: 20–23","question":"لماذا ختم تعداد المحرمات بقوله: ﴿إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا﴾؟","answer":"جاءت الخاتمة بعد قوله ﴿إِلَّا مَا قَدْ سَلَفَ﴾ لتفتح باب العفو عما وقع قبل التحريم: فالله يغفر لمن انتهى، ويرحمه بعد أن بيّن له حدود النكاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص798.","url":""}]},{"id":"s4-69","number":69,"surah":4,"verses":[24,25],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا اسْتَمْتَعْتُمْ بِهِ مِنْهُنَّ﴾ بـ«ما»، دون أن يقال: فمن استمتعتم بها؟","answer":"﴿مَا﴾ تحتمل الشرطية والموصولة، وفي الحالين تفيد عموم الاستمتاع المأذون به شرعًا الذي يترتب عليه وجوب المهر؛ أما ﴿مَنْ﴾ فكانت ستجعل النظر أولًا إلى ذوات النساء لا إلى الفعل وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص23.","url":""}]},{"id":"s4-70","number":70,"surah":4,"verses":[24,25],"verseLabel":"النساء: 24–25","question":"لماذا سمى المهور هنا ﴿أُجُورَهُنَّ﴾، بينما سماها قبل ذلك ﴿صَدُقَاتِهِنَّ﴾؟","answer":"سميت المهور هنا ﴿أُجُورَهُنَّ﴾ لأن السياق رتب أداءها على عقد النكاح وما أحله من الاستمتاع، فبرز معنى الحق المالي الواجب أداؤه؛ أما ﴿صَدُقَاتِهِنَّ﴾ فتلحظ كون المهر عطية تدل على صدق الرغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص23.","url":""}]},{"id":"s4-71","number":71,"surah":4,"verses":[24,25],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ لَمْ يَسْتَطِعْ مِنْكُمْ طَوْلًا﴾، دون أن يقال: قدرة أو مالًا؟","answer":"الطَّول هو السعة والفضل والقدرة الممتدة، والمراد هنا القدرة المالية على نكاح الحرائر؛ فاللفظ يجمع معنى المال والقدرة التي يتيحها، ولا يقصر العجز على صورة نقدية واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص33.","url":""}]},{"id":"s4-72","number":72,"surah":4,"verses":[24,25],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ فَتَيَاتِكُمُ الْمُؤْمِنَاتِ﴾، واختار «فتياتكم»؟","answer":"الفتاة لفظ ملاطفة يرد للأَمَة كرامتها الإنسانية، وإضافتهن إلى جماعة المؤمنين توثّق أخوة الدين وتمنع الازدراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص37.","url":""}]},{"id":"s4-73","number":73,"surah":4,"verses":[24,25],"verseLabel":"النساء: 24–25","question":"لماذا جمع بين الأوصاف: ﴿مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ وَلَا مُتَّخِذَاتِ أَخْدَانٍ﴾؟","answer":"الإحصان يثبت العفة إيجابًا، ونفي السفاح ينفي العلاقة المعلنة، ونفي الأخدان ينفي العلاقة السرية؛ فاستوعب الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص43.","url":""}]},{"id":"s4-74","number":74,"surah":4,"verses":[24,25],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿فَعَلَيْهِنَّ نِصْفُ مَا عَلَى الْمُحْصَنَاتِ مِنَ الْعَذَابِ﴾، فعبر بـ«ما»؟","answer":"﴿مَا﴾ موصولة تعم مقدار العقوبة التي تجب على المحصنات؛ فالمعنى: عليهن نصف العقاب الثابت عليهن، وجاء البيان صالحًا للحكم من غير إعادة اسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص29.","url":""}]},{"id":"s4-75","number":75,"surah":4,"verses":[24,25],"verseLabel":"النساء: 24–25","question":"لماذا وصف المشقة الجنسية بـ﴿الْعَنَتَ﴾ في قوله: ﴿لِمَنْ خَشِيَ الْعَنَتَ مِنْكُمْ﴾؟","answer":"العنت هو المشقة الشديدة التي توقع صاحبها في الحرج والهلاك، والمراد هنا خشية الوقوع في الزنا وما يجره من إثم وعقوبة؛ فهو أبلغ من مجرد المشقة الجنسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص46.","url":""}]},{"id":"s4-76","number":76,"surah":4,"verses":[5],"verseLabel":"النساء: 25؛ المائدة: 5","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء عن الإماء: ﴿مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ﴾ بصيغة المؤنث، وقوله تعالى في المائدة: ﴿مُحْصِنِينَ غَيْرَ مُسَافِحِينَ﴾ بصيغة المذكر؟","answer":"في النساء الحكم منصب على الإماء اللاتي ينكحن عند العجز، فوصفت حالهن مباشرة بالعفة؛ وفي المائدة الخطاب للرجال الذين أُحلت لهم المحصنات، فحمّلهم هم أيضًا شرط الإحصان ونفي السفاح، فاختلاف الصيغة تابع لجهة التكليف.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص137؛ إسلام ويب، باب النساء: 25.","url":""}]},{"id":"s4-77","number":77,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"لماذا تكرر ﴿يُرِيدُ اللَّهُ﴾ ثلاث مرات متقاربة: أن يبين، وأن يتوب، وأن يخفف؟","answer":"تكرار الإرادة يوزع العناية على ثلاث نعم مستقلة: بيان الحكم، وقبول التوبة، والتخفيف؛ ويثبت أن التشريع رحمة مقصودة لا تكليفًا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص63.","url":""}]},{"id":"s4-78","number":78,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"لماذا قابل بين إرادة الله التوبة وإرادة متبعي الشهوات: ﴿أَنْ تَمِيلُوا مَيْلًا عَظِيمًا﴾؟","answer":"قوبلت إرادة الله التي تتجه إلى التوبة والرحمة بإرادة متبعي الشهوات التي تتجه إلى إمالة المؤمنين عن الاستقامة ميلًا عظيمًا؛ فظهر الفرق بين مقصد التشريع ومقصد الإغواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص63.","url":""}]},{"id":"s4-79","number":79,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"ما الصلة بين قوله: ﴿يُرِيدُ اللَّهُ أَنْ يُخَفِّفَ عَنْكُمْ﴾ وبين ﴿وَخُلِقَ الْإِنْسَانُ ضَعِيفًا﴾؟","answer":"قوله ﴿وَخُلِقَ الْإِنْسَانُ ضَعِيفًا﴾ تعليل لإرادة التخفيف: لما كان الإنسان ضعيفًا أمام التكاليف والشهوات، شرع الله له ما يلائم فطرته وقدرته ولا يوقعه في الحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص65.","url":""}]},{"id":"s4-80","number":80,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ﴾، فسمى مال الآخرين أموالكم؟","answer":"أضاف أموال بعض المخاطبين إلى جماعتهم فقال ﴿أَمْوَالَكُمْ﴾؛ لأن مصالحهم مترابطة، ولأن الاعتداء على مال غيرك اعتداء على أمن الجماعة المالي، وليردع كل واحد عن غيره كما يرتدع عن ماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص72.","url":""}]},{"id":"s4-81","number":81,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"ما دلالة الاستدراك بقوله تعالى: ﴿إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ﴾ بعد النهي عن أكل الأموال بالباطل؟","answer":"الاستثناء منقطع في المعنى: ليست التجارة عن تراض من أكل المال بالباطل، بل هي الطريق المشروع المقابل له. وخصت بالذكر لأنها أبرز صور انتقال الأموال بين الناس بالاختيار والمعاوضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص75.","url":""}]},{"id":"s4-82","number":82,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَقْتُلُوا أَنْفُسَكُمْ﴾، دون أن يقال: لا يقتل بعضكم بعضًا؟","answer":"جعل قتل الآخر قتلًا للنفس لأن المؤمنين كالجسد الواحد، ولأن النهي يشمل قتل الإنسان نفسه وتعريضها للهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص75.","url":""}]},{"id":"s4-83","number":83,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"لماذا جمع بين ﴿عُدْوَانًا وَظُلْمًا﴾؟","answer":"العدوان تجاوز الحد في الفعل، والظلم وضع الحق في غير موضعه وإيقاع الضرر؛ فاجتمع وصف السلوك ووصف أثره وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص79–80.","url":""}]},{"id":"s4-84","number":84,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"لماذا صرح باسم الله في قوله: ﴿وَكَانَ ذَلِكَ عَلَى اللَّهِ يَسِيرًا﴾، ولم يقل: عليه يسيرًا؟","answer":"أظهر الاسم الجليل في ﴿عَلَى اللَّهِ يَسِيرًا﴾ لتستحضر القدرة الإلهية مباشرة ويشتد الوعيد، فلا يعود الضمير إلى معنى بعيد ولا يخف وقع التهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص81.","url":""}]},{"id":"s4-85","number":85,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ﴾ بالبناء للمجهول، دون أن يقال: ما نهاكم الله عنه؟","answer":"بُني ﴿كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ﴾ للمفعول لأن المقام معقود بالفعل ووقوعه لا بتعيين فاعله، أو لأن الفاعل معلوم من السياق؛ فبرز الأثر المقصود من غير تشتيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص82–83.","url":""}]},{"id":"s4-86","number":86,"surah":4,"verses":[26,27,28,29,30,31],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ﴾، دون أن يقال: ذنوبكم؟","answer":"جاءت ﴿سَيِّئَاتِكُمْ﴾ في مقابلة اجتناب الكبائر؛ فالمراد ما دون الكبائر من السيئات التي وعد الله بتكفيرها لمن اجتنب الكبائر، واللفظ يلحظ قبحها مع الوعد بمحو أثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص81.","url":""}]},{"id":"s4-87","number":87,"surah":4,"verses":[26],"verseLabel":"النساء: 26","question":"لماذا رُتبت المقاصد هكذا: ﴿لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ… وَيَتُوبَ عَلَيْكُمْ﴾؛ فقدم البيان ثم الهداية ثم التوبة؟","answer":"بدأ بالبيان لأنه يكشف الأحكام، ثم بالهداية إلى سنن الصالحين للعمل بها، ثم بالتوبة لإزالة أثر التقصير؛ فترتيبها ينتقل من معرفة الطريق إلى سلوكه ثم معالجة الزلل.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031.","url":""}]},{"id":"s4-88","number":88,"surah":4,"verses":[26,27],"verseLabel":"النساء: 26–27","question":"لماذا عُدِّي فعل الإرادة باللام: ﴿يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ﴾، ثم عُدِّي بـ«أن»: ﴿يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ﴾؟","answer":"اللام في ﴿يريد الله ليبين﴾ تُفهم على معنى: يريد تشريع ذلك لأجل أن يبين ويهدي، فتظهر الغاية؛ أما ﴿يريد أن يتوب﴾ فالتوبة نفسها هي المراد المباشر، فدخلت عليها ﴿أن﴾.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031، https://quranpedia.net/note/48031.","url":""}]},{"id":"s4-89","number":89,"surah":4,"verses":[27],"verseLabel":"النساء: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ﴾ فقدم اسم الله، بينما قال قبلها وبعدها: ﴿يُرِيدُ اللَّهُ﴾؟","answer":"قُدم اسم الله في ﴿والله يريد أن يتوب عليكم﴾ لمقابلة إرادته الرحيمة بإرادة متبعي الشهوات في الجملة التالية؛ أما الموضعان الآخران فالمقصود تعداد ما يريده الله من بيان وتخفيف، فجرى الفعل أولًا.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031، https://quranpedia.net/note/48031.","url":""}]},{"id":"s4-90","number":90,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"ما دلالة عموم الخطاب في قوله تعالى: ﴿وَلَا تَتَمَنَّوْا مَا فَضَّلَ اللَّهُ بِهِ بَعْضَكُمْ عَلَى بَعْضٍ﴾ دون تخصيص الرجال أو النساء؟","answer":"جاء ﴿بَعْضَكُمْ عَلَى بَعْضٍ﴾ عامًا ليشمل كل صور التفاوت التي قد تثير التمني والحسد بين الرجال والنساء وبين أفراد الجنس الواحد؛ فالعلاج موجه إلى النفس الإنسانية كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص88.","url":""}]},{"id":"s4-91","number":91,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلرِّجَالِ نَصِيبٌ مِمَّا اكْتَسَبُوا وَلِلنِّسَاءِ نَصِيبٌ مِمَّا اكْتَسَبْنَ﴾، فكرر «نصيب»؟","answer":"تكرار ﴿نَصِيبٌ﴾ يجعل لكل من الرجال والنساء حصة مستقلة مما اكتسب، فلا يذوب حكم أحدهما في الآخر؛ كما يوازن بينهما في ارتباط الجزاء بالسعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص90.","url":""}]},{"id":"s4-92","number":92,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ﴾، وحذف ما يُسأل؟","answer":"حُذف المتعلق في ﴿وَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ﴾ لأن السياق يدل عليه، ولأن تركه يفتح المعنى على كل ما يناسب المقام؛ فالحذف إيجاز وتعميم لا نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص92.","url":""}]},{"id":"s4-93","number":93,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِكُلٍّ جَعَلْنَا مَوَالِيَ﴾، دون أن يقال: ورثة؟","answer":"الموالي هم من تربطهم بالميت ولاية قرابة أو ولاء فيلون أمر ميراثه ويستحقونه؛ فاللفظ أوسع دلالة من لفظ ﴿ورثة﴾ من جهة رابطة القرب والولاية التي نشأ عنها الإرث.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص97.","url":""}]},{"id":"s4-94","number":94,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ﴾، دون أن يقال: الذكور؟","answer":"القوامة قيام مسؤول بالرعاية والإنفاق والحماية، لا إطلاق سلطة؛ وربطتها الآية بالتكليف المالي وبما رتب الله من خصائص، ثم قيدت معالجة النزاع بمراحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص106.","url":""}]},{"id":"s4-95","number":95,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"لماذا اختيرت صيغة المبالغة ﴿قَوَّامُونَ﴾، ولم يقل: قائمون؟","answer":"﴿قَوَّامُونَ﴾ صيغة مبالغة تدل على كثرة القيام بشؤون النساء وتنوعه ودوامه؛ فليست القوامة فعلًا عارضًا، بل مسؤولية مستمرة من رعاية وإنفاق وحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص107.","url":""}]},{"id":"s4-96","number":96,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ﴾، دون أن يقال صراحة: الرجال على النساء؟","answer":"عُدل إلى ﴿بَعْضَهُمْ عَلَى بَعْضٍ﴾ لئلا يفهم تفضيل كل رجل على كل امرأة في كل صفة؛ فقد تفضل امرأة رجلًا في العلم أو العمل. وفيه أيضًا إشعار بأن الفريقين أجزاء مجتمع واحد، وأن التفاضل الوظيفي لمصلحتهما معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص107.","url":""}]},{"id":"s4-97","number":97,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"لماذا رتب علاج النشوز هكذا: الوعظ، ثم الهجر في المضاجع، ثم الضرب؟","answer":"الترتيب ينتقل من الأخف والأقرب إلى الإصلاح الباطن: الوعظ، ثم ضغط عاطفي خاص في المضجع، ثم الإجراء الأخير المنضبط غير المؤذي؛ فلا ينتقل إلى مرحلة مع جدوى ما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص114.","url":""}]},{"id":"s4-98","number":98,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"لماذا ختمت آية القوامة بـ﴿إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا﴾؟","answer":"ختمت الآية بـ﴿عَلِيًّا كَبِيرًا﴾ لتحذر الرجال من البغي بعد طاعة الزوجات: فإن كانت لهم درجة قوامة فالله أعلى منهم وأكبر، وهو القادر على أخذهم بظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص118.","url":""}]},{"id":"s4-99","number":99,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"لماذا عبر عن النزاع الزوجي بقوله: ﴿شِقَاقَ بَيْنِهِمَا﴾؟","answer":"الشقاق من الانشقاق؛ يصور كل زوج في شق مقابل للآخر بعد أن كانا مؤتلفين. وإضافته إلى ﴿بَيْنِهِمَا﴾ توسع الصورة حتى يبدو الخلاف قد ملأ العلاقة الفاصلة بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص127.","url":""}]},{"id":"s4-100","number":100,"surah":4,"verses":[32,33,34,35],"verseLabel":"النساء: 32–35","question":"إلى من يعود الضمير في قوله: ﴿إِنْ يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا﴾، ولماذا جاء محتملًا؟","answer":"يحتمل الضمير في ﴿يُرِيدَا﴾ الحكمين، ويحتمل الزوجين؛ واتساعه يشمل كل من يباشر الإصلاح: فإذا صدقت إرادة الإصلاح من الوسطاء أو الزوجين يسّر الله الوفاق بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص129.","url":""}]},{"id":"s4-101","number":101,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا تكررت الباء مع كل صنف في آية الحقوق: ﴿وَبِالْوَالِدَيْنِ... وَبِذِي الْقُرْبَى...﴾ بخلاف نظيرها في البقرة؟","answer":"كررت الباء مع كل صنف لتتعلق الوصية بالإحسان بكل واحد منهم استقلالًا، فيتجدد الاهتمام عند انتقال الخطاب من حق إلى حق؛ أما آية البقرة فساقت الأصناف في تركيب الميثاق على نسق الإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص141.","url":""}]},{"id":"s4-102","number":102,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا فرق بين ﴿الْجَارِ ذِي الْقُرْبَى﴾ و﴿الْجَارِ الْجُنُبِ﴾؟","answer":"الجار ذو القربى يجمع حق الجوار وحق القرابة، والجار الجنب هو البعيد نسبًا أو دارًا؛ ففرّق التعبير ليقرر تفاوت الأسباب مع ثبوت الإحسان لكليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص141.","url":""}]},{"id":"s4-103","number":103,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"من هو ﴿الصَّاحِبِ بِالْجَنْبِ﴾، ولماذا جاء بهذا التعبير الواسع؟","answer":"﴿الصَّاحِبِ بِالْجَنْبِ﴾ يشمل من لازَم الإنسان في سفر أو دراسة أو عمل، وقيل الزوجة؛ واتساع اللفظ مقصود ليشمل كل صحبة عارضة أو دائمة توجب حسن المعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص141.","url":""}]},{"id":"s4-104","number":104,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا جمع بين ﴿مُخْتَالًا فَخُورًا﴾ من غير حرف عطف بينهما؟","answer":"﴿مُخْتَالًا﴾ يصف الكبر في هيئة النفس والتصرف، و﴿فَخُورًا﴾ يصف إظهاره بالقول والتباهي. وجاء الثاني صفةً تابعة بلا عطف لاتحاد الموصوف وتكامل الصفتين فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص144.","url":""}]},{"id":"s4-105","number":105,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا جمع في وصف البخلاء بين: يبخلون، ويأمرون الناس بالبخل، ويكتمون ما آتاهم الله؟","answer":"جمع بين بخلهم، ودعوتهم غيرهم إليه، وكتمان فضل الله؛ فبدأ بفساد العمل، ثم تعديته إلى الناس، ثم ستر النعمة التي كان ينبغي إظهار أثرها بالشكر والإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص147.","url":""}]},{"id":"s4-106","number":106,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿عَذَابًا مُهِينًا﴾ هنا، دون أن يقال: عذابًا أليمًا؟","answer":"ناسب ﴿مُهِينًا﴾ من اختال وفخر وبخل رياءً وطلب التعاظم؛ فعقوبته لا تقتصر على الألم، بل تكسر الكبر الذي استعلى به على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص151.","url":""}]},{"id":"s4-107","number":107,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا سمى الشيطان ﴿قَرِينًا﴾، ولم يقل: صاحبًا؟","answer":"القرين هو الملازم المقترن بصاحبه حتى كأنه مشدود إليه، وهو أبلغ هنا من مطلق الصاحب؛ لأن الشيطان يداوم إغواء من أعرض عن ذكر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص157.","url":""}]},{"id":"s4-108","number":108,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا تقدم الإنفاق على الإيمان في آية، وتقدم الإيمان على الإنفاق في الآية التالية؟","answer":"في الأولى عُلّق الذم بالإنفاق رياءً فقدم لأنه محل الحديث، ثم كشف فقد الإيمان باعثه. وفي الثانية بدأ بالإيمان لأنه الأصل الذي لو تحقق لأثمر الإنفاق الصادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص158–159.","url":""}]},{"id":"s4-109","number":109,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ﴾، فجمع بين «مثقال» و«ذرة»؟","answer":"﴿مِثْقَالَ﴾ يحدد وزن الشيء ومقداره، و﴿ذَرَّةٍ﴾ تمثل غاية الصغر؛ فاجتماعهما ينفي أن يقع الظلم في أدنى مقدار يمكن وزنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص166.","url":""}]},{"id":"s4-110","number":110,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا﴾، دون أن يقال: من عنده؟","answer":"﴿مِنْ لَدُنْهُ﴾ تدل على قرب الاختصاص وصدور الأجر تفضلًا من خزائن الله مباشرة، فهي أخص من مطلق ﴿من عنده﴾ وأقوى في تشريف العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص168.","url":""}]},{"id":"s4-111","number":111,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا خاطب النبي ﷺ في قوله: ﴿وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا﴾، ولم يقل: وجئنا برسولهم؟","answer":"الخطاب المباشر ﴿بِكَ﴾ يستحضر موقف النبي ﷺ شاهدًا على قومه يوم القيامة ويقرّبه من السامع، بدل الإخبار عنه بلفظ غائب عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص173–174.","url":""}]},{"id":"s4-112","number":112,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿لَوْ تُسَوَّى بِهِمُ الْأَرْضُ﴾، دون أن يقال: لو يسوَّون بالأرض؟","answer":"جعلت الأرض هي التي تُسوّى بهم؛ فالصورة تتمنى أن تنطبق عليهم حتى يندمجوا في ترابها ويختفوا، وهي أبلغ من مجرد مساواتهم بالأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص176–177.","url":""}]},{"id":"s4-113","number":113,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يَكْتُمُونَ اللَّهَ حَدِيثًا﴾، مع ورود ما يدل على كتمانهم في مواضع أخرى؟","answer":"لا يستطيعون كتمان الحديث حين تشهد عليهم الجوارح وتظهر الحقائق، أما ما ورد من كذبهم وكتمانهم ففي موقف سابق من مواقف القيامة؛ فتتعدد الأحوال ولا تتناقض الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص176.","url":""}]},{"id":"s4-114","number":114,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى﴾، دون أن يقال: لا تصلوا؟","answer":"النهي عن القرب أبلغ من النهي عن الفعل؛ لأنه يمنع مقدماته والدخول فيه قبل زوال المانع، فيصون حرمة الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص186.","url":""}]},{"id":"s4-115","number":115,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا جعل الغاية: ﴿حَتَّى تَعْلَمُوا مَا تَقُولُونَ﴾، ولم يقل: ما تفعلون؟","answer":"لأن السكر يفسد الوعي بالكلام، والصلاة قائمة على ذكر وتلاوة ودعاء؛ فجعلت الغاية أن يعي المصلي ما ينطق به، لا مجرد أن يؤدي الحركات.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص187.","url":""}]},{"id":"s4-116","number":116,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا استثنى من الجنابة ﴿إِلَّا عَابِرِي سَبِيلٍ﴾؟","answer":"استثني عابر السبيل لأنه يمر في موضع الصلاة مرورًا من غير مكث، وقيل المراد المسافر الجنب الذي تعذّر عليه الماء؛ وعلى الوجهين روعي العذر العارض مع بقاء حرمة الجنابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص187.","url":""}]},{"id":"s4-117","number":117,"surah":4,"verses":[36,37,38,39,40,41,42,43],"verseLabel":"النساء: 36–43","question":"لماذا ختمت آية الطهارة بـ﴿إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا﴾؟","answer":"جاء ﴿عَفُوًّا غَفُورًا﴾ عقب رخص المرض والسفر وفقد الماء؛ فالعفو يناسب رفع الحرج والتجاوز عن العجز، والمغفرة ستر ما يقع من تقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص190.","url":""}]},{"id":"s4-118","number":118,"surah":4,"verses":[6],"verseLabel":"النساء: 43؛ المائدة: 6","question":"ما سرّ التعبير في قوله تعالى في تيمم النساء: ﴿فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ﴾، وزاد في المائدة: ﴿مِنْهُ﴾؟","answer":"آية المائدة فصّلت أحكام الطهارة ابتداءً، فزاد ﴿منه﴾ ليصرح بأن المسح يكون من الصعيد الطيب؛ أما النساء فجاء ذكر التيمم ضمن النهي عن الصلاة حال اختلال الإدراك، فناسب الإيجاز اعتمادًا على دلالة ﴿صعيدًا طيبًا﴾.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص138؛ إسلام ويب، باب النساء: 43.","url":""}]},{"id":"s4-119","number":119,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا صور اختيارهم الضلالة بالشراء: ﴿يَشْتَرُونَ الضَّلَالَةَ﴾؟","answer":"صوّر اختيارهم الضلالة شراءً؛ لأنهم بذلوا الهدى الذي عرفوه وأخذوا بدله ما يضرهم، فكانت صفقة خاسرة عن قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص197.","url":""}]},{"id":"s4-120","number":120,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُرِيدُونَ أَنْ تَضِلُّوا السَّبِيلَ﴾، دون أن يقال: تضلوا عن السبيل؟","answer":"الفعل ﴿تَضِلُّوا﴾ يتعدى بنفسه بمعنى تخطئوا الطريق أو تفقدوا وجهه؛ فصُوّر السبيل نفسه كأنه الشيء الذي يتيهونه، وهو أبلغ من مجرد الابتعاد عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص200.","url":""}]},{"id":"s4-121","number":121,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا صرح باسم الله مرتين: ﴿وَاللَّهُ أَعْلَمُ بِأَعْدَائِكُمْ وَكَفَى بِاللَّهِ وَلِيًّا﴾؟","answer":"أظهر اسم الله في الجملتين لتستقل كل حقيقة في النفس: علمه بالأعداء، وكفايته وليًا. ثم أعيد في ﴿وَكَفَى بِاللَّهِ﴾ لتعظيم من يتولى المؤمنين ويكفيهم النصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص210.","url":""}]},{"id":"s4-122","number":122,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا جمع بين ﴿وَلِيًّا﴾ و﴿نَصِيرًا﴾؟","answer":"الولي يتولى شؤون المؤمن ويحفظهم بالقرب والرعاية، والنصير يدفع عنهم عدوهم ويعينهم عليه؛ فجمع بين دوام الولاية وعون المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص210.","url":""}]},{"id":"s4-123","number":123,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِهِ﴾، دون أن يقال: يغيرون الكلام؟","answer":"التحريف إمالة الكلام عن وجهه لفظًا أو معنى، فالفعل يصور نقل الدلالة من موضعها المقصود لا مجرد الكذب المنفصل عن النص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص215.","url":""}]},{"id":"s4-124","number":124,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا رتبت أقوالهم هكذا: ﴿سَمِعْنَا وَعَصَيْنَا وَاسْمَعْ غَيْرَ مُسْمَعٍ وَرَاعِنَا﴾؟","answer":"رتبت الأقوال لتكشف تدرج عدوانهم: يعلنون السماع ويقرنونه بالعصيان، ثم يخاطبون الرسول بلفظ يحتمل الدعاء عليه، ثم يلوون ﴿رَاعِنَا﴾ إلى معنى السخرية والطعن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص219.","url":""}]},{"id":"s4-125","number":125,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا سمي تحريفهم ﴿لَيًّا بِأَلْسِنَتِهِمْ﴾؟","answer":"الليّ فتل اللسان وتحريكه بالكلام عن وجهه؛ فصوّر تلاعبهم بالألفاظ ذات الوجهين حتى يسمع المخاطب ظاهرًا ويقصدوا باطنًا مؤذيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص221.","url":""}]},{"id":"s4-126","number":126,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿آمِنُوا بِمَا نَزَّلْنَا مُصَدِّقًا لِمَا مَعَكُمْ﴾، ولم يسم القرآن والتوراة؟","answer":"أبهم الاسمان ووصف الكتابين بقوله ﴿بِمَا نَزَّلْنَا مُصَدِّقًا لِمَا مَعَكُمْ﴾؛ ليجعل وصف التنزيل والتصديق نفسه حجة عليهم، فما معهم يشهد لما نزل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص235.","url":""}]},{"id":"s4-127","number":127,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا هدد بطمس ﴿وُجُوهًا﴾ منكرة، ولم يقل: وجوهكم؟","answer":"العدول عن ﴿وجوهكم﴾ إلى ﴿وُجُوهًا﴾ يجعل الوعيد متوجهًا إلى وجوه غير معينة من جماعتهم، فيوقع الخوف في كل فرد من أن يكون هو المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص237.","url":""}]},{"id":"s4-128","number":128,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"ما سر الصورة في قوله: ﴿نَطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَى أَدْبَارِهَا﴾؟","answer":"الطمس محو معالم الوجه، ثم رده على الدبر يقلب جهة التقدم إلى الوراء؛ فهي صورة حسية لعقوبة تمحو التمييز وتعكس أصحابها، وتلائم إعراضهم عن الحق بعد معرفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص237.","url":""}]},{"id":"s4-129","number":129,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا خيّر الوعيد بين طمس الوجوه وبين اللعن: ﴿أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّا أَصْحَابَ السَّبْتِ﴾؟","answer":"الوعيد يعرض عقوبتين: طمس المعالم وردها إلى الخلف، أو الإبعاد من الرحمة كما أُبعد أصحاب السبت؛ فكلتاهما تناسب انقلابهم عن الحق وتمردهم بعد العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص239.","url":""}]},{"id":"s4-130","number":130,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ﴾، ثم قال: ﴿وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾؛ فلم يذكر المشيئة مع الشرك؟","answer":"الشرك إذا مات صاحبه عليه يهدم أصل التوحيد الذي تُبنى عليه المغفرة، أما ما دونه فداخل تحت المشيئة؛ ولا تنفي الآية قبول توبة المشرك في حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص245.","url":""}]},{"id":"s4-131","number":131,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يُزَكُّونَ أَنْفُسَهُمْ﴾، دون أن يقال: ألم تسمع؟","answer":"﴿أَلَمْ تَرَ﴾ تجعل دعوى تزكيتهم لشهرتها ووضوح بطلانها كأنها مشهد يُرى، فتدعو إلى التعجب منها والإنكار عليها، لا إلى مجرد سماع خبرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص252.","url":""}]},{"id":"s4-132","number":132,"surah":4,"verses":[44,45,46,47,48,49,50],"verseLabel":"النساء: 44–50","question":"لماذا قابل تزكيتهم أنفسهم بقوله: ﴿بَلِ اللَّهُ يُزَكِّي مَنْ يَشَاءُ﴾؟","answer":"﴿بَلْ﴾ تبطل تزكيتهم أنفسهم وتثبت أن التزكية الحق حكم لله وحده؛ فهو العالم بالسرائر، يطهر ويثني على من يشاء وفق علمه، لا وفق الدعاوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص255.","url":""}]},{"id":"s4-133","number":133,"surah":4,"verses":[13,41],"verseLabel":"النساء: 46؛ المائدة: 13، 41","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِهِ﴾، وقوله تعالى في المائدة: ﴿مِنْ بَعْدِ مَوَاضِعِهِ﴾؟","answer":"﴿عن مواضعه﴾ أعم في إمالة الكلام عن وجهه بتأويل أو تبديل، أما ﴿من بعد مواضعه﴾ فتبرز أنهم عرفوا مواضعه الثابتة ثم أبطلوا العمل بها، ولا سيما حكم الرجم؛ فكانت أشد في وصف التحريف عن علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص162، تحت المائدة: 41 في المقارنة بالنساء: 46.","url":""}]},{"id":"s4-134","number":134,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ﴾، واستعمل الإيمان لما هو باطل؟","answer":"استعمل ﴿يُؤْمِنُونَ﴾ تهكمًا وكشفًا للمفارقة: أهل الكتاب الذين كان مقتضى علمهم الإيمان بالوحي جعلوا تصديقهم وخضوعهم للجبت والطاغوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص261.","url":""}]},{"id":"s4-135","number":135,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما دلالة وصفهم الكافرين بقولهم: ﴿هَؤُلَاءِ أَهْدَى مِنَ الَّذِينَ آمَنُوا سَبِيلًا﴾، واختيار لفظ ﴿سَبِيلًا﴾؟","answer":"السبيل هو الطريق الموصل إلى الغاية؛ فادعاؤهم أن عبدة الأوثان أهدى طريقًا من المؤمنين يصور انقلاب موازينهم، إذ سموا طريق الضلال هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص263.","url":""}]},{"id":"s4-136","number":136,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ لَهُمْ نَصِيبٌ مِنَ الْمُلْكِ فَإِذًا لَا يُؤْتُونَ النَّاسَ نَقِيرًا﴾، واختار النقير؟","answer":"النقير هو النقرة الدقيقة في ظهر نواة التمر، فضُرب به المثل في غاية القلة؛ أي لو كان لهم شيء من الملك لمنعهم بخلهم أن يعطوا الناس أدنى قدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص277.","url":""}]},{"id":"s4-137","number":137,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ يَحْسُدُونَ النَّاسَ﴾، دون أن يقال: يحسدون محمدًا ﷺ؟","answer":"عبر بـ﴿النَّاسَ﴾ ليشمل النبي ﷺ ومن آمن معه، وليظهر أن حسدهم تجاوز شخصًا واحدًا إلى الجماعة التي آتاها الله من فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص281.","url":""}]},{"id":"s4-138","number":138,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"لماذا قابل حسدهم بقوله: ﴿فَقَدْ آتَيْنَا آلَ إِبْرَاهِيمَ الْكِتَابَ وَالْحِكْمَةَ وَآتَيْنَاهُمْ مُلْكًا عَظِيمًا﴾؟","answer":"ردت الآية حسدهم بأن النبوة والكتاب والملك سبق أن اجتمعت لآل إبراهيم الذين ينتسبون إليهم؛ فلا وجه لاستنكار فضل الله على محمد ﷺ وآله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص282.","url":""}]},{"id":"s4-139","number":139,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا الْعَذَابَ﴾؟","answer":"﴿كُلَّمَا﴾ تفيد التجدد: كلما احترقت الجلود حتى نضجت بدلت بجلود قابلة للإحساس، وعلل ذلك بـ﴿لِيَذُوقُوا الْعَذَابَ﴾؛ فصورت دوام الألم وتجدد مباشرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص294.","url":""}]},{"id":"s4-140","number":140,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى في نعيم الجنة: ﴿أَزْوَاجٌ مُطَهَّرَةٌ﴾، دون أن يقال: طاهرات؟","answer":"﴿مُطَهَّرَةٌ﴾ تدل على أن التطهير وقع عليها وشملها من كل أذى حسي ومعنوي، أما ﴿طاهرات﴾ فقد تصف ذاتها في جانب واحد؛ فالأولى أبلغ في كمال النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص301.","url":""}]},{"id":"s4-141","number":141,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا﴾، فكرر مادة الظل؟","answer":"﴿ظِلًّا﴾ هو النعيم المظلل، و﴿ظَلِيلًا﴾ تؤكد كثافته ودوامه وكمال الإظلال؛ فاشتقاق الصفة من الموصوف للمبالغة، لا تكرار خالٍ من المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص302.","url":""}]},{"id":"s4-142","number":142,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"لماذا كرر ﴿أَطِيعُوا﴾ مع الله والرسول، ولم يكرره مع ﴿أُولِي الْأَمْرِ﴾؟","answer":"أولو الأمر أصحاب الولاية العلمية أو التنفيذية الذين يقوم بهم نظام الجماعة؛ وطاعتهم تابعة لطاعة الله والرسول، ولذلك لم يُعَد الفعل معها استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص316.","url":""}]},{"id":"s4-143","number":143,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ﴾، فنكر «شيئًا»؟","answer":"نُكرت ﴿شَيْءٍ﴾ في سياق الشرط لتعم أي أمر يقع فيه التنازع، صغيرًا أو كبيرًا؛ فلا يخرج شيء من وجوب رده إلى الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص318.","url":""}]},{"id":"s4-144","number":144,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ﴾، وكيف يكون الرد إلى الله؟","answer":"الرد إلى الله هو الرجوع إلى كتابه، وإلى الرسول الرجوع إليه في حياته وإلى سنته بعد وفاته؛ فالوحي هو الحكم عند التنازع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص319.","url":""}]},{"id":"s4-145","number":145,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"verseLabel":"النساء: 51–59","question":"ما سرّ تقديم ﴿خَيْرٌ﴾ على ﴿وَأَحْسَنُ تَأْوِيلًا﴾؟","answer":"بدأ بـ﴿خَيْرٌ﴾ ليثبت فضل الرد إلى الله والرسول في ذاته، ثم خص أثره فقال ﴿وَأَحْسَنُ تَأْوِيلًا﴾؛ فهو أصلح كذلك في المآل والنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص322.","url":""}]},{"id":"s4-146","number":146,"surah":4,"verses":[2],"verseLabel":"النساء: 55؛ التغابن: 2","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿فَمِنْهُمْ مَنْ آمَنَ بِهِ وَمِنْهُمْ مَنْ صَدَّ عَنْهُ﴾ فقدم المؤمن، بينما قال في التغابن: ﴿فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾ فقدم الكافر؟","answer":"سياق النساء في ذرية إبراهيم وما آتاهم الله، فناسب البدء بمن آمن بذلك الكتاب والنبي؛ أما التغابن فمقام تعداد أحوال عموم البشر والتنبيه على جحود الخلق، فبدأ بالكافر الذي يعالجه السياق ثم ثنّى بالمؤمن.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص140؛ إسلام ويب، باب النساء: 55.","url":""}]},{"id":"s4-147","number":147,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿يَزْعُمُونَ أَنَّهُمْ آمَنُوا﴾، دون أن يقال: يقولون؟","answer":"الزعم قول يغلب استعماله فيما لا تقوم عليه حجة أو يداخله الكذب؛ فاختير ليكشف أن إيمانهم دعوى يناقضها تحاكمهم إلى الطاغوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص324.","url":""}]},{"id":"s4-148","number":148,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿يُرِيدُونَ أَنْ يَتَحَاكَمُوا إِلَى الطَّاغُوتِ﴾ بعد قوله: ﴿وَقَدْ أُمِرُوا أَنْ يَكْفُرُوا بِهِ﴾؟","answer":"المفارقة بين الإرادتين تفضح النفاق: يختارون التحاكم إلى الطاغوت مع أنهم مأمورون بالكفر به؛ فالموصول يكشف تناقض الدعوى مع القصد والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص331.","url":""}]},{"id":"s4-149","number":149,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"لماذا أكد إضلال الشيطان بقوله: ﴿أَنْ يُضِلَّهُمْ ضَلَالًا بَعِيدًا﴾؟","answer":"﴿ضَلَالًا﴾ مصدر يؤكد فعل الإضلال، و﴿بَعِيدًا﴾ يصورهم وقد ابتعدوا غاية البعد عن طريق الرجوع؛ فليس انحرافًا يسيرًا عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص332.","url":""}]},{"id":"s4-150","number":150,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿رَأَيْتَ الْمُنَافِقِينَ يَصُدُّونَ عَنْكَ صُدُودًا﴾، فأعاد المصدر وقال «عنك»؟","answer":"المصدر بعد الفعل يبالغ في وصف الإعراض ويثبته، فكأن الصد صار سمةً كاملة لا حركة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص340.","url":""}]},{"id":"s4-151","number":151,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقُلْ لَهُمْ فِي أَنْفُسِهِمْ قَوْلًا بَلِيغًا﴾؛ كيف يكون القول في أنفسهم؟","answer":"﴿فِي أَنْفُسِهِمْ﴾ أي قولًا يبلغ أعماقهم ويؤثر فيها، أو قل لهم خاليًا بهم ما يردعهم؛ و﴿بَلِيغًا﴾ هو الذي يصل إلى موضع التأثير ويوافق حال المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص353.","url":""}]},{"id":"s4-152","number":152,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ﴾، فاختار الإذن دون الأمر؟","answer":"الإذن هنا بمعنى التمكين والإرادة الشرعية التي بها تجب طاعة الرسول؛ فطاعته ليست سلطة مستقلة عن الله، بل طاعة مأذون بها من مرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص359.","url":""}]},{"id":"s4-153","number":153,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"لماذا جاء القسم على هذه الصورة: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ﴾؟","answer":"افتتح بالقسم ونفي الإيمان لتأكيد أن التحاكم الظاهر لا يكفي حتى يزول الحرج الباطن ويقع التسليم التام.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص365.","url":""}]},{"id":"s4-154","number":154,"surah":4,"verses":[60,61,62,63,64,65],"verseLabel":"النساء: 60–65","question":"لماذا جعل تمام الإيمان في ثلاث مراحل: أن يحكموك، وألا يجدوا حرجًا، وأن يسلموا تسليمًا؟","answer":"بدأ بالتحاكم الظاهر إلى الرسول، ثم نفى الحرج الباطن من حكمه، ثم أثبت التسليم العملي التام؛ فاستوعب قبول المرجع والقلب والتنفيذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص368.","url":""}]},{"id":"s4-155","number":155,"surah":4,"verses":[66,67,68,69,70],"verseLabel":"النساء: 66–70","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ لَدُنَّا أَجْرًا عَظِيمًا﴾، دون أن يقال: من عندنا؟","answer":"﴿مِنْ لَدُنَّا﴾ أخص من ﴿من عندنا﴾، وتوحي بقرب العطاء واختصاصه بالله؛ فناسبت الأجر العظيم الذي يتفضل به على المطيعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص385.","url":""}]},{"id":"s4-156","number":156,"surah":4,"verses":[66,67,68,69,70],"verseLabel":"النساء: 66–70","question":"لماذا رتبت الأصناف هكذا: النبيون، ثم الصديقون، ثم الشهداء، ثم الصالحون؟","answer":"الترتيب من أعلى مراتب الاصطفاء والقدوة إلى من كمل تصديقه، ثم من شهد للحق بنفسه، ثم عموم الصالحين؛ وهو ترتيب منازل صحبة لا انتقاص لمن تأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص401.","url":""}]},{"id":"s4-157","number":157,"surah":4,"verses":[66,67,68,69,70],"verseLabel":"النساء: 66–70","question":"ما سرّ التعبير في قوله تعالى عن جماعة الأصناف: ﴿وَحَسُنَ أُولَئِكَ رَفِيقًا﴾ بالإفراد؟","answer":"﴿رَفِيقًا﴾ مفرد لأنه اسم جنس يشمل الرفقاء المذكورين، أو لأنه حال يلحظ كل واحد منهم رفيقًا؛ فالإفراد يجمع الأصناف في حسن الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص400.","url":""}]},{"id":"s4-158","number":158,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"ما سرّ التعبير في قوله تعالى: ﴿خُذُوا حِذْرَكُمْ﴾؛ وكيف يؤخذ الحذر؟","answer":"صوّر الحذر كأنه سلاح أو متاع يؤخذ ويُحمل؛ ليجعل الاستعداد أمرًا عمليًا ملازمًا، لا مجرد شعور بالخوف في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص411.","url":""}]},{"id":"s4-159","number":159,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"لماذا قابل بين ﴿انْفِرُوا ثُبَاتٍ﴾ و﴿انْفِرُوا جَمِيعًا﴾، فذكر حالتي التفرق والاجتماع؟","answer":"﴿ثُبَاتٍ﴾ جماعات متفرقة تتتابع بحسب الحاجة، و﴿جَمِيعًا﴾ جيشًا مجتمعًا؛ فشمل الأمر خطتي الحركة العسكرية تبعًا للمصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص411.","url":""}]},{"id":"s4-160","number":160,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"لماذا اعترض بقوله: ﴿كَأَنْ لَمْ تَكُنْ بَيْنَكُمْ وَبَيْنَهُ مَوَدَّةٌ﴾؟","answer":"الجملة المعترضة تكشف تناقض المنافق: يتمنى الغنيمة كأن لا رابطة مودة جمعته بالمؤمنين تلزمه بنصرتهم؛ فلا يرى العلاقة إلا من خلال نصيبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص428.","url":""}]},{"id":"s4-161","number":161,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"لماذا سمى مبادلة الدنيا بالآخرة شراء: ﴿يَشْرُونَ الْحَيَاةَ الدُّنْيَا بِالْآخِرَةِ﴾؟","answer":"﴿يَشْرُونَ﴾ هنا بمعنى يبيعون؛ فصوّر بذل الحياة الدنيا في سبيل الآخرة صفقة واعية، ثمنها الفاني وعوضها الثواب الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص431.","url":""}]},{"id":"s4-162","number":162,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"ما سرّ تقديم القتل على الغلبة: ﴿فَيُقْتَلْ أَوْ يَغْلِبْ﴾؟","answer":"قدّم القتل، وهو ما تخشاه النفوس، ليقرر من أول الأمر أنه ليس خسارة في سبيل الله بل أحد طريقَي الأجر؛ ثم عطف الغلبة، فكلا المصيرين موعود بالأجر العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص436.","url":""}]},{"id":"s4-163","number":163,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ هَذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا﴾، دون أن يقال: القرية الظالمة؟","answer":"وصف أهل القرية بالظلم لا القرية نفسها؛ لأن الظلم فعل السكان لا المكان، وفي التصريح بـ﴿أَهْلُهَا﴾ تعيين للمسؤول عن اضطهاد المستضعفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص442.","url":""}]},{"id":"s4-164","number":164,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"لماذا كرر دعاءهم: ﴿وَاجْعَلْ لَنَا مِنْ لَدُنْكَ وَلِيًّا وَاجْعَلْ لَنَا مِنْ لَدُنْكَ نَصِيرًا﴾؟","answer":"كرر ﴿وَاجْعَلْ لَنَا﴾ لأن الولي والنصير حاجتان مستقلتان: الولي يتولى أمرهم ويرعاهم، والنصير يعينهم على الظالمين؛ و﴿مِنْ لَدُنْكَ﴾ تفوض اختيارهما إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص439.","url":""}]},{"id":"s4-165","number":165,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"لماذا قابل بين القتال ﴿فِي سَبِيلِ اللَّهِ﴾ والقتال ﴿فِي سَبِيلِ الطَّاغُوتِ﴾؟","answer":"إضافة السبيل إلى الله تجعل قتال المؤمنين خالصًا لنصرة الحق، وإضافته إلى الطاغوت تكشف أن قتال الكافرين في خدمة الباطل المتجاوز للحد؛ فتقابلت الغايتان قبل تقابل الجيوش.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص447.","url":""}]},{"id":"s4-166","number":166,"surah":4,"verses":[71,72,73,74,75,76],"verseLabel":"النساء: 71–76","question":"لماذا ختم بقوله: ﴿إِنَّ كَيْدَ الشَّيْطَانِ كَانَ ضَعِيفًا﴾، مع ما يبدو من قوة أثره؟","answer":"كيد الشيطان ضعيف في ذاته لأنه لا يملك إلا الوسوسة والتزيين، وإنما يقوى باستجابة أتباعه؛ فإذا واجهه المؤمن بالوحي والثبات انكشف ضعفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص447.","url":""}]},{"id":"s4-167","number":167,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"لماذا كنى عن ترك القتال بقوله: ﴿كُفُّوا أَيْدِيَكُمْ﴾؟","answer":"اليد آلة البطش والقتال، فكنى بكفها عن منع القتال كله؛ والصورة تجعل الأيدي متهيئة للحركة ثم مأمورة بالانقباض حتى يأتي الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص453.","url":""}]},{"id":"s4-168","number":168,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللَّهِ أَوْ أَشَدَّ خَشْيَةً﴾؟","answer":"شبه خشيتهم من الناس بخشية الله، ثم ترقى إلى ﴿أَوْ أَشَدَّ خَشْيَةً﴾؛ ليكشف اضطراب ميزانهم حين عظم في قلوبهم ضرر الناس حتى ساوى أو تجاوز ما يجب لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص455.","url":""}]},{"id":"s4-169","number":169,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"لماذا قابل ﴿مَتَاعُ الدُّنْيَا قَلِيلٌ﴾ بـ﴿وَالْآخِرَةُ خَيْرٌ لِمَنِ اتَّقَى﴾، ولم يقل: كثيرة؟","answer":"لم يقل ﴿كثيرة﴾ لأن تفاضل الآخرة ليس في المقدار وحده؛ بل هي خير في النوع والدوام والعاقبة لمن اتقى، أما الدنيا فمتاع قليل مهما كثر ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص451.","url":""}]},{"id":"s4-170","number":170,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿أَيْنَمَا تَكُونُوا يُدْرِكْكُمُ الْمَوْتُ﴾، فصور الموت كطالب يدركهم؟","answer":"أُسند الإدراك إلى الموت فصُوّر طالبًا يلحق الهارب أينما كان؛ وفي ﴿أَيْنَمَا﴾ استغراق لكل مكان، فلا تنجي منه إقامة ولا فرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص460.","url":""}]},{"id":"s4-171","number":171,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ كُنْتُمْ فِي بُرُوجٍ مُشَيَّدَةٍ﴾؟","answer":"البروج أبنية مرتفعة حصينة، و﴿مُشَيَّدَةٍ﴾ تحتمل المرفوعة أو المحكمة المطلية؛ فاستحضرت أقصى ما يتوهم فيه المنعة ثم نفت أن يحجز عن الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص464.","url":""}]},{"id":"s4-172","number":172,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"ما دلالة نسبتهم الحسنة إلى الله والسيئة إلى الرسول في قولهم: ﴿هَذِهِ مِنْ عِنْدِ اللَّهِ﴾ و﴿هَذِهِ مِنْ عِنْدِكَ﴾؟","answer":"هذه مقالة المنافقين: ينسبون النعمة إلى الله، فإذا أصابتهم شدة تشاءموا بالرسول ﷺ وحملوه تبعتها؛ فكشف النقل اضطرابهم في فهم القدر وتحاملهم على الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص466.","url":""}]},{"id":"s4-173","number":173,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"كيف يجمع القارئ بين ﴿قُلْ كُلٌّ مِنْ عِنْدِ اللَّهِ﴾ ثم ﴿مَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ﴾؟","answer":"﴿كُلٌّ مِنْ عِنْدِ اللَّهِ﴾ من جهة الخلق والتقدير ووقوع الأشياء بمشيئته، و﴿فَمِنْ نَفْسِكَ﴾ من جهة السبب والكسب؛ فالعبد يجلب السيئة بذنبه، والله خالق الأسباب والنتائج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص465.","url":""}]},{"id":"s4-174","number":174,"surah":4,"verses":[77,78,79,80],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا﴾، واختار «حفيظًا» دون «حافظًا»؟","answer":"﴿حَفِيظًا﴾ صيغة تدل على المبالغة والدوام في الحفظ والمراقبة؛ فنفت عن الرسول ﷺ مسؤولية إجبارهم وإحصاء أعمالهم، إذ وظيفته البلاغ وهم محاسبون عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص480–481.","url":""}]},{"id":"s4-175","number":175,"surah":4,"verses":[80],"verseLabel":"النساء: 80","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا﴾، وقوله تعالى في الإسراء: ﴿وَمَا أَرْسَلْنَاكَ عَلَيْهِمْ وَكِيلًا﴾؟","answer":"الحفيظ يراقب الأعمال ويحصيها ليجبر الناس على الطاعة، وهذه ليست وظيفة الرسول؛ والوكيل يتولى أمورهم استقلالًا، فنُفي كل وصف في المقام الذي يناسبه.","sources":[{"label":"فاضل السامرائي، *لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 48657.","url":""}]},{"id":"s4-176","number":176,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"ما سرّ اقتصار المنافقين على كلمة ﴿طَاعَةٌ﴾، دون أن يقولوا: أطعنا؟","answer":"الاسم المفرد ﴿طَاعَةٌ﴾ دعوى مقتضبة تحتمل معنى: أمرنا طاعة؛ فيظهرون بها موافقة ثابتة من غير أن يسندوا إلى أنفسهم فعلًا تحقق، بخلاف ﴿أطعنا﴾ الذي يلتزم وقوع الطاعة منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص486.","url":""}]},{"id":"s4-177","number":177,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"لماذا اختير فعل ﴿بَيَّتَ﴾ لما دبروه ليلًا؟","answer":"التبييت تدبير الأمر ليلًا في خفاء، ثم استعمل لكل ما يضمر ويقرر بعيدًا عن الناس؛ فناسب انقلابهم بعد خروجهم من مجلس الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص488.","url":""}]},{"id":"s4-178","number":178,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ﴾، دون أن يقال: يعلم؟","answer":"الكتابة تزيد على مجرد العلم معنى الإثبات والحفظ للمحاسبة؛ فما يدبرونه ليلًا لا يضيع، بل يسجل عليهم ويواجهون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص489.","url":""}]},{"id":"s4-179","number":179,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"لماذا وصف الاختلاف المفترض في القرآن بأنه ﴿اخْتِلَافًا كَثِيرًا﴾، ولم يقل: اختلافًا فقط؟","answer":"قيد الاختلاف بـ﴿كَثِيرًا﴾ لأن كتابًا طويلًا متعدد الموضوعات لو كان من صنع البشر لظهر فيه تناقض واضطراب كثيران؛ وانتفاء ذلك شاهد على مصدره، ولا يعني إثبات تناقض قليل فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص499.","url":""}]},{"id":"s4-180","number":180,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا جَاءَهُمْ أَمْرٌ مِنَ الْأَمْنِ أَوِ الْخَوْفِ أَذَاعُوا بِهِ﴾، واختار «جاءهم»؟","answer":"﴿جَاءَهُمْ﴾ تصور الخبر وافدًا عليهم قبل التثبت منه، فيبادرون إلى إذاعته سواء حمل أمنًا أو خوفًا؛ فالمشكلة في تلقي كل وارد ونشره بلا رد إلى أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص503.","url":""}]},{"id":"s4-181","number":181,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"لماذا صرح بالرسول في قوله: ﴿وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ﴾، ولم يضمره؟","answer":"أظهر وصف ﴿الرَّسُولِ﴾ بدل الضمير لتذكيرهم بأن الذي يرد إليه الخبر صاحب الرسالة والمرجع المخول بالبيان، فتظهر علة وجوب الرجوع إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص504.","url":""}]},{"id":"s4-182","number":182,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ﴾، واختار صورة الاستنباط؟","answer":"الاستنباط في الأصل استخراج الماء من باطن الأرض، واستعير لاستخراج المعنى الخفي من الخبر بالنظر؛ فليس كل سامع يحسن تقدير عواقبه، وإنما أهل الاستدلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص504.","url":""}]},{"id":"s4-183","number":183,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"لماذا استثنى ﴿إِلَّا قَلِيلًا﴾ في قوله: ﴿لَاتَّبَعْتُمُ الشَّيْطَانَ إِلَّا قَلِيلًا﴾؛ وإلى ماذا يعود الاستثناء؟","answer":"الأقرب أن ﴿إِلَّا قَلِيلًا﴾ استثناء من اتباع الشيطان: فلولا فضل الله ورحمته لاتبعتموه إلا عددًا قليلًا يعصمهم رسوخ الفطرة أو الوحي؛ وفيه بيان سعة المنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص505.","url":""}]},{"id":"s4-184","number":184,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"لماذا أفرد النبي ﷺ بالتكليف: ﴿فَقَاتِلْ فِي سَبِيلِ اللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ﴾؟","answer":"أفرد النبي ﷺ بالتكليف ليبين أن أداءه واجب عليه ولو تخلف غيره، فلا يحمل تبعة تقاعسهم؛ ثم أمره بتحريض المؤمنين ليبعث عزائمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص512.","url":""}]},{"id":"s4-185","number":185,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿عَسَى اللَّهُ أَنْ يَكُفَّ بَأْسَ الَّذِينَ كَفَرُوا﴾، دون أن يقال: أن ينصركم عليهم؟","answer":"كف البأس أوسع من مجرد النصر؛ فقد يتحقق برد قوة العدو ومنع هجومه أو إضعافه، فجعل الغاية حماية المؤمنين من شدته بأي وجه يقدره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص515.","url":""}]},{"id":"s4-186","number":186,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى في الشفاعة الحسنة: ﴿نَصِيبٌ مِنْهَا﴾، وفي السيئة: ﴿كِفْلٌ مِنْهَا﴾؟","answer":"النصيب حصة من الخير تنمو لصاحب الشفاعة الحسنة، أما الكفل فهو مقدار يحمل تبعته كأنه ثقل على صاحبه؛ فناسب كل لفظ أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص519.","url":""}]},{"id":"s4-187","number":187,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"ما سرّ تقديم رد التحية بأحسن على رد مثلها: ﴿فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا﴾؟","answer":"زاد الإحسان في الرد ليصنع السلام مودةً متنامية، وأباح المماثلة حدًا أدنى للعدل؛ فجمع الفضل والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص525–526.","url":""}]},{"id":"s4-188","number":188,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"لماذا انتقل من التحية إلى قوله: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَى يَوْمِ الْقِيَامَةِ﴾؟","answer":"ختمت آية التحية بأن الله يحاسب على كل شيء، ثم قررت الآية التالية وحدانيته وجمعه الخلق للحساب؛ فانتقل من مراقبة العمل اليومي إلى اليوم الذي يستوفى فيه حسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص527.","url":""}]},{"id":"s4-189","number":189,"surah":4,"verses":[81,82,83,84,85,86,87],"verseLabel":"النساء: 81–87","question":"لماذا ختم بقوله: ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ حَدِيثًا﴾، ولم يقل: قولًا؟","answer":"اختير ﴿حَدِيثًا﴾ لأن المقام خبر عن جمع الخلق يوم القيامة؛ والاستفهام ينفي أن يكون أحد أصدق من الله في هذا الخبر أو غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص536.","url":""}]},{"id":"s4-190","number":190,"surah":4,"verses":[122],"verseLabel":"النساء: 87؛ النساء: 122","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آية الجمع: ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ حَدِيثًا﴾، وقوله تعالى في آية الوعد: ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلًا﴾؟","answer":"﴿حديثًا﴾ يلائم خبر جمع الخلق والحساب، فهو نبأ متجدد يُحدَّث به؛ و﴿قيلًا﴾ جاء بعد ﴿وعد الله حقًا﴾ فركز على صدق القول الصادر والوعد الملفوظ، فاختار لكل سياق زاويته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص535–539؛ وج8، ص70–79.","url":""}]},{"id":"s4-191","number":191,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ أَرْكَسَهُمْ بِمَا كَسَبُوا﴾، واختار «أركسهم»؟","answer":"الإركاس الرد والقلب إلى أسفل؛ فصوّرهم وقد رُدوا في النفاق والضلال بسبب ما كسبوه، جزاءً موافقًا لاتجاههم المختار.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص544.","url":""}]},{"id":"s4-192","number":192,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿أَتُرِيدُونَ أَنْ تَهْدُوا مَنْ أَضَلَّ اللَّهُ﴾، فنسب الإضلال إلى الله؟","answer":"نسبة الإضلال إلى الله هنا جزاء على كسبهم وإعراضهم: خذلهم وتركهم لما اختاروا بعد قيام الحجة، فلا يملك البشر هداية من حكم الله بضلاله بسبب عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص546.","url":""}]},{"id":"s4-193","number":193,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَدُّوا لَوْ تَكْفُرُونَ كَمَا كَفَرُوا فَتَكُونُونَ سَوَاءً﴾، وحذف جهة التساوي؟","answer":"حُذف متعلق ﴿سَوَاءً﴾ لأن السياق يبينه ويعممه: يريدون أن تتساووا معهم في الكفر وما يتبعه من الموقف والمصير، فلا يبقى بين الفريقين فرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص556–557.","url":""}]},{"id":"s4-194","number":194,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"لماذا صور ضيقهم عن القتال بقوله: ﴿حَصِرَتْ صُدُورُهُمْ﴾؟","answer":"الحصر ضيق الصدر وانقباضه حتى يعجز عن الإقدام؛ فصوّر نفورهم من قتال المؤمنين أو قومهم كأن صدورهم ضاقت بالفعلين فلم تتسع لأحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص566.","url":""}]},{"id":"s4-195","number":195,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَاتَلُوكُمْ﴾، وحذف مفعول المشيئة؟","answer":"حذف مفعول ﴿شَاءَ﴾ لأن جواب الشرط يفسره: لو شاء الله تسليطهم عليكم لسلطهم فقاتلوكم؛ والحذف يوجز ويجعل المشيئة محيطة بكل تفاصيل ذلك التسليط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص568–569.","url":""}]},{"id":"s4-196","number":196,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"لماذا كرر في وصف الفريق الآخر: ﴿يُرِيدُونَ أَنْ يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ﴾؟","answer":"كرر ﴿يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ﴾ لكشف طلبهم أمنين متعارضين: يظهرون لكل فريق ما يرضيه ليأمنوا جانبه، من غير ولاء صادق لأحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص576.","url":""}]},{"id":"s4-197","number":197,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلَّمَا رُدُّوا إِلَى الْفِتْنَةِ أُرْكِسُوا فِيهَا﴾، واختار «أركسوا» مرة أخرى؟","answer":"تكرار ﴿أُرْكِسُوا﴾ يناسب تكرر رجوعهم إلى الفتنة: كلما دعوا إلى الشرك أو القتال انقلبوا فيه منكسين، فدل على سرعة الانتكاس ورسوخه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص577.","url":""}]},{"id":"s4-198","number":198,"surah":4,"verses":[88,89,90,91],"verseLabel":"النساء: 88–91","question":"لماذا ختم الحكم بقوله: ﴿وَأُولَئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَانًا مُبِينًا﴾؟","answer":"﴿سُلْطَانًا مُبِينًا﴾ حجة واضحة وإذن ظاهر في قتال هذا الفريق بعد تحقق امتناعه من الاعتزال والسلم وكف اليد؛ فالقيد يمنع أن يكون القتال بالظن أو الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص580.","url":""}]},{"id":"s4-199","number":199,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً﴾؛ وكيف استثني الخطأ من القتل المنفي؟","answer":"الاستثناء منقطع أو متصل باعتبار الوقوع: لا يليق بمؤمن أن يتعمد قتل مؤمن، لكن قد يقع منه القتل خطأً؛ فليس الخطأ مستثنى من الإباحة، بل من صورة القتل المنفي قصدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص583.","url":""}]},{"id":"s4-200","number":200,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"لماذا اختير وصف ﴿مُؤْمِنَةٍ﴾ في ﴿تَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ﴾، ولم يقل: مسلمة؟","answer":"وصف الرقبة بـ﴿مُؤْمِنَةٍ﴾ لأن الكفارة قربة يُتقرب بها إلى الله، فتحرير مؤمن يخرجه من الرق إلى حرية تعينه على عبادة الله؛ واللفظ القرآني هنا هو مناط الحكم الشرعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص590.","url":""}]},{"id":"s4-201","number":201,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"لماذا عبر عن الإنسان كله بـ﴿رَقَبَةٍ﴾؟","answer":"الرقبة جزء ملازم لمعنى الاسترقاق، إذ كانت في موضع القيد والملك؛ فأطلقت على الإنسان كله بعلاقة الجزء والكل، وصار تحرير الرقبة تصويرًا لفك الشخص من ربقة العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص592.","url":""}]},{"id":"s4-202","number":202,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"ما سرّ التعبير في قوله تعالى: ﴿وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ﴾ بصيغة اسم المفعول؟","answer":"اسم المفعول ﴿مُسَلَّمَةٌ﴾ يركز على وصول الدية كاملة إلى أهل القتيل بالفعل، لا مجرد وجوبها في الذمة؛ فالمقصود أداء الحق وتمكينهم منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص593.","url":""}]},{"id":"s4-203","number":203,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"لماذا سمى عفو أهل القتيل صدقة: ﴿إِلَّا أَنْ يَصَّدَّقُوا﴾؟","answer":"سمى إسقاط أهل القتيل للدية صدقة لأنه تنازل اختياري عن حق مالي ثابت ابتغاء الأجر؛ فالعفو هنا بذل منهم، لا سقوط للحق من أصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص593.","url":""}]},{"id":"s4-204","number":204,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"لماذا سمى الكفارة ﴿تَوْبَةً مِنَ اللَّهِ﴾؟","answer":"جعل الله الكفارة طريقًا لقبول التوبة ومحو أثر الخطأ، فسماها ﴿تَوْبَةً مِنَ اللَّهِ﴾ أي تشريعًا راجعًا بفضله على العبد، لا أن نفس الفعل غير المقصود معصية عمدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص598.","url":""}]},{"id":"s4-205","number":205,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"لماذا قابل تفصيل قتل الخطأ بإيجاز شديد في قتل العمد؟","answer":"قتل الخطأ يحتاج تفصيل الكفارة والدية لاختلاف الأحوال، أما العمد فمقصده الزجر وبيان فظاعة الجريمة، فاستغنى عن الفروع بسلسلة الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص601.","url":""}]},{"id":"s4-206","number":206,"surah":4,"verses":[92,93],"verseLabel":"النساء: 92–93","question":"لماذا توالت أربعة ألوان من الوعيد للقاتل عمدًا: جهنم، والخلود، والغضب، واللعن، ثم إعداد العذاب؟","answer":"جهنم تبين الدار، والخلود طول المكث، والغضب سخط الله، واللعن الطرد من الرحمة، والعذاب العظيم يجمع شدة الجزاء؛ فتعددت الجهات لتناسب تعمد إزهاق نفس مؤمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص606.","url":""}]},{"id":"s4-207","number":207,"surah":4,"verses":[93],"verseLabel":"النساء: 93","question":"لماذا ختم وعيد قاتل المؤمن بـ﴿وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا﴾، بينما قال في المنافقين والمشركين في الفتح: ﴿وَأَعَدَّ لَهُمْ جَهَنَّمَ﴾؟","answer":"في النساء سُردت عقوبات قاتل المؤمن ثم خُتمت بجنس العذاب العظيم ليضم ما ذُكر وغيره؛ وفي الفتح عُيّنت جهنم للمنافقين والمشركين بعد ذكر ظنهم بالله، فناسب التصريح بالدار المعدة لهم.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 43384.","url":""}]},{"id":"s4-208","number":208,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"لماذا عبر عن السفر للجهاد بقوله: ﴿إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ﴾؟","answer":"الضرب في الأرض كناية عن السير فيها؛ لأن المسافر يضربها بقدمه أو راحلته، وإضافته إلى سبيل الله تقيد الحركة بغاية الجهاد والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص610.","url":""}]},{"id":"s4-209","number":209,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَبَيَّنُوا﴾، دون أن يقال: فتثبتوا؟","answer":"التبين طلب ظهور حقيقة الحال والوصول إلى بيانها، أما التثبت فهو التمهل وعدم العجلة؛ فالتبين يتضمن التثبت ويزيد عليه تحصيل الحكم الواضح قبل الإقدام.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص612.","url":""}]},{"id":"s4-210","number":210,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَامَ﴾، فصور السلام شيئًا يلقى؟","answer":"صوّر إظهار السلام وإبلاغه كشيء يلقى إلى المخاطبين فيبلغهم سريعًا؛ فيدخل فيه لفظ السلام وكل علامة ظاهرة على الانقياد والسلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص614.","url":""}]},{"id":"s4-211","number":211,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿لَسْتَ مُؤْمِنًا﴾، دون أن يقال: لست مسلمًا؟","answer":"نهاهم أن ينفوا عنه الإيمان الذي أظهر علامته، لأن السرائر إلى الله، ولأن الحكم الدنيوي يتعلق بالظاهر؛ فاختيار ﴿مُؤْمِنًا﴾ يغلظ إنكار التسرع في إسقاط حرمة المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص620.","url":""}]},{"id":"s4-212","number":212,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"لماذا سمى متاع الدنيا ﴿عَرَضَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"العَرَض ما يعرض ثم يزول، ومنه المتاع غير الثابت؛ فسميت الغنيمة المطلوبة ﴿عَرَضَ الْحَيَاةِ الدُّنْيَا﴾ تحقيرًا لسرعة فنائها أمام حرمة الدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص616.","url":""}]},{"id":"s4-213","number":213,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"لماذا قابل عرض الدنيا بقوله: ﴿فَعِنْدَ اللَّهِ مَغَانِمُ كَثِيرَةٌ﴾؟","answer":"قابل العرض الزائل بمغانم كثيرة ثابتة عند الله؛ فمن ترك العجلة إلى مال مشتبه عوضه الله رزقًا حلالًا وأجرًا أعظم، فلا يجعل القتل طريقًا إلى غنيمة قريبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص617.","url":""}]},{"id":"s4-214","number":214,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ كُنْتُمْ مِنْ قَبْلُ فَمَنَّ اللَّهُ عَلَيْكُمْ﴾، واختار «منَّ» بدل «أنعم»؟","answer":"المنّة نعمة عظيمة يذكّر المنعم بها ليظهر فضلها؛ فقوله ﴿فَمَنَّ اللَّهُ عَلَيْكُمْ﴾ يستحضر انتقالهم من حال خفيّ أو ضعف إلى ظهور الإيمان والأمن، فيرحموا من كان كحالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص620.","url":""}]},{"id":"s4-215","number":215,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"لماذا كرر الأمر: ﴿فَتَبَيَّنُوا﴾ في أول الآية وآخرها؟","answer":"افتتح الأمر بالتبين قاعدةً قبل الحكم، ثم أعاده بعد تذكيرهم بحالهم الأولى ومغانم الله؛ ليغلق باب التسرع ويجعل التبين نتيجة عملية للموعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص620.","url":""}]},{"id":"s4-216","number":216,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"لماذا ختمت الآية بـ﴿إِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا﴾، ولم يقل: عليمًا؟","answer":"الخبير هو العالم ببواطن الأمور ودقائق الدوافع؛ فناسب مقامًا قد يتستر فيه طلب عرض الدنيا وراء دعوى الجهاد، فأحاط بالعمل ونيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص622.","url":""}]},{"id":"s4-217","number":217,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"لماذا بدأ بالمجاهدين بأموالهم قبل أنفسهم في قوله: ﴿الْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ﴾؟","answer":"قدمت الأموال لأنها عون الجهاد وتجهيزه ومقدمته، ولأن بذلها يقع قبل مباشرة القتال غالبًا؛ ثم جاءت الأنفس التي تبلغ غاية التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص632.","url":""}]},{"id":"s4-218","number":218,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير أولًا بـ﴿دَرَجَةً﴾ ثم بـ﴿دَرَجَاتٍ مِنْهُ﴾ في تفضيل المجاهدين؟","answer":"﴿دَرَجَةً﴾ تثبت أصل المفاضلة بين المجاهدين والقاعدين غير أولي الضرر، ثم فصل الجزاء فجمع ﴿دَرَجَاتٍ﴾ لتعدد منازل الفضل والمغفرة والرحمة التي ينالها المجاهدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص637.","url":""}]},{"id":"s4-219","number":219,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى﴾ مع تفضيل المجاهدين؟","answer":"مع تفضيل المجاهدين لم تسلب الآية القاعدين المؤمنين أصل الخير، فقالت ﴿وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى﴾؛ فجمعت بين إنصاف الفريقين وإظهار مزية الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص635.","url":""}]},{"id":"s4-220","number":220,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ﴾، فأظهر الملائكة وأسند إليهم التوفي؟","answer":"أسند التوفي إلى الملائكة لأنهم المباشرون لقبض الأرواح بأمر الله، وإظهارهم يستحضر مشهد المساءلة عند الموت: ﴿فِيمَ كُنْتُمْ﴾، فيشتد توبيخ القاعدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص646.","url":""}]},{"id":"s4-221","number":221,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"لماذا جمع في وصف عجزهم بين ﴿لَا يَسْتَطِيعُونَ حِيلَةً﴾ و﴿لَا يَهْتَدُونَ سَبِيلًا﴾؟","answer":"﴿لَا يَسْتَطِيعُونَ حِيلَةً﴾ تنفي القدرة على أسباب الخروج، و﴿لَا يَهْتَدُونَ سَبِيلًا﴾ تنفي معرفة الطريق أو وسيلة الوصول؛ فجمع بين عجز القوة وعجز التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص651.","url":""}]},{"id":"s4-222","number":222,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى في عفو الله عنهم: ﴿فَأُولَئِكَ عَسَى اللَّهُ أَنْ يَعْفُوَ عَنْهُمْ﴾ مع تحقق رحمة الله؟","answer":"﴿عَسَى﴾ من الله وعد كريم، لكنها أبقيت بصيغة الرجاء تربيةً للمؤمن ألا يجزم لنفسه بالعفو، وللدلالة على أن أمر النجاة مرده إلى فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص653.","url":""}]},{"id":"s4-223","number":223,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ تقديم ﴿مُرَاغَمًا كَثِيرًا﴾ على ﴿وَسَعَةً﴾ في ثمرات الهجرة؟","answer":"قدم ﴿مُرَاغَمًا كَثِيرًا﴾ لأنه أول ما يلقاه المهاجر من مكان يفلت فيه من سلطان عدوه ويرغم أنفه، ثم عطف ﴿وَسَعَةً﴾ لما يعقب النجاة من سعة رزق ودين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص660.","url":""}]},{"id":"s4-224","number":224,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَخْرُجْ مِنْ بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ﴾، فنسب الهجرة إلى الله والرسول؟","answer":"الهجرة إلى الله قصدٌ إلى طاعته ورضاه، وإلى الرسول قصدٌ إلى نصرته واللحاق بجماعته؛ فنسبت الوجهة إليهما لبيان إخلاص الغاية لا جهة المكان وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص661.","url":""}]},{"id":"s4-225","number":225,"surah":4,"verses":[94,95,96,97,98,99,100],"verseLabel":"النساء: 94–100","question":"ما دلالة قوله تعالى فيمن أدركه الموت في طريق الهجرة: ﴿فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ﴾؟","answer":"﴿وَقَعَ﴾ تفيد ثبوت الأجر وتحققه بمجرد صدق الخروج وإن لم يبلغ المهاجر مقصده، و﴿عَلَى اللَّهِ﴾ وعد أوجبه الله على نفسه تفضلًا لا حقًا يفرضه عليه أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص664.","url":""}]},{"id":"s4-226","number":226,"surah":4,"verses":[101],"verseLabel":"النساء: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تقصروا من الصلاة﴾، دون أن يقال: أن تقصروا الصلاة؟","answer":"دخول ﴿مِنْ﴾ يفيد أن القصر يتناول بعض الصلاة أو بعض صفاتها، لا إسقاط الصلاة كلها؛ فينقص عددها أو هيئتها بحسب حال السفر والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص669–670.","url":""}]},{"id":"s4-227","number":227,"surah":4,"verses":[101],"verseLabel":"النساء: 101","question":"لماذا عُلِّق قصر الصلاة بقوله: ﴿إن خفتم أن يفتنكم الذين كفروا﴾ مع أن القصر يكون في السفر الآمن أيضًا؟","answer":"ذُكر الخوف لأنه الحال التي نزل فيها الحكم وكان أشد اتصالًا بالقصر، لا ليحصر مشروعيته فيه؛ فقد بينت السنة ثبوت قصر السفر في الأمن أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص671–673.","url":""}]},{"id":"s4-228","number":228,"surah":4,"verses":[102],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا كنت فيهم﴾، دون أن يقال: وإذا أقمت فيهم الصلاة؟","answer":"قوله ﴿وَإِذَا كُنْتَ فِيهِمْ﴾ يربط تنظيم صلاة الخوف بحضور القائد الذي يقيمها ويقسم الجماعة طائفتين؛ ثم دل عمل الأمة على أن الحكم باقٍ لمن يقوم مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص680–681.","url":""}]},{"id":"s4-229","number":229,"surah":4,"verses":[102],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿فلتقم طائفة منهم معك﴾ مع أن النبي ﷺ قائم بينهم أصلًا؟","answer":"القيام هنا قيام الطائفة للصلاة مع النبي ﷺ، لا مجرد كونهم واقفين في المكان؛ فالفعل ينقلهم من الحراسة إلى الائتمام المنظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص680–683.","url":""}]},{"id":"s4-230","number":230,"surah":4,"verses":[102],"verseLabel":"النساء: 102","question":"كيف يُؤخذ الحذر في قوله: ﴿وليأخذوا حذرهم وأسلحتهم﴾، ولمَ عطف السلاح عليه؟","answer":"أخذ الحذر تصوير للاستعداد كشيء يُحمل ويلازم صاحبه، والسلاح وسيلته الحسية؛ فالعطف جمع اليقظة والتخطيط مع أداة الدفاع، إذ لا يغني أحدهما عن الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص684–685.","url":""}]},{"id":"s4-231","number":231,"surah":4,"verses":[102],"verseLabel":"النساء: 102","question":"لماذا جمع بين ﴿أسلحتكم﴾ و﴿أمتعتكم﴾ مع أن موطن القتال يوحي بذكر السلاح وحده؟","answer":"ذكر الأسلحة لمنع مباغتة المقاتلين، والأمتعة لأن العدو يطمع كذلك في الزاد والدواب وما تقوم به الحركة؛ فتركهما معًا يحقق له الغارة الشاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص686–688.","url":""}]},{"id":"s4-232","number":232,"surah":4,"verses":[102],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿فيميلون عليكم ميلة واحدة﴾ بالإفراد؟","answer":"الإفراد في ﴿مَيْلَةً وَاحِدَةً﴾ يصور هجومًا واحدًا جامعًا مفاجئًا يستأصل الجماعة قبل أن تستعد، وهو سر حرص العدو على غفلتهم في الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص687–688.","url":""}]},{"id":"s4-233","number":233,"surah":4,"verses":[102],"verseLabel":"النساء: 102","question":"ما سرّ تقديم أذى المطر على المرض في قوله: ﴿إن كان بكم أذى من مطر أو كنتم مرضى﴾؟","answer":"قدم أذى المطر لأنه عارض عام مباشر يجعل حمل السلاح شاقًا على الجماعة، ثم ذكر المرض وهو عذر شخصي؛ فانتقل من السبب الخارجي العام إلى الداخلي الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص688–689.","url":""}]},{"id":"s4-234","number":234,"surah":4,"verses":[103],"verseLabel":"النساء: 103","question":"لماذا جاء الأمر بذكر الله بعد الفراغ من صلاة الخوف مباشرة؟","answer":"لما اقتضت صلاة الخوف حركةً وقصرًا وتناوبًا، أعقبها الأمر بالذكر في كل حال ليبقى اتصال القلب بالله ويستدرك ما قد يفوت من كمال الهيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص697–699.","url":""}]}]);
